window.__CS249R_CHAPTERS__["vol2/08_fleet_orchestration"] = {"key": "vol2/08_fleet_orchestration", "sections": [{"id": "sec-1", "level": 2, "title": "Purpose"}, {"id": "sec-2", "level": 2, "title": "The Scheduling Problem"}, {"id": "sec-3", "level": 2, "title": "Distributed Scheduling Complexity"}, {"id": "sec-4", "level": 3, "title": "Admission, placement, and reconciliation"}, {"id": "sec-5", "level": 3, "title": "Failure as a scheduling input"}, {"id": "sec-6", "level": 2, "title": "Scheduling Objectives and Their Conflicts"}, {"id": "sec-7", "level": 2, "title": "Core Allocation Constraints"}, {"id": "sec-8", "level": 3, "title": "Dominant-resource fairness allocation"}, {"id": "sec-9", "level": 3, "title": "Bin packing"}, {"id": "sec-10", "level": 3, "title": "Gang scheduling"}, {"id": "sec-11", "level": 3, "title": "Deadlock prevention and detection"}, {"id": "sec-12", "level": 3, "title": "Heterogeneous gang scheduling"}, {"id": "sec-13", "level": 2, "title": "Orchestration Paradigms"}, {"id": "sec-14", "level": 3, "title": "Slurm and HPC scheduling heritage"}, {"id": "sec-15", "level": 3, "title": "Kubernetes declarative container orchestration"}, {"id": "sec-16", "level": 3, "title": "Kubernetes ecosystem for ML training"}, {"id": "sec-17", "level": 3, "title": "Paradigm trade-offs and selection criteria"}, {"id": "sec-18", "level": 3, "title": "Hybrid architectures in practice"}, {"id": "sec-19", "level": 2, "title": "Topology-Aware Scheduling"}, {"id": "sec-20", "level": 3, "title": "The topology hierarchy"}, {"id": "sec-21", "level": 3, "title": "Placement algorithms"}, {"id": "sec-22", "level": 3, "title": "Rail-optimized scheduling"}, {"id": "sec-23", "level": 3, "title": "Topology discovery and dynamic adaptation"}, {"id": "sec-24", "level": 2, "title": "Elastic Scheduling"}, {"id": "sec-25", "level": 3, "title": "The scheduler-framework contract"}, {"id": "sec-26", "level": 3, "title": "Scheduler integration"}, {"id": "sec-27", "level": 3, "title": "Elastic scaling policies"}, {"id": "sec-28", "level": 2, "title": "Cost Optimization"}, {"id": "sec-29", "level": 3, "title": "Preemption cost and cascades"}, {"id": "sec-30", "level": 3, "title": "Spot instances and preemptible VMs"}, {"id": "sec-31", "level": 3, "title": "Spot instance strategies for ML training"}, {"id": "sec-32", "level": 3, "title": "Capacity reservation strategies"}, {"id": "sec-33", "level": 3, "title": "Cost-aware scheduling policies"}, {"id": "sec-34", "level": 2, "title": "Custom ML Schedulers"}, {"id": "sec-35", "level": 3, "title": "Duration-agnostic scheduling (Tiresias)"}, {"id": "sec-36", "level": 3, "title": "Iteration-aware scheduling (Gandiva)"}, {"id": "sec-37", "level": 3, "title": "Finish-time fairness (Themis)"}, {"id": "sec-38", "level": 3, "title": "Adaptive resource allocation (Pollux)"}, {"id": "sec-39", "level": 3, "title": "Scheduler comparison framework"}, {"id": "sec-40", "level": 3, "title": "From research to production"}], "html": "<h1 id=\"sec-1\" class=\"cs-h1\">Fleet Orchestration</h1>\n<h2 id=\"sec-1\" class=\"cs-h2\">Purpose</h2>\n<p><em>Why can jobs wait while expensive accelerators sit idle?</em></p>\n<p>A thousand idle accelerators still incur ownership or reservation costs while queued experiments make no progress. More hardware does not resolve that waste when available resources cannot form the groups that pending jobs need. Free devices may be scattered across machines with unsuitable connections, or several jobs may each hold resources while waiting for the rest. On one machine, improving execution usually begins with the work already running. Across a shared fleet, useful progress also depends on which work can start, how long it waits, and what other work its allocation displaces. A short experiment needs a timely result, a long training run needs continuity, and a serving workload needs capacity before requests miss their deadlines. Favoring any one claim without considering the others can leave the fleet busy while delaying the results it exists to produce. Interrupting a job can free capacity, but preserving its state and restoring progress consume time and bandwidth. Waiting for a better placement can accelerate execution while extending completion time. Fair access therefore cannot be judged from device counts alone, and high utilization cannot establish that capacity is being used well. The engineering challenge is to honor these competing claims under changing demand and uncertain resource availability, while keeping the allocation process itself reliable. In C³ terms, orchestration pays coordination overhead to turn compute and communication capacity into useful progress while preserving fairness and latency headroom.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Learning Objectives</div>\n<ul class=\"cs-list\">\n<li>Explain how batch and declarative control planes admit, place, and reconcile allocations under stale state and partial failure</li>\n<li>Apply gang, multi-dimensional fit, and topology constraints before dominant-resource fairness to find allocations a job can run</li>\n<li>Analyze conflicts among throughput, latency, fairness, and cost using slowdown, queueing delay, and ML-specific scheduling signals</li>\n<li>Design topology-aware placements that map tensor-, pipeline-, and data-parallel groups onto NVLink domains and switch tiers</li>\n<li>Design elastic, preemption, and spot policies whose throughput or price gains repay their transition and interruption costs</li>\n<li>Diagnose utilization losses by separating allocated, active, and productive capacity and tracing each gap to its cause</li>\n<li>Evaluate serving-capacity and quota policies that balance serving headroom, team guarantees, and reclaimable borrowed capacity</li>\n</ul>\n</div>\n<h2 id=\"sec-2\" class=\"cs-h2\">The Scheduling Problem</h2>\n<p>&lt;span id=\"sec-fleet-orchestration-introduction\"&gt;&lt;/span&gt;</p>\n<p>Consider two research teams sharing a 1,000-GPU cluster: Team A submits a 512-GPU job that will run for a month, while Team B submits hundreds of 8-GPU experiments that each run for an hour. If the scheduler continually admits whichever jobs fit, Team B's small experiments can indefinitely block Team A's large training run. The scheduling problem is to resolve this conflict among throughput, fairness, and cluster utilization.</p>\n<p>Production traces show that this mix is the normal case rather than a contrived one. In the Kalos cluster that Shanghai AI Laboratory used for language-model development in 2023, <code>[JobSizeMix.single_job_pct_str]</code> of <code>[JobSizeMix.job_count_str]</code> GPU jobs requested a single GPU, yet together they consumed <code>[JobSizeMix.single_time_pct_str]</code> of the cluster's GPU time. Jobs of <code>[JobSizeMix.large_threshold_str]</code> GPUs or more made up <code>[JobSizeMix.large_job_pct_str]</code> of submissions and consumed <code>[JobSizeMix.large_time_pct_str]</code> of GPU time [@hu2024characterization], two distributions that @fig-acme-job-size plots side by side. Counted by jobs, the cluster is a stream of small experiments; counted by GPU-hours, it is a few percent of jobs that hold nearly all the accelerators. A scheduler must serve both views at once, which is why fairness, packing, and preemption policies cannot be judged by either count alone.</p>\n<p>Mechanisms for synchronizing workers efficiently (@sec-collective-communication), partitioning computation across them (@sec-distributed-training-systems), and recovering from hardware failures (@sec-fault-tolerance-reliability) solve the single-job scaling problem. Each of them assumed that the job already held its accelerators. Fault tolerance assumed more than that. Its recovery paths drew on a spare pool deep enough to replace a drained node and on spot capacity whose loss the job could absorb. Neither exists unless something outside the job grants it, holds it in reserve, or takes it back. That something is orchestration, the policy that decides which jobs run, where they run, when one is preempted for another, and how competing demands share the fleet. An allocation decision must hold across unreliable nodes, balance competing fleet objectives, and satisfy each job's feasibility constraints. Only then can platform control planes, topology-aware placement, elastic and cost-aware policies, workload-aware ML schedulers, and serving, multi-tenant, and diagnostic practices turn raw capacity into useful work. Training and serving draw on the same fleet, so the capacity envelope this chapter allocates is the one both depend on; how a serving system spends its share, request by request, is the subject of @sec-inference-scale.</p>\n<p>In the fleet stack (shown in the margin), orchestration occupies the Reliability &amp; Control row of the distribution band, but the infrastructure band beneath it constrains its decisions. The scheduler must account for GPU heterogeneity, NVLink topology, rack power limits, and network bisection bandwidth. When scheduling goes wrong, debugging can require examining all four bands to identify whether the root cause lies in infrastructure (hardware constraints), distribution (algorithm limitations), serving (workload mismatch), or governance (policy misconfiguration). Orchestration connects physical infrastructure to distributed algorithms, translating resource requests into placements that respect both hardware topology and organizational policy.</p>\n<p>Translating those requests into placements grows harder as the fleet and its flagship workloads scale. In a <code>[ClusterEconomicsContext.cluster_size_str]</code>-GPU cluster, a single pretraining run of a GPT-3-class 175B-parameter model [@brown2020language], the running instance of Archetype A (GPT-4/Llama-3) throughout this book, can hold a <code>[ClusterEconomicsContext.gang_job_gpus_str]</code>-GPU allocation for weeks. Because the scaling laws of @sec-vol2-intro-ai-scaling-laws-a043 reward larger models trained on more tokens, each new generation of such runs asks for a larger gang held for longer, so the scheduler's hardest requests keep growing. When enough jobs of that class are queued that together they ask for more GPUs than the cluster holds, alongside thousands of smaller experiments and inference workloads competing for the same pool, naive policies break down. A first-come-first-served policy without backfilling (running smaller jobs in the gaps while a large job waits) or preemption can let large jobs occupy the cluster for weeks, delaying smaller experiments that researchers need to iterate quickly. A fair-share policy that divides capacity without respecting each job's minimum resource bundle can leave many partial allocations and no runnable large job.</p>\n<p>↩ Archetype A and its 175B-parameter running instance are established in @sec-introduction-archetype-gpt4llama3-b02f.</p>\n<p>The economic stakes make these decisions consequential at every scale. A continuously provisioned <code>[ClusterEconomicsContext.cluster_size_str]</code>-GPU cluster, valued at the chapter's cloud-equivalent rate of <code>[ClusterEconomicsContext.gpu_hour_cost_str]</code>, represents <code>[ClusterEconomicsContext.daily_cost_str]</code> per day in capacity, whether the GPUs are computing useful work or sitting idle while jobs wait in a queue. If scheduling inefficiencies leave <code>[ClusterEconomicsContext.idle_pct_str]</code> of GPUs idle, that translates to <code>[ClusterEconomicsContext.daily_waste_str]</code> per day in unused capacity value, or about <code>[ClusterEconomicsContext.annual_waste_str]</code> annually. This share counts only the idle capacity that better scheduling can recover, the gap between a poorly scheduled fleet at <code>[ClusterEconomicsContext.util_low_pct_str]</code> utilization and a well-scheduled one at <code>[ClusterEconomicsContext.util_high_pct_str]</code>. The poorly scheduled fleet idles more of its GPUs than this, and @sec-fleet-orchestration-cost-optimization prices that full idle share.</p>\n<p>Holding useful work per active GPU-hour constant, improving utilization from <code>[ClusterEconomicsContext.util_low_pct_str]</code> to <code>[ClusterEconomicsContext.util_high_pct_str]</code> adds <code>[ClusterEconomicsContext.productive_gpu_gain_str]</code> fully active GPU-equivalents of productive capacity without purchasing additional hardware. That count measures the gain in useful work. Procurement planning asks a different question, namely how much hardware the gain replaces. For that comparison the answer is the gain divided by the <code>[ClusterEconomicsContext.util_low_pct_str]</code> baseline utilization, or <code>[ClusterEconomicsContext.raw_gpu_equivalent_gain_str]</code> raw GPUs, because new GPUs run under the same scheduling policy would also reach only <code>[ClusterEconomicsContext.util_low_pct_str]</code> utilization. Recovered capacity becomes cash savings only when it avoids purchases or billed resource time. Scheduling can therefore increase the useful work delivered by an existing investment, even when the fleet's immediate expenditure remains unchanged.</p>\n<p>Capturing that recoverable capacity depends on workload semantics, rather than an ML-versus-high-performance computing (HPC) boundary, because those semantics determine scheduling flexibility. Rigid synchronous jobs in both domains require a fixed set of co-scheduled ranks, whereas malleable jobs can make progress across a declared range of resource counts. Gang scheduling is the central allocation constraint for a rigid training group: a job configured to require <code>[ClusterEconomicsContext.gang_job_gpus_str]</code> GPUs cannot complete its distributed iterations with only half of them. Malleable data-parallel training can instead vary its replica count at explicit reconfiguration boundaries, but tensor- and pipeline-parallel groups usually retain a rigid base allocation. The scheduler must therefore model each job's minimum viable gang, the smallest set of co-scheduled devices on which it can make progress, and its permitted resize points rather than infer rigidity from the workload's field.</p>\n<p>If gang scheduling determines which resources must be available together, topology awareness via placement groups determines how efficiently they can communicate. Tensor-parallel groups benefit from placement within a high-bandwidth NVLink domain; a placement across slower links must still meet the job's communication budget. Two allocations of the same size can therefore deliver very different useful throughput.</p>\n<p>: <strong>Gang scheduling</strong>: Formalized by @ousterhout1982scheduling for parallel systems, where the \"Ousterhout matrix\" co-schedules related threads across processors in synchronized time slices. In a rigid ML training group, incomplete allocation prevents collective completion, so held resources can remain idle until the missing ranks launch.</p>\n<p>: <strong>Placement group</strong>: A cloud-native abstraction that requests instances be placed within a high-bandwidth, low-latency network domain. For the ML Fleet, placement groups reduce placement scatter and may expose higher network limits than unconstrained placement. They do not guarantee workload-level bisection bandwidth: topology oversubscription, concurrent traffic, routing, and the collective pattern still determine delivered AllReduce bandwidth.</p>\n<p>GPU heterogeneity is the third dimension. Many clusters contain mixtures of A100 and H100 accelerators with different compute throughput and interconnect bandwidth. Their training-throughput ratio depends on the workload, numerical precision, and communication path, so the scheduler needs measured performance and the applicable allocation cost. Memory capacity adds a hard admission test once pools differ in it. The common A100 and H100 variants both carry <code>[ClusterEconomicsContext.h100_mem_gb_str]</code> of high-bandwidth memory (HBM), but smaller-memory variants of the same accelerator and older generations often share the fleet. A job whose working set fits only the larger devices cannot run on the rest at any priority. The debugging example in @sec-fleet-orchestration-debugging returns to exactly such a mixed fleet. The scheduler must match workloads to appropriate hardware based on actual requirements, not user preferences, while maintaining high utilization across heterogeneous pools. When users request specific GPU types out of habit rather than necessity, the mismatch between requested and required resources can leave entire hardware pools idle while queues overflow on preferred hardware.</p>\n<p>Beyond those spatial and hardware constraints, job durations are also uncertain: a training run may converge early and complete in days rather than weeks, hardware failures may abort jobs and return resources at unpredictable times, and hyperparameter searches may terminate unpromising configurations early. In both ML and scientific computing, fixed-step jobs with stable iteration times permit better release-time estimates than jobs whose stopping conditions or execution rates vary. The scheduler must therefore distinguish an estimated completion time from an enforced runtime limit when deciding whether another job can safely use a temporary gap in capacity.</p>\n<p>The interaction between these challenges creates combinatorial complexity. A scheduler must simultaneously handle gang scheduling constraints (atomic allocation), heterogeneous resources (capability matching), topology requirements (NVLink locality for tensor parallelism), priority and fairness policies (organizational equity), preemption decisions (which running jobs to interrupt), and cost optimization (spot vs. on-demand placement). Each dimension constrains the others. A topology-optimal placement may violate fairness policies, a cost-optimal spot placement may violate reliability requirements, and a fairness-driven allocation may fragment resources in ways that prevent gang scheduling. The scheduler therefore does more than pack jobs onto GPUs. It must maintain a consistent, economically useful view of a failing, heterogeneous fleet. At that scale, placement stops being only an optimization problem and becomes a distributed systems problem of keeping state coherent across thousands of machines.</p>\n<h2 id=\"sec-3\" class=\"cs-h2\">Distributed Scheduling Complexity</h2>\n<p>A single-machine scheduler works inside one operating-system boundary, where three properties hold closely enough to design around: it observes resource state directly and consistently, its allocation decisions take effect atomically, and failures are nearly binary (the machine is up or it is down). Device faults and delayed cleanup still occur, but they do not hide behind a network. A cluster scheduler surrenders all three properties. It coordinates independent nodes through delayed messages and uncertain observations, so an authoritative allocation decision does not establish that every node has received or completed it. Several distributed systems problems emerge from that gap.</p>\n<p>Partial failures pose the first challenge. A node can fail between allocation and job start, creating a gap between the scheduler's decision and its effect. The scheduler may successfully allocate 32 GPUs across 4 nodes, only to have one node fail before the job launches. The remaining 24 GPUs sit idle while the scheduler detects the failure, updates its state, and re-plans the allocation. Meanwhile, other jobs that could have used those 24 GPUs have already been placed elsewhere, potentially on suboptimal hardware. Before the first training step, recovery must repair allocation and launch state even though no new model progress exists to restore. Once execution begins, resource recovery must also coordinate with the framework's checkpoint and membership mechanisms.</p>\n<p>Network partitions create a second problem. The scheduler may lose connectivity to a subset of nodes while those nodes continue operating normally. From the scheduler's perspective, their status is uncertain; from the nodes' perspective, jobs may still be running and producing useful work. Reallocating their GPUs risks double allocation if the partition heals while the old work still runs; waiting for reconnection leaves possibly healthy capacity idle. The partition's duration cannot be known in advance, so any fixed timeout is a guess about network behavior that may prove wrong. A timeout can trigger recovery, but it does not prove that the old execution has stopped. Reusing a GPU therefore requires confirmed cleanup or an enforced revocation of the old allocation. Restarting a job on reachable replacement nodes also requires fencing stale attempts from shared outputs. One common form of fencing advances the allocation's generation number, so that node agents and storage reject any work carrying an older one. The recovery policy can choose how long to wait for reconnection, but each choice must preserve exclusive ownership where the workload requires it.</p>\n<p>↩ Epoch fencing and leases during job recovery are established in @sec-fault-tolerance-reliability-reliability-recovery-procedures-002d.</p>\n<p>State inconsistency emerges as a third challenge that compounds the first two. Resource state may differ between the scheduler's view and reality on individual nodes. A GPU the scheduler believes is free may still be cleaning up from a previous job: flushing caches, deallocating device memory, running a zombie process from a failed container, or completing a CUDA driver reset after an error. Conversely, a GPU marked as \"in use\" may have been freed by a job that terminated between heartbeat intervals. The scheduler therefore operates on a model of cluster state that is always slightly stale. The degree of staleness varies across nodes with heartbeat frequency, network latency, and the complexity of cleanup operations.</p>\n<p>Ordering without global time presents the fourth issue. Allocation messages issued before and after a partition can arrive out of order. Logical timestamps, counters that order events without a shared clock, can describe an order, but do not by themselves prevent conflicting ownership. The control plane must serialize conflicting allocation decisions, and the resource manager must reject stale allocation generations before acting on them. Otherwise, an old launch request can revive work after a newer allocation has taken ownership.</p>\n<p>These four challenges echo the CAP theorem of @sec-introduction-cap-theorem-reality-f3b0, under which a partitioned system cannot guarantee both consistency and availability. CAP is a theorem about distributed data systems, not a literal proof about every scheduler, but the analogy draws attention to which allocation decisions remain safe when nodes cannot communicate. Slurm, an HPC workload manager, and Kubernetes, a container orchestration platform, both need authoritative allocation records and mechanisms that reconcile those records with execution. Optimistic concurrency permits schedulers to plan against potentially stale snapshots, then validate proposed changes before committing them. Rejecting a conflicting proposal costs scheduling work; accepting conflicting ownership would violate a different, essential invariant.</p>\n<p>The control-plane tension becomes concrete when the scheduler interacts with the ML framework's own distributed coordination plane during a partition. A scheduler may decide that a subset of nodes is unavailable while workers on those nodes are still blocked inside a collective operation. That state mismatch creates a brief window of conflicting intent: the scheduler wants to recover the allocation, but the training job has not yet converged on a new membership view. Elastic launch mechanisms such as TorchElastic reduce this ambiguity through rendezvous, the step at which workers agree on group membership and ranks. They use heartbeats and re-rendezvous so the framework can either reform a viable worker group or terminate cleanly, which gives the scheduler a clearer recovery signal than an opaque collective timeout [@pytorchElasticDocs; @pytorchRendezvousDocs]. This layered coordination, with scheduler-level policy for coarse allocation and framework-level membership for workers, is the characteristic architecture of production distributed training clusters.</p>\n<h3 id=\"sec-4\" class=\"cs-h3\">Admission, placement, and reconciliation</h3>\n<p>When a single undifferentiated queue mixes quota checks, hardware binding, and crash recovery, operators cannot tell whether a pending job is blocked by team quota, fragmented topology, or a dead node whose lease, a time-limited ownership grant that lapses unless renewed, has not yet expired. A stale retry can also assign the same accelerators to two jobs at once. A scheduler control plane avoids this ambiguity by separating three decisions. <strong>Admission control</strong> decides whether a job may enter the runnable set under quota, priority, gang, and safety constraints. <strong>Placement</strong> binds an admitted job to a feasible set of nodes while accounting for accelerator capability, topology, power, storage, and network capacity. <strong>Reconciliation</strong> compares desired allocations with observed node and job state, then starts, retries, evicts, or fences work until the two agree. Keeping these stages explicit makes it possible to distinguish admission denial from placement failure, while versioned decisions and resource-level enforcement prevent stale observations from authorizing competing owners.</p>\n<p>Control-plane architectures distribute these decisions differently [@hindman2011; @burns2016]. A centralized scheduler serializes admission and placement against one authoritative state, which simplifies conflict handling but concentrates scheduling latency and failure impact. A two-level design offers resources to framework schedulers, gaining policy specialization at the cost of delayed or rejected offers. A shared-state design lets several schedulers plan concurrently against a common state and resolves conflicts through version checks or optimistic concurrency. In every design, reconciliation closes the loop. Node agents must enforce allocation generations and lease validity so that an old decision cannot revive after a newer placement has taken ownership.</p>\n<p>Feasibility also extends beyond free accelerator count. Power-aware admission rejects or delays a placement whose worst-case draw would exceed a rack or facility envelope; relying on average draw risks correlated throttling when colocated jobs enter compute-heavy phases together. I/O-aware placement treats dataset-read and checkpoint-write bandwidth as reservable capacity, so a gang that fits in GPU memory does not start where concurrent input pipelines or checkpoint bursts will saturate the same storage path. These constraints can deliberately leave accelerators idle. The idle capacity is the cost of preserving the power and data-movement budgets required for the admitted jobs to make progress.</p>\n<h3 id=\"sec-5\" class=\"cs-h3\">Failure as a scheduling input</h3>\n<p>A scheduler that allocates 10,000 GPUs as if every granted node will stay healthy until the job finishes will see a multi-thousand-GPU training gang stall every few hours waiting for replacement capacity that was already handed out to other workloads. As @sec-fault-tolerance-reliability-reliability-mathematics-inevitable-failure-93ef established, the fleet failure rate is the per-device rate multiplied by the population (@eq-system-mtbf), so a cluster of ten thousand GPUs loses a device every few hours (@tbl-cluster-mtbf-scaling). Where fault tolerance turns that failure rate into checkpoints, detection, and elastic recovery for a running job, the scheduler must plan for failure in every allocation decision. The scheduler uses two failure rates, one for each decision. It sizes spare capacity and replacement paths from the GPU-only count of devices it must replace. Its estimate of how often a running job is interrupted, by contrast, uses the shorter full-system interval of @sec-fault-tolerance-reliability-reliability-worked-example-cluster-mtbf-calculation-9255, which adds PCIe and network failure domains, because those faults also stop a synchronous job even when no GPU needs replacing.</p>\n<p>The scheduler cannot treat the cluster as a static resource pool where resources, once allocated, remain available until voluntarily released. It must anticipate loss of allocated resources during execution and provide replacement capacity or rescheduling paths. The response depends on the fault and the validity of the surviving state. A transient disruption may permit recovery in place if the execution state remains usable; a persistent hardware failure requires replacement resources. Even a short disruption can force checkpoint recovery if the framework cannot safely continue [@tiwari2015].</p>\n<p>When a node heartbeat is missed, the scheduler faces three recovery policies with different delay and capacity costs. It can wait to see whether the heartbeat resumes, though this delays recovery if the machine has permanently crashed. It can instead begin recovery promptly on replacement resources, provided stale execution is fenced before conflicting work resumes. An intermediate approach marks the node as suspect and prepositions replacement capacity while checking its status; this reduces launch delay if replacement becomes necessary, but holds capacity that could otherwise serve pending work. Whichever policy it picks, reuse of the node's GPUs still waits on the fencing that network partitions require. Historical failure and recovery measurements set how long to wait and how much replacement capacity to hold.</p>\n<p>The recovery-time decomposition of fault tolerance (@eq-recovery-time) shows where scheduler policy intervenes most effectively. Of its detection, restart, load, and warmup terms, the scheduler owns most of $\\JobRestartTime$, the time to allocate replacement resources and launch processes, and that is the term its spare-capacity policy shortens. Waiting longer on a missed heartbeat lengthens $\\FailureDetectionTime$ in exchange for avoiding a needless restart, so the wait is worth extending only while a transient fault remains more likely than a permanent one.</p>\n<p>↪ The same decomposition in scheduler-facing phases (detect, reschedule, reload, and replay of work since the last checkpoint) is developed in @sec-appdx-reliability-foundations-recovery-anatomy.</p>\n<p>These requirements connect the scheduler directly to checkpoint and recovery infrastructure. Scheduling decisions about spare capacity, preemption policies, and elastic training support determine how quickly the system recovers from statistically expected failures. A scheduler that reserves spare capacity or supports elastic recovery can restore throughput much faster than one that requires every failed job to wait for a full fresh allocation and reload. The reserve fraction follows from the measured failure rate and recovery time of the fleet's own workloads. Once the control plane can maintain coherent ownership across admission, placement, reconciliation, and node failures, it still needs an explicit policy objective to decide which competing jobs receive capacity when demand exceeds what the fleet can run at once.</p>\n<p>↩ Failure detection, recovery procedures, and spare pools are established in @sec-fault-tolerance-reliability-reliability-failure-detection-recovery-0f54.</p>\n<h2 id=\"sec-6\" class=\"cs-h2\">Scheduling Objectives and Their Conflicts</h2>\n<p>Giving a large training gang an unbroken allocation for weeks amortizes launch and data-movement overhead, but leaves short interactive debugging jobs waiting hours in the queue. Preempting the large gang so short jobs start immediately burns cluster capacity on checkpoint saves and restarts. Every scheduling policy trades four competing objectives against one another: throughput, fairness, latency, and cost efficiency. Throughput benefits from allocations that sustain useful work and amortize launch, interruption, and data-movement overhead; a large allocation helps only while the job scales effectively. Maintaining fairness demands an equitable distribution of resources across competing tenants to prevent a single dominant project from monopolizing the fleet. Dominant resource fairness [@ghodsi2011] formalizes this balance by equalizing each tenant's largest normalized share across GPUs, CPU, and memory. Reducing queue latency helps short, interactive jobs complete promptly, but aggressive preemption can repeatedly interrupt long-running training. Pursuing cost efficiency introduces different costs for different policies: spot capacity risks interruption, off-peak scheduling delays admission, and dense packing can increase interference. Each policy must be evaluated against useful work completed and the delays it imposes.</p>\n<p>Fairness requires an outcome metric rather than an input quota rule alone. For job $\\JobIndex$, <strong>slowdown</strong> $\\JobSlowdown_j=(\\JobQueueWaitTime_j+\\IsolatedJobRunTime_j)/\\IsolatedJobRunTime_j$ compares its queueing-plus-running time with its isolated runtime $\\IsolatedJobRunTime_j$, assuming the running time is unchanged by sharing. A one-hour job that waits nine hours has $\\JobSlowdown_j=10$, even if its team eventually receives its nominal GPU share. When contention or resizing changes execution time, the numerator must instead use the observed queueing-plus-running duration while the denominator retains the isolated baseline. A scheduler should report the distribution of slowdown by user and job class, together with the age of the oldest pending feasible job. Dominant-share parity detects unequal resource allocation, slowdown exposes unequal delay, and the maximum feasible wait exposes starvation risk. These metrics separate a policy that is fair in allocated GPU-hours from one that is fair in the time users wait to obtain useful results.</p>\n<p>Each of the four objectives, pursued alone, schedules the same pool differently and gives up something the others protect (@fig-fleet-orchestration-scheduling-tradeoffs). Favoring a large unbroken allocation can delay short experiments, while repeatedly admitting short jobs can prevent a large gang from assembling. These conflicts depend on the workload and available capacity; improving one objective does not necessarily worsen every other objective.</p>\n<p>Consider a 64-GPU fine-tuning run of the same 175B-parameter model, a far smaller allocation than its <code>[ClusterEconomicsContext.gang_job_gpus_str]</code>-GPU pretraining run. If it sustains high utilization for days, an uninterrupted allocation amortizes launch overhead across a long execution. Admitting it may nevertheless require draining 64 suitably placed GPUs, delaying smaller experiments. Conversely, repeatedly filling available gaps with short jobs can prevent the large job from assembling its required group. Preemption or resizing can recover flexibility only if the job supports the transition and its cost is acceptable. The policy must therefore compare useful throughput with completion delay for both job classes. In scheduler terminology, those choices often appear as quality-of-service classes: job-priority tiers that decide which objective wins when throughput, latency, fairness, and cost collide.</p>\n<p>Queueing adds a further conflict between utilization and latency, because a fleet run close to full load leaves arriving jobs little spare capacity. In a single-server queue with random arrivals, mean waiting time, expressed as a multiple of the mean job duration, is the product of a load factor $\\ServingUtilization/(1-\\ServingUtilization)$ and a variability factor $(1+\\ServiceTimeVariationCoefficient^2)/2$. Here $\\ServingUtilization$ is offered load relative to service capacity, and $\\ServiceTimeVariationCoefficient$ is the coefficient of variation of job duration. The load factor stays small through moderate load and grows without bound as load approaches capacity, so waiting time bends sharply upward near saturation instead of rising in proportion to utilization. The variability factor scales the whole curve. A queue that mixes minute-long debugging jobs with week-long training runs waits several times longer at the same load than a queue of similar-length jobs. Each added point of utilization therefore costs more waiting time in an ML fleet than in a uniform one. Notebook \\ref{nbk-fleet-orchestration-queuing-theory-gpu-clusters} states the relation formally and prices both factors.</p>\n<p>To isolate the effect of runtime variability, consider an M/G/1 queue with first-come-first-served service. Kendall notation names the queue by its arrival process, service-time distribution, and server count: M for memoryless (Poisson) arrivals, G for a general service-time distribution, and 1 for a single server. Treating a fleet as one server means modeling its aggregate capacity as a single resource that works through one job at a time, with each job's service time equal to its GPU-hours divided by the fleet's GPU count. That mapping ignores gang packing and parallel admission, so it isolates the variability effect rather than predicting a real fleet's wait. Jobs arrive according to a Poisson process $(\\ArrivalRate)$, and independent service times follow a general distribution $(\\Glyph{G})$ with mean $1/\\ServiceRate$ and finite standard deviation $\\ServiceTimeStandardDeviation$. When offered load is below service capacity, the Pollaczek-Khinchine formula gives the steady-state expected waiting time in the queue $(\\QueueWaitTime)$:</p>\n<p>$$ \\frac{\\QueueWaitTime}{1/\\ServiceRate} = \\frac{\\ServingUtilization}{1-\\ServingUtilization} \\cdot \\frac{1+\\ServiceTimeVariationCoefficient^2}{2} $$</p>\n<p>Here, $\\ServingUtilization = \\ArrivalRate/\\ServiceRate$ represents offered load relative to the model's service capacity, $1/\\ServiceRate$ is the average job duration, and $\\ServiceTimeVariationCoefficient= \\ServiceTimeStandardDeviation\\ServiceRate$ is the <strong>coefficient of variation</strong> of job duration. The right-hand side is therefore the waiting time expressed as a multiple of the average job duration; a fleet's measured GPU-busy percentage is not automatically this model's load.</p>\n<p>An exponential service-time distribution provides a reference case, yielding $\\ServiceTimeVariationCoefficient\\approx 1$. A mixed ML queue can have much greater variability when short debugging jobs measured in minutes share capacity with training runs measured in weeks. The representative $\\ServiceTimeVariationCoefficient=3$ calculation in this callout captures that variability without claiming a universal fleet constant. The impact on wait times is multiplicative. For the scheduling argument here, the single-server multiplier is sufficient; @sec-appdx-inference-scale-queuing-theory-batched-inference-bbf0 develops an explicit single-server surrogate for batched serving and explains why multi-server, finite-buffer M/G/c/K systems require additional modeling.</p>\n<p>At <code>[QueuingTheory.rho_pct_str]</code> utilization $(\\ServingUtilization = 0.8)$: with an exponential workload $(\\ServiceTimeVariationCoefficient= 1)$, $\\QueueWaitTime=$ <code>[QueuingTheory.wq_uniform_str]</code> $\\times$ the average job duration. With an illustrative high-variability workload $(\\ServiceTimeVariationCoefficient= 3)$, $\\QueueWaitTime=$ <code>[QueuingTheory.wq_ml_str]</code> $\\times$ the average job duration. In this M/G/1 model, service-time variability multiplies waiting time at the same offered load. The example does not prescribe a universal GPU-utilization threshold or model gang placement directly. It explains why capacity planning needs the service-time distribution and queue-delay objective as well as average load.</p>\n<h2 id=\"sec-7\" class=\"cs-h2\">Core Allocation Constraints</h2>\n<p>Awarding the 64-GPU fine-tuning run its fair share of the cluster delivers zero progress if those GPUs sit on nodes with exhausted host memory, lack the interconnect its parallel layout requires, or arrive only 32 at a time. A scheduling objective can choose only among allocations that a job can actually run. Fairness must be computed across every resource a tenant consumes, a request must fit every dimension of the node that receives it, a rigid group must arrive whole, and the resources each job holds must not block one another. Each of these constraints narrows the feasible set before any objective selects within it.</p>\n<h3 id=\"sec-8\" class=\"cs-h3\">Dominant-resource fairness allocation</h3>\n<p>Equalizing GPU counts alone fails when one tenant's jobs saturate host CPU and memory while another's saturate the network fabric, leaving free GPUs unusable behind exhausted auxiliary resources. Dominant-resource fairness (DRF)} makes a multi-resource entitlement comparable by normalizing each tenant's allocation against fleet capacity and taking its largest share [@ghodsi2011]. Consider the deliberately small cluster in @tbl-fleet-orchestration-drf-allocation: <code>[DrfAllocation.cap_gpu_str]</code> GPUs, <code>[DrfAllocation.cap_cpu_str]</code> CPU cores, <code>[DrfAllocation.cap_mem_str]</code> GB of memory, and <code>[DrfAllocation.cap_net_str]</code> Gb/s of network capacity. Tenant A's replica requires <code>[DrfAllocation.a_gpu_str]</code> GPU, <code>[DrfAllocation.a_cpu_str]</code> cores, <code>[DrfAllocation.a_mem_str]</code> GB, and <code>[DrfAllocation.a_net_str]</code> Gb/s; Tenant B's distributed worker requires <code>[DrfAllocation.b_gpu_str]</code> GPUs, <code>[DrfAllocation.b_cpu_str]</code> cores, <code>[DrfAllocation.b_mem_str]</code> GB, and <code>[DrfAllocation.b_net_str]</code> Gb/s.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Tenant</strong></th><th><strong>Allocation</strong></th><th><strong>GPU share</strong></th><th><strong>CPU share</strong></th><th><strong>Memory share</strong></th><th><strong>Network share</strong></th><th><strong>Dominant share</strong></th></tr></thead><tbody>\n<tr><td>A</td><td><code>[DrfAllocation.count_a_str]</code> replicas</td><td><code>[DrfAllocation.a_gpu_math]</code></td><td><code>[DrfAllocation.a_cpu_math]</code></td><td><code>[DrfAllocation.a_mem_math]</code></td><td><code>[DrfAllocation.a_net_math]</code></td><td><code>[DrfAllocation.dom_a_math]</code></td></tr>\n<tr><td>B</td><td><code>[DrfAllocation.count_b_str]</code> workers</td><td><code>[DrfAllocation.b_gpu_math]</code></td><td><code>[DrfAllocation.b_cpu_math]</code></td><td><code>[DrfAllocation.b_mem_math]</code></td><td><code>[DrfAllocation.b_net_math]</code></td><td><code>[DrfAllocation.dom_b_math]</code></td></tr>\n</tbody></table></div>\n<p>: <strong>Worked DRF Allocation</strong>: Progressive filling gives Tenant A four one-GPU replicas and Tenant B a pair of two-GPU workers. Both tenants reach a dominant share of 0.50 even though their CPU and memory allocations differ. GPUs and network are jointly saturated; CPU and memory remain available but cannot increase either allocation without exceeding a saturated resource. {#tbl-fleet-orchestration-drf-allocation tbl-colwidths=\"[12,19,13,13,14,15,14]\"}</p>\n<p>For tenant $\\TenantIndex$, define its dominant share as $\\DominantShare_i=\\max_\\ResourceTypeIndex(\\TenantResourceAllocation/\\FleetResourceCapacity)$, where $\\TenantResourceAllocation$ is its allocation of resource $\\ResourceTypeIndex$ and $\\FleetResourceCapacity$ is fleet capacity for that resource. The calculation equalizes $\\DominantShare_i$, not every resource share. One A replica raises A's dominant share by <code>[DrfAllocation.a_step_math]</code>; one B worker raises B's by <code>[DrfAllocation.b_step_math]</code>. Progressive filling, which repeatedly gives one more bundle to the tenant with the smaller dominant share until a resource saturates, therefore grants roughly two A replicas for each B worker until both dominant shares reach <code>[DrfAllocation.dom_a_math]</code>. This split is a fair policy target, but it is not yet a feasible placement. If B's two workers form one four-GPU gang, the four GPUs must become available atomically. If tensor parallelism requires one NVLink domain, four free GPUs scattered across nodes do not satisfy the allocation. If the job requires 80 GB HBM accelerators, four incompatible GPUs do not count at all. A production scheduler therefore applies capability, gang, and topology constraints to the feasible set, then uses DRF to choose fairly among allocations that can actually run. The order is not a convenience. Feasibility comes before fairness (principle \\ref{pri-feasibility-before-fairness}) because a fair share of accelerators on which the job cannot run delivers no progress to the tenant who holds it. When no equal-share placement exists, the scheduler should report the constraint causing the deviation rather than silently presenting an infeasible entitlement as service delivered.</p>\n<p>The same resource share has different meaning across the three lighthouse workloads introduced in @sec-vol2-introduction-archetypes:</p>\n<ul class=\"cs-list\">\n<li><strong>Archetype A (GPT-4/Llama-3)</strong> needs a rigid, topology-compatible gang. Fractional allocations below its minimum parallel configuration deliver no progress, so fairness must include maximum feasible wait for a contiguous placement rather than GPU-hours alone.</li>\n<li><strong>Archetype B (DLRM at Scale)</strong> couples accelerator memory to sparse-routing bandwidth. A nominal GPU allocation is infeasible when embedding shards or network capacity cannot follow it, so network and memory must enter the dominant share and placement must protect the serving-latency envelope.</li>\n<li><strong>Archetype C (Federated MobileNet)</strong> schedules participation rather than data-center GPUs. Eligibility filters for power, connectivity, and device capability can systematically exclude parts of the population, so fairness must be audited through participation and outcome rates across device and user groups, not equal device counts in a round.</li>\n</ul>\n<p>The common rule is to define the feasible bundle first and assess fairness over useful progress second. Treating every accelerator or client as interchangeable would conceal the constraint that makes each archetype difficult.</p>\n<h3 id=\"sec-9\" class=\"cs-h3\">Bin packing</h3>\n<p>Even when a cluster has dozens of free GPUs in total, a pending 8-GPU job will sit blocked if previous placements scattered those free GPUs in 1- and 2-GPU remnants across partially occupied nodes. Fitting jobs of varying sizes into fixed-capacity nodes without stranding capacity is an instance of <strong>bin packing</strong>. Because general bin packing is NP-hard, no known algorithm finds optimal solutions in polynomial time. Practical heuristics such as first-fit decreasing and best-fit decreasing offer tractable choices, but their performance depends on job sizes and placement constraints. How much usable capacity a heuristic recovers in a heterogeneous ML fleet has to be measured against that fleet's job mix, because the classical guarantees cover only one-dimensional packing.</p>\n<p>: <strong>Bin packing</strong>: First-fit decreasing has a classical asymptotic $11/9$ approximation ratio for one-dimensional bin packing, with an additive constant in the finite-instance bound. That result does not guarantee the same ratio for ML placement with several resource dimensions, topology constraints, and indivisible gangs. A scheduler must evaluate its heuristic against feasible placements and the stranded capacity it leaves.</p>\n<p>Consider a 64-node cluster with 8 GPUs per node, totaling <code>[FleetFragmentation.total_gpus_str]</code>. If every job requires 6 GPUs within one node, only one such job fits per node, leaving 2 GPUs unused and reducing effective capacity for this workload to <code>[FleetFragmentation.effective_capacity_pct_str]</code>. The remaining 2 GPUs per node cannot be combined across nodes into another feasible six-GPU allocation, although smaller compatible jobs could use them. With a mix of 1-GPU, 3-GPU, and 7-GPU jobs, fragmentation depends on the placement and the pending requests; total free capacity can exceed a waiting job's demand while no individual node has enough space. @Fig-fragmentation-problem maps this stranded capacity across an $8{\\times}8$ allocation grid. Although <code>[FleetFragmentation.snapshot_free_str]</code> slots (<code>[FleetFragmentation.snapshot_free_pct_str]</code> of cluster capacity, dashed white cells) sit idle across nodes 0 through 7, active allocations (J1 through J15) leave every node partially occupied, which blocks a pending 8-GPU job that requires an entire unfragmented node.</p>\n<p>ML placement is a multi-dimensional packing problem. Jobs require GPUs together with CPU cores for data preprocessing, host memory for data loading and augmentation pipelines, local SSD storage for dataset caching, and network bandwidth for gradient synchronization. A job requesting 4 GPUs, 32 CPU cores, and 256 GB of RAM may not fit on a node that has 4 free GPUs but only 16 free CPU cores because other jobs have consumed the host CPU for preprocessing. The scheduler must simultaneously satisfy all resource dimensions, and the job fits only if every dimension has sufficient capacity on the selected node. A bottleneck in any one dimension can therefore strand capacity in the others.</p>\n<p>Locality constraints further restrict placement beyond simple resource availability. A training job may require tensor-parallel groups to remain within NVLink-connected nodes when its communication budget cannot tolerate the lower per-endpoint bandwidth of the external fabric (<code>[FleetFragmentation.nvlink_h100_gb_per_s_str]</code> per direction intra-node vs. <code>[FleetFragmentation.ib_ndr_gb_per_s_str]</code> per port inter-node). On this topology, where NVLink does not connect the nodes, a job requesting \"4 GPUs with NVLink connectivity\" cannot use 2 GPUs from node A and 2 from node B, even if all 4 GPUs are individually available and the total capacity is sufficient. These topology constraints turn resource counts into a placement problem where which specific resources are available matters as much as how many. A capacity-feasible packing must also pass the job's locality constraints.</p>\n<p>Schedulers address fragmentation through several complementary strategies, each targeting a different aspect of the problem. The first, backfill, lets smaller jobs run in the gaps while a large job waits for contiguous resources; @sec-fleet-orchestration-gang-scheduling develops it together with the reservation it must protect and the runtime estimates it depends on. A second strategy, periodic <strong>defragmentation</strong>, migrates or preempts low-priority jobs to consolidate free resources into contiguous blocks, analogous to memory compaction in operating systems. The scheduler identifies nodes where partial allocations leave stranded resources, preempts the jobs occupying those resources, and re-schedules them on nodes where they can be packed more efficiently. The cost includes state transfer and restart, plus replay of work not captured by a valid checkpoint. A graceful checkpoint can preserve recent progress, but still takes time and storage bandwidth. The scheduler must weigh these costs against the benefit of starting large jobs sooner, and low-demand periods reduce the number of competing jobs affected by the move.</p>\n<p>A third strategy, <strong>over-subscription</strong>, admits more demand than a capacity dimension can sustain simultaneously, but only where the resource is divisible and the scheduler can bound interference. Average activity of a GPU's streaming multiprocessors (SMs), its compute units, does not create fractional whole GPUs. A job that reserves device memory, requires an exclusive CUDA context, or belongs to a rigid gang still occupies its assigned device while kernels are idle. Statistical multiplexing can be safe for explicitly shareable CPU, network, storage, or partitioned GPU capacity when tenants have measured, weakly correlated peaks and enforceable limits. It is unsafe to convert 70 percent average GPU utilization into a 1.4$\\times$ device overcommit ratio. Whole-device capacity should instead be recovered through preemption, elastic resizing, or an isolation mechanism such as Multi-Instance GPU (MIG) hardware partitioning or NVIDIA's Multi-Process Service (MPS), which lets several processes' kernels share one device. Either mechanism helps only if the scheduler models its memory, compute, and fault-sharing contract explicitly. Both reappear with the serving workloads they suit best in @sec-fleet-orchestration-resource-isolation.</p>\n<h3 id=\"sec-10\" class=\"cs-h3\">Gang scheduling</h3>\n<p>Where bin packing and device sharing govern how requests fit onto individual nodes in space, distributed training adds a simultaneity constraint in time. Partial allocation of rigid multi-GPU jobs creates a distributed scheduling failure mode in which two jobs each hold half the resources they need and block each other indefinitely while every allocated GPU sits idle. In the left panel of @fig-gang-scheduling-deadlock, jobs J1 and J2 each hold 4 of the 8 GPUs they require, and the whole pool stalls. Atomic gang scheduling (right panel) instead grants J1 all 8 GPUs as one allocation while J2 waits without holding any, which prevents this allocation deadlock.</p>\n<p><em><strong>Gang scheduling</strong></em> is the ML cluster scheduling policy that atomically allocates the resources required by a job's minimum viable execution group, so a rigid group either receives its complete allocation or waits without retaining a partial one.</p>\n<ol class=\"cs-list\">\n<li><strong>Significance</strong>: A rigid synchronous job configured for <code>[ClusterEconomicsContext.gang_job_gpus_str]</code> GPUs but holding only <code>[ClusterEconomicsContext.gang_half_gpus_str]</code> GPUs completes zero training steps, not half as many: each collective stalls until every rank in its communication group arrives, so the held GPUs consume power and capital at zero useful output. Without atomic allocation, two such jobs can each acquire half the cluster and deadlock, both at zero progress while consuming the full cluster's operating cost.</li>\n<li><strong>Distinction</strong>: Unlike a malleable service or parallel job that can make progress across a resource range, rigid synchronous training has step-function utility: the minimum viable gang or nothing. The distinction is a property of the execution graph, not of whether the workload is labeled ML, cloud, or HPC.</li>\n<li><strong>Common pitfall</strong>: A frequent misconception is that priorities or quotas alone solve this. Atomicity must extend to every co-scheduled resource the job needs to make progress (accelerators, high-bandwidth interconnect domains, network capacity for collectives); enforcing it at GPU granularity alone recreates the deadlock one resource layer down.</li>\n</ol>\n<p>↩ Ring and tree AllReduce schedules, each of which completes only after every rank's contribution has been reduced, are established in @sec-communication-collective-operations-collective-operations-allreduce-algorithms-7545.</p>\n<p>The partial-allocation pattern is a hold-and-wait deadlock, and its price is the whole allocation for as long as the cycle persists. At the scale of the chapter's reference workload, two <code>[ClusterEconomicsContext.gang_job_gpus_str]</code>-GPU gangs that have each acquired <code>[ClusterEconomicsContext.gang_held_gpus_str]</code> GPUs from a pool too small to complete either one burn about <code>[ClusterEconomicsContext.gang_idle_burn_str]</code> per hour apiece. The limiting case is two jobs that each request the entire cluster, the example OpenAI used to motivate group admission (war story \\ref{ws-fleet-orchestration-openai-gang-scheduling}). On the <code>[ClusterEconomicsContext.cluster_size_str]</code>-GPU cluster, a deadlock that strands every device wastes <code>[ClusterEconomicsContext.cluster_hourly_cost_str]</code> per hour at the chapter's rate while producing no progress for either job. Measured against the stake computed at the start of the chapter, raising utilization from <code>[ClusterEconomicsContext.util_low_pct_str]</code> to <code>[ClusterEconomicsContext.util_high_pct_str]</code> recovers about <code>[ClusterEconomicsContext.daily_gain_str]</code> per day in equivalent capacity value. About <code>[ClusterEconomicsContext.deadlock_hours_str]</code> hours of such a deadlock therefore erase a full day of that gain. Gang scheduling does not create the gain, but it protects it. For a rigid job $\\RigidGangJob$ requiring $\\DeviceCount$ GPUs, the scheduler must grant all $\\DeviceCount$ GPUs atomically or leave the job queued without a partial allocation. This all-or-nothing rule removes hold-and-wait for the resources covered by that allocation; it does not prevent later deadlocks in application code or auxiliary resources.</p>\n<p>: <strong>Hold-and-wait</strong>: One of the four Coffman conditions (mutual exclusion, hold-and-wait, no preemption, and circular wait), all of which must hold for deadlock to occur [@coffman1971]. Gang scheduling removes hold-and-wait through atomic allocation, which is why it prevents this deadlock by construction; the price is reduced packing flexibility.</p>\n<p>Naive gang scheduling is wasteful in predictable ways. Atomic allocation means the waiting job holds nothing, yet a large gang will never assemble if every freed GPU goes to a smaller job. The scheduler therefore places a <strong>reservation</strong> for the job at the head of the queue, draining capacity toward it by declining to start new work on GPUs that the gang will need. If the cluster has <code>[ClusterEconomicsContext.gang_held_gpus_str]</code> free GPUs and that job requests <code>[ClusterEconomicsContext.gang_job_gpus_str]</code>, the reservation keeps the <code>[ClusterEconomicsContext.gang_held_gpus_str]</code> GPUs idle until <code>[ClusterEconomicsContext.gang_missing_gpus_str]</code> more become available, potentially wasting thousands of GPU-hours. Backfill scheduling addresses this by identifying jobs in the queue that can fit within the <code>[ClusterEconomicsContext.gang_held_gpus_str]</code> available GPUs without delaying the large job's expected start time (@fig-fleet-orchestration-backfill-reservation), an idea popularized in the ANL/IBM SP scheduling system [@lifka1995anlibm]. A 128-GPU job with an estimated runtime of 2 hours is a backfill candidate if the <code>[ClusterEconomicsContext.gang_missing_gpus_str]</code> additional GPUs needed by the large job will remain unavailable for at least 2 hours. Protecting the reservation requires an enforced runtime bound or a preemption contract that releases the backfill allocation in time, including any checkpoint and cleanup delay. The estimate identifies an opportunity; the release contract makes the reservation enforceable.</p>\n<p>The accuracy of runtime estimates determines backfill effectiveness, and this creates a game-theoretic challenge. If users overestimate runtimes, fewer jobs appear to fit a backfill window. If they underestimate, the scheduler may need to preempt a backfilled job to honor the reservation, paying recovery costs and losing unsaved progress. A policy that kills jobs at their declared limit encourages conservative estimates. Tiresias [@gu2019tiresias], discussed in @sec-fleet-orchestration-tiresias, avoids duration estimates when setting priority by using observed resource consumption. That choice addresses ordering under uncertainty, while reservation protection still needs an enforced runtime bound or release contract that says when a backfilled job will give its capacity back.</p>\n<h3 id=\"sec-11\" class=\"cs-h3\">Deadlock prevention and detection</h3>\n<p>Gang scheduling eliminates the hold-and-wait condition for the atomically allocated bundle, but it does not immunize the cluster against all forms of resource contention. Later requests for auxiliary resources can still create a cycle of dependencies. Priority rules can also prevent a resource holder from making progress without creating a cycle. Distinguishing these cases matters because breaking a deadlock and providing a starved job with enough resources to exit require different interventions.</p>\n<p>Priority inversion occurs when a high-priority job waits on a low-priority resource holder whose progress other work delays. Consider the 64-GPU fine-tuning run of the 175B-parameter model, submitted at high priority. The scheduler has reserved 60 available GPUs, but the remaining 4 are held by a low-priority data processing job. Normally, the scheduler would preempt the low-priority job to satisfy the high-priority request. However, if a stream of medium-priority development jobs saturates the cluster's CPU or network bandwidth, starving the low-priority job of the resources it needs to checkpoint and exit, the low-priority job stalls. Its graceful release path cannot complete. The high-priority job waits for the low-priority job, which is effectively blocked by the medium-priority jobs. The 60-GPU idle block persists until the exit path receives resources or an enforced termination policy reclaims the remaining GPUs, potentially losing uncheckpointed work.</p>\n<p><em><strong>Priority inversion</strong></em> is an ML cluster scheduling pathology in which a high-priority task is forced to wait for a lower-priority task to release a shared resource.</p>\n<ol class=\"cs-list\">\n<li><strong>Significance</strong>: It ties the progress of a high-priority job, and the accelerators reserved for it, to the progress of the lowest-priority job in the wait-for chain. In ML clusters, this typically occurs when a low-priority job holding GPUs is starved of auxiliary resources (for example, bandwidth for checkpointing), preventing it from finishing and releasing the accelerators needed by high-priority workloads.</li>\n<li><strong>Distinction</strong>: Unlike standard queuing (where tasks wait their turn), priority inversion involves an active blockage: the high-priority task is ready to run but is transitively dependent on a task that the scheduler does not prioritize.</li>\n<li><strong>Common pitfall</strong>: A frequent misconception is that strict priority levels solve this. Raising the waiting job's priority does not supply the CPU or bandwidth that its lower-priority resource holder needs to exit; the preemption policy must protect that release path.</li>\n</ol>\n<p>Prevention and detection address different parts of this problem. Atomic allocation prevents hold-and-wait for the resources included in the gang, while reserving checkpoint bandwidth allows a preempted job to complete its exit path. Timeouts instead bound how long the system waits before investigating or reclaiming an allocation; they do not prevent deadlock states from arising. Monitoring can trigger recovery when progress stops, but safe reclamation still requires enforcing the new ownership decision.</p>\n<p>Detection, unlike exact placement search, is computationally cheap. Before feasibility filtering, a cluster with 10,000 GPUs and 500 pending jobs can have more than $10^{15}$ candidate allocations, which puts exhaustive allocation search out of reach. Detection instead works on a <strong>wait-for graph</strong>, a directed graph with one vertex per job and an edge from job A to job B whenever A waits for a resource that B holds. A cycle identifies a potential deadlock. It establishes deadlock when every edge is an unavoidable blocking dependency and no alternative resource allocation can let a member proceed. Finding a cycle in an already constructed graph takes time linear in its vertices and edges. The difficulty lies in construction. Resource state changes continuously across a distributed control plane, so the scheduler rarely holds a complete, current graph, and a cycle detected on stale state may already have resolved while a real one goes unseen.</p>\n<p>Large-scale schedulers therefore supplement wait-for detection with mechanisms that preserve liveness under incomplete state. A <strong>lease-based resource</strong> gives every allocation a time-to-live; expiry authorizes reclamation only when the resource manager enforces revocation and cleanup before reuse. <strong>Progress monitoring</strong> checks advancement through signals such as completed-step counters, using GPU utilization and heartbeats as supporting observations rather than proof of useful work. When the scheduler must preempt a lower-priority job, <strong>holistic preemption</strong> reserves the CPU, network, and storage bandwidth needed for that job to checkpoint and exit cleanly; otherwise, the victim can be too starved to release the accelerators. False failure suspicions can cost useful work, but must not bypass the ownership checks required for safe recovery.</p>\n<h3 id=\"sec-12\" class=\"cs-h3\">Heterogeneous gang scheduling</h3>\n<p>In preference-training pipelines such as reinforcement learning from human feedback (RLHF), allocating the policy-training GPUs while the rollout-generation or reward-scoring workers sit queued stalls the workflow just as completely as a missing AllReduce rank. Homogeneous gang scheduling allocates $\\DeviceCount$ identical workers executing the same compute graph. Heterogeneous workflows instead combine trainers, evaluators, and inference-style workers that need different GPU counts, memory footprints, and lifetimes, yet still must run together as a single job.</p>\n<p>↩ The models that alignment training co-locates, and their unequal resource demands, are established in @sec-distributed-training-rlhf.</p>\n<p>Heterogeneous gang scheduling extends atomic allocation to the roles that must coexist for a workflow to progress. A viable group might pair high-HBM nodes for memory-bound generation with compute-oriented nodes for policy updates. The orchestration problem then shifts from packing a homogeneous ring toward routing data. Rather than reducing gradients among identical workers, the job streams rollouts from generation workers to the workers that compute policy updates, so placement must also support the data exchanged between those roles. Rollout and training stages may exchange work in batches or through a buffered pipeline; their measured production and consumption rates determine where queues grow or accelerators wait. The scheduler needs a minimum viable resource bundle and a supported scaling policy for each role, rather than an assumption that all workers are interchangeable or perfectly balanced.</p>\n<p>Homogeneous and heterogeneous jobs share an allocation requirement: the scheduler must assemble a viable group before expecting progress. Backfill can use capacity while that group waits, provided runtime estimates or preemption contracts protect the reservation. Enforcing these policies requires a control plane that represents ownership and reconciles allocations after failures.</p>\n<h2 id=\"sec-13\" class=\"cs-h2\">Orchestration Paradigms</h2>\n<p>A pending gang and a queue of small backfill jobs need both a policy for sharing capacity and a control plane that can enforce it. The policies just developed apply across platforms; the orchestration paradigm determines how the platform represents allocations and recovers when observed state diverges from them. Slurm, shaped by HPC batch systems, favors explicit resource requests and predictable allocation. Kubernetes, shaped by cloud-native service management, favors declared desired state and continuous reconciliation. The choice is therefore not Slurm vs. Kubernetes as products; it is which control model best matches the workload mix, failure behavior, and operational culture of the fleet.</p>\n<p>The two platforms embody two control models (@fig-fleet-orchestration-slurm-vs-k8s). Slurm follows an imperative batch model, in which the user states the resources a job needs and the central slurmctld dispatches that allocation through per-node slurmd daemons. Kubernetes follows a declarative model, in which the user states what should be running and controllers reconcile observed state toward that declaration through the API server and node agents. Both platforms accept explicit resource requirements and track execution state, so the useful distinction is which lifecycle the platform manages directly: an allocated batch job or a collection of workloads maintained by controllers. That distinction shapes how ML workloads are admitted, monitored, and recovered from failure, and distributed training still needs framework-level coordination under either model.</p>\n<h3 id=\"sec-14\" class=\"cs-h3\">Slurm and HPC scheduling heritage</h3>\n<p>When a multi-node job needs an exclusive, non-overlapping block of accelerators for days at a time without partial-allocation deadlocks or conflicting node ownership, a centralized batch allocator is the most direct control plane. The Slurm Workload Manager originated at Lawrence Livermore National Laboratory to solve that problem for Linux supercomputers [@yoo2003]: long-running jobs, expensive shared hardware, and users who can specify resource needs in advance. In ML infrastructure, the same batch model maps to GPU training through partitions for heterogeneous accelerator pools and predictable atomic allocations for long-running distributed jobs.</p>\n<p>: <strong>Slurm Workload Manager</strong>: Originally \"SLURM,\" an acronym for Simple Linux Utility for Resource Management, the project dropped the acronym capitalization in 2012. Developed at Lawrence Livermore National Laboratory beginning in 2002, Slurm's centralized controller (<code>slurmctld</code>) maintains a single authoritative view of resource allocations. At very large scale, operators may partition fleets or federate schedulers to keep scheduling latency, policy isolation, and failure domains manageable.</p>\n<p>Slurm's batch submission model makes resource requirements explicit. Users submit job scripts, and the scheduler allocates resources within eligible partitions according to policy and availability. A submission of <code>sbatch --gres=gpu:8 --nodes=4</code> requests 8 GPUs on each of 4 nodes, a 32-GPU allocation. The request supplies a capacity contract, but useful execution still depends on the selected hardware and the application's launch configuration. Overstating requirements strands resources; understating them can cause memory failures or poor performance.</p>\n<p>Slurm's architecture consists of a central controller daemon (<code>slurmctld</code>) that maintains the global view of cluster state and makes scheduling decisions, and per-node daemons (<code>slurmd</code>) that manage local resources and execute jobs. This centralized architecture provides the authoritative allocation model discussed in @sec-fleet-orchestration-distributed-scheduling: the controller is the source of truth for resource assignments, reducing the risk of conflicting allocations. The cost is a potential single point of failure (addressed through active-passive failover) and a scheduling-throughput limit. As fleets grow, organizations may partition the cluster or federate schedulers to bound scheduling latency and failure impact; within a cluster, a typical ML configuration defines Slurm partitions by accelerator type and interconnect (@tbl-fleet-orchestration-slurm-partitions).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Partition</strong></th><th><strong>GPUs/node</strong></th><th><strong>Interconnect</strong></th><th><strong>Typical use</strong></th></tr></thead><tbody>\n<tr><td><strong>dgx-a100</strong></td><td>8$\\times$ A100</td><td>NVLink + IB NDR</td><td>Large LLM training</td></tr>\n<tr><td><strong>a100-pcie</strong></td><td>4$\\times$ A100</td><td>PCIe + IB HDR</td><td>Medium training</td></tr>\n<tr><td><strong>inference</strong></td><td>2$\\times$ A10G</td><td>Ethernet</td><td>Model serving</td></tr>\n<tr><td><strong>debug</strong></td><td>1$\\times$ V100</td><td>Ethernet</td><td>Development</td></tr>\n</tbody></table></div>\n<p>: <strong>Slurm Partition Configuration</strong>: Partitions organize heterogeneous accelerators into logical pools matched to workload characteristics. NVLink-connected partitions support tensor parallelism, while PCIe partitions serve workloads that rely primarily on data parallelism. Separating inference and debug partitions prevents experimental workloads from impacting production serving. {#tbl-fleet-orchestration-slurm-partitions}</p>\n<p>Within a partition, a request specifies both the number of GPUs a job needs and the <strong>allocation shape</strong>: how those GPUs are distributed across nodes. In Slurm, <code>--gres=gpu:N</code> or <code>--gpus-per-node=N</code> requests a per-node count, while <code>--gpus=N</code> requests a job-wide total. Whether the scheduler may split a node between jobs is a separate consumable-resource policy (Slurm's <code>select/cons_tres</code> plugin), and a node-exclusive policy strands the unused devices in the six-on-eight example of @sec-fleet-orchestration-bin-packing. Shape decides communication. In an eight-GPU-per-node pool, a 16-GPU request that also fixes eight GPUs per node (<code>--gpus-per-node=8</code>) yields two fully populated nodes, whose NVLink domains follow from the node hardware rather than the count. A request for 16 GPUs with no per-node constraint gives the scheduler more freedom, so it can start sooner on partially occupied nodes, but it may spread the group across several of them. Whether that flexibility is useful depends on the parallelism configuration and its communication budget. Tensor-parallel groups with frequent exchanges may justify compact placement, while data-parallel groups with well-overlapped communication may tolerate a wider allocation.</p>\n<p>Once partitions and allocation shapes define what a job asks for, the <strong>fair-share scheduling</strong> mechanism uses past consumption to influence future priority under contention. An illustrative heuristic combines base priority, the user's target fair share ($\\TargetFairShare$), recent actual consumption ($\\RecentUsageShare$), and a small stabilizing constant ($\\FairShareStabilizingConstant$); it illustrates the feedback without reproducing Slurm's multifactor priority calculation:</p>\n<p>$$\\text{Priority}<em>{\\text{effective}} = \\text{Priority}</em>{\\text{base}} \\times \\frac{\\TargetFairShare}{\\RecentUsageShare+ \\FairShareStabilizingConstant}$$ {#eq-fleet-orchestration-fair-share}</p>\n<p>With base priority and target share fixed, @eq-fleet-orchestration-fair-share lowers priority as recent consumption increases. Doubling consumption approximately halves this illustrative priority when the stabilizing constant is negligible. Actual admission also depends on other priority factors and feasible resources; low recent usage does not guarantee an immediate start.</p>\n<p>The time decay of usage history determines how quickly the system \"forgives\" past heavy usage. A half-life of one week means that a researcher's heavy usage from two weeks ago contributes only 25 percent to their current usage calculation. Short half-lives make the policy more responsive to recent changes but can encourage alternating bursts of usage. Long half-lives retain the effect of a completed large project when its researchers return with smaller jobs. The useful decay window depends on the fleet's job durations and the period over which the organization intends to balance access. Usage itself need not count every device alike. <strong>Trackable resources (TRES)</strong>} let accounting charge different accelerator classes different billing weights in fair-share usage, an administrative valuation that tracks economic cost only as far as the chosen weights do.</p>\n<p>Preemption policies enable high-priority jobs to reclaim resources from running workloads, and for ML training the reclaim must leave time to save state. Slurm expresses that time as a grace period. It signals the selected job (<code>SIGTERM</code>), waits the configured <code>GraceTime</code>, and only then kills it (<code>SIGKILL</code>); under <code>PreemptMode=REQUEUE</code> it can also requeue an eligible job to run again later. Neither the signal nor the requeue saves model state. The application must handle the signal, publish a valid checkpoint within the grace period, and restore it on restart. If termination precedes completion of that save, recovery uses the last valid checkpoint and replays subsequent work. Preemption therefore buys access for high-priority work with the victim's replay and restart time, a price that @sec-fleet-orchestration-preemption-cascades develops.</p>\n<p>↩ Checkpointing for progress preservation, including the checkpoint interval and coordination patterns, is established in @sec-fault-tolerance-reliability-reliability-checkpoint-restart-fundamentals-0ac2.</p>\n<p>Several Slurm features expose ML structure to the batch system. A hyperparameter sweep is the opposite of a gang. Job arrays submit many trials as one record (for example, <code>--array=0-99</code>), and each trial reads its index from the <code>SLURM_ARRAY_TASK_ID</code> environment variable to select its configuration. Slurm schedules the elements independently, so individual trials become ideal backfill candidates that fill small gaps in capacity, while the array keeps submission and management overhead low without making the trials one indivisible gang.</p>\n<p>Heterogeneous jobs carry the heterogeneous gang of @sec-fleet-orchestration-heterogeneous-gang into a batch allocation. One job can contain components with distinct resource requests, admitted together. The 64-GPU fine-tuning run of the 175B model, for example, could request 8 GPU nodes for training and 2 CPU-only nodes for on-the-fly tokenization as a single allocation. It could then launch training on the GPU component and data workers on the CPU component (<code>srun --het-group=0</code> and <code>--het-group=1</code>). This separation helps only if the data workers and transfer path sustain the training stage's consumption rate; a heterogeneous allocation exposes that choice but does not itself balance the pipeline.</p>\n<p>At the boundaries of each allocation, prolog and epilog scripts turn job transitions into health checks. A prolog tests reported topology, ECC counters, and link status on each allocated node and drains a failing node before launch. An epilog removes the job's orphan processes and shared-memory segments. Draining a failing node this way applies the quarantine practice of @sec-fleet-orchestration-topology-discovery at job boundaries, keeping sensitive work off a node whose health evidence shows degradation. Passing the prolog reduces exposure to known faults but does not establish the bandwidth the job will receive.</p>\n<p>Slurm's strengths for ML training include explicit batch allocations, configurable fair-share policies, and integration with MPI-based distributed training frameworks. A mixed training-serving fleet also needs a service lifecycle that maintains ready replicas as demand and failures change. Inside a batch scheduler, adding or removing an inference replica means submitting or canceling a job, a far heavier operation than a controller adjusting a replica count, and a failed replica stays down until something resubmits it. Operators must integrate replica health, replacement, and demand-driven scaling with the batch scheduler, or assign those responsibilities to a service orchestration platform.</p>\n<h3 id=\"sec-15\" class=\"cs-h3\">Kubernetes declarative container orchestration</h3>\n<p>When a cluster runs always-on inference services alongside training jobs, managing serving replicas as batch scripts forces operators to rebuild health checks, rolling updates, and replica replacement by hand. Kubernetes addresses this mixed workload by managing both services and batch jobs through a <strong>declarative model</strong> that expresses a workload's desired state and uses control loops to reconcile observations with that state [@burns2016; @kubernetes_orchestration]. The unit it places is the <strong>pod</strong>, one or more containers that share a node and a network identity, and its default scheduler places pods one at a time. The name collides with the hardware pod of @sec-compute-pod, the many racks joined under one fabric. A Kubernetes pod is a software unit that never spans more than one node, so a 64-pod training job is 64 container groups placed onto nodes, all of which can sit inside one hardware pod. Controllers above the scheduler give groups of pods a purpose: a Deployment keeps a set number of identical replica pods running, while a Job runs pods until they complete, retrying failures under a stated policy. The workload controller therefore determines what completion, replacement, or continued availability means.</p>\n<p>Failure handling reveals the importance of the workload contract. Slurm can detect node failures and requeue eligible jobs when configured to do so. Kubernetes controllers maintain workload-specific goals, such as a Deployment's replica count or a Job's completion and retry policy. A replacement pod still has to be placed, become ready, and rejoin the distributed training run before progress resumes. Training operators can coordinate worker creation, while the framework remains responsible for valid state and group recovery. Both platforms therefore require an explicit agreement between allocation, process lifecycle, and application recovery.</p>\n<p>Kubernetes' control loop architecture uses the controller pattern: controllers observe and update API objects through the API server, which persists cluster state in etcd, a replicated key-value store. Those objects contain desired state and reported observations, not instantaneous physical truth. The pattern repeats at every level: the Deployment controller reconciles the number of pod replicas, the scheduler binds pending pods to nodes, the kubelet (the agent on each node) keeps its assigned containers running, and the node controller marks nodes that stop reporting. Each component acts independently and communicates only through API objects, which makes the system resilient to the failure of any single controller. The price of that independence is that their interactions require clear ownership and retry behavior, particularly when a failed node's last reported state no longer describes its execution.</p>\n<p>: <strong>Controller pattern (reconciliation loop)</strong>: A \"level-triggered\" design reconciles the current desired and observed states rather than depending on every intermediate event. A restarted controller can resume from durable state if its actions tolerate retries and its observations expose unfinished work. Multiple controllers still need distinct responsibilities so that one controller's correction does not repeatedly undo another's.</p>\n<p>For those controllers to bind accelerators rather than generic CPU containers, Kubernetes needs an explicit resource representation before it can place GPU workloads. In the device-plugin model, <strong>device plugins</strong> expose accelerators as schedulable extended resources. The NVIDIA device plugin registers GPUs with the kubelet, enabling pod specifications that request GPU resources declaratively through the standard Kubernetes resource model. A pod then asks for whole GPUs by naming the <code>nvidia.com/gpu</code> resource in its limits (@lst-fleet-orchestration-k8s-gpu).</p>\n<pre class=\"cs-code\"><code># Kubernetes pod resource specification for GPU allocation\nresources:\n  limits:\n    nvidia.com/gpu: 4  # Request exactly 4 GPUs for this pod\n  requests:\n    cpu: &quot;32&quot;\n    memory: &quot;256Gi&quot;</code></pre>\n<p>When the device plugin exposes exclusive whole GPUs, a small model serving occasional requests can reserve a device while using only a fraction of its compute and memory capacity. Whole-device allocation suits workloads that need the capacity or isolation, but can strand resources for smaller workloads. The resource unit exposed by the plugin therefore matters, because sharing or partitioning changes what the scheduler can allocate and what isolation each allocation receives. Device plugins can also expose hardware partitions, such as MIG instances, as schedulable units, a choice that @sec-fleet-orchestration-resource-isolation develops with the serving workloads it suits.</p>\n<p>Kubernetes' default scheduler places pods independently, so it does not supply the group admission that @sec-fleet-orchestration-gang-scheduling requires. Under that default, a 64-pod training job receives 64 separate placement decisions, with no guarantee that all will succeed. If the cluster has resources for 60 pods but not 64, those 60 can occupy capacity while the remaining 4 wait. The platform must therefore configure a group-level admission and placement contract for a rigid job.</p>\n<p>The mechanism that closes this gap is group admission. A <strong>PodGroup</strong> declares a group's minimum runnable membership. The scheduler tentatively reserves a placement for each member as it finds one but binds none of them to nodes until the minimum membership is placed, and it releases every reservation if the attempt fails or times out. Admission and placement thereby become two decisions, with the group admitted only when placement has succeeded for enough of it. The Volcano batch scheduler and the Coscheduling scheduler plugin both implement this pattern. Group admission does not make physical launches simultaneous; nodes can still fail or start at different times, so the framework must establish the communication group before training proceeds.</p>\n<p>: <strong>Volcano</strong>: Volcano provides a scheduler with batch and gang-scheduling mechanisms. Pods select it through their scheduler name, so it can coexist with Kubernetes' default scheduler. The operational contract must account for interactions between schedulers sharing the same nodes; installing Volcano does not automatically transfer every workload's scheduling to it.</p>\n<p><strong>Context</strong>: OpenAI scaled Kubernetes clusters to <code>[OpenAiK8sScale.nodes_str]</code> nodes for workloads including GPT-3, CLIP, and DALL-E. Its account explains that MPI-coordinated optimizer groups needed all members scheduled before training could progress [@sigler2021openai_kubernetes].</p>\n<p><strong>Mechanism</strong>: The account illustrates the risk with two experiments each requesting the entire cluster. Incremental pod placement could allocate half the capacity to each, leaving neither with a complete group.</p>\n<p><strong>Impact</strong>: In that example, both jobs hold capacity without making progress. It demonstrates the deadlock mechanism rather than documenting a particular pair of stalled production runs.</p>\n<p><strong>Fix</strong>: OpenAI reports adopting the coscheduling plugin to add group-aware admission to the Kubernetes scheduler.</p>\n<p><strong>Systems lesson</strong>: Distributed ML scheduling must encode the job's execution semantics. For MPI-style training, \"some pods scheduled\" is not partial progress; it is wasted allocation. Production schedulers need gang scheduling, quota controls, and workload-aware policies rather than generic pod placement alone.</p>\n<p>When a PodGroup cannot find enough free capacity on its own, priority classes control scheduling precedence and preemption eligibility. A fleet might give inference higher priority than training to help protect serving service-level objectives (SLOs), but priority cannot replace ready capacity during a demand spike. With <code>preemptionPolicy: PreemptLowerPriority</code>, a pending pod can displace lower-priority pods when their removal makes placement feasible. With <code>preemptionPolicy: Never</code>, it retains queue precedence without initiating preemption and remains subject to higher-priority preemption. Termination, cleanup, and replacement startup take time. Training applications also need a checkpoint-aware shutdown path that fits the allowed grace period; assigning priorities does not create that path. The policy must balance serving readiness against repeated interruption of training.</p>\n<p>Kueue makes admission a separate control decision. It manages when workloads may consume quota, while a compatible scheduler binds their pods to nodes. The admission policy and placement policy must agree on resource types, group requirements, and topology. Separating these responsibilities lets each layer run its own policy, at the price of keeping the two consistent. Kueue represents each team or project as a queue with a configured quota (a ClusterQueue) and groups queues into cohorts whose members may lend one another unused quota, under the borrowing and reclaim contract of @sec-fleet-orchestration-burst-capacity.</p>\n<p>: <strong>Kueue</strong>: Kueue separates workload admission from pod placement. Its all-or-nothing mechanisms include waiting for admitted pods to become ready and requeuing workloads that exceed the configured timeout. Aggregate quota admission alone does not prove that a gang fits the physical topology; the guarantee depends on the configured readiness, topology, and placement mechanisms.</p>\n<h3 id=\"sec-16\" class=\"cs-h3\">Kubernetes ecosystem for ML training</h3>\n<p>Group admission handles one constraint that microservice orchestration can leave implicit but distributed training cannot. Four other such constraints remain. Workers must launch knowing their peers, collective traffic must avoid network layers built for request traffic, checkpoint writes need bandwidth rather than only storage capacity, and progress must be observable below the container. Operators and plugins add each constraint to the platform; the mechanism matters more than the product that happens to implement it.</p>\n<p>Peer discovery is the job of the <strong>training operator ecosystem</strong>, which extends Kubernetes with job-specific resource types (custom resource definitions). In the Kubeflow Training Operator, a <code>PyTorchJob</code> declares the number of workers, the container image, and resource requirements. The operator creates the pods and injects the rendezvous address (<code>MASTER_ADDR</code> and <code>MASTER_PORT</code>), the group size, and each worker's rank (<code>WORLD_SIZE</code> and <code>RANK</code>), which the framework uses to form its communication group. If a worker pod fails, the operator can detect the deviation and create a replacement pod to restore the desired replica count, but training-state recovery still depends on the framework's checkpoint and rendezvous logic.</p>\n<p>Collective traffic is the second constraint. The pod overlay network that the Container Network Interface (CNI) configures, designed for microservice requests, routes packets through software switching on the host CPU, which adds latency and caps bandwidth when it sits on the critical gradient-synchronization path. For bandwidth-sensitive training, <strong>host networking</strong> (<code>hostNetwork: true</code>) places pods in the host's network namespace, bypassing the ordinary pod overlay path. It does not itself allocate remote direct memory access (RDMA) devices or grant permission to use them; device exposure, resource requests, drivers, and access controls require separate configuration. Operators such as NVIDIA's Network Operator automate that exposure through RDMA device plugins and GPUDirect RDMA configuration, letting containerized workloads approach bare-metal interconnect performance once the rest of the stack is configured.</p>\n<p>Checkpoint bandwidth is the third constraint, because storage integration must account for the checkpoint storm of definition \\ref{dfn-data-storage-checkpoint-storm}, in which many workers write large amounts of state together. Kubernetes PersistentVolumeClaims (PVCs) request capacity on a configured storage system but do not reserve checkpoint throughput. A <code>[ReferenceCheckpoint.job_gpus_str]</code>-GPU training job writing the <code>[ReferenceCheckpoint.ckpt_tb_str]</code> resumable checkpoint of the 175B model needs a measured write budget shared with other workloads. Backend bandwidth controls, client throttling, or staggered writes can limit interference; the platform must verify which controls the storage implementation enforces.</p>\n<p>Visibility into progress is the fourth. The <strong>observability stack</strong> for training clusters combines general-purpose cluster monitoring (commonly Prometheus and Grafana) with accelerator telemetry such as the Data Center GPU Manager (DCGM) exporter, which reports utilization, memory bandwidth, temperature, and ECC errors. These observations locate symptoms. Correlating them with step progress, input waits, and communication traces is what distinguishes useful computation from stalls and identifies which dependency limits a training job.</p>\n<p>↪ Fleet telemetry across device, network, and facility levels, and the correlation that narrows a failure domain, is developed in @sec-ops-scale-fleet-telemetry.</p>\n<p>The <code>[ReferenceCheckpoint.job_gpus_str]</code>-GPU pretraining run for our 175B model illustrates how these responsibilities fit together. One possible deployment defines a <code>PyTorchJob</code> with <code>[ReferenceCheckpoint.worker_pods_str]</code> worker pods, each requesting <code>[ReferenceCheckpoint.gpus_per_pod_str]</code> GPUs. Host networking removes the pod overlay from the gradient path, and the Network Operator exposes each node's InfiniBand adapters to the workers through RDMA device plugins. A PVC backed by Lustre, a parallel file system, provides access to the <code>[ReferenceCheckpoint.corpus_tb_str]</code> tokenized training corpus and a checkpoint path whose sustained bandwidth must be validated. DCGM metrics stream to Prometheus, supporting alerts on uncorrectable ECC errors and deviations from workload-specific communication baselines.</p>\n<h3 id=\"sec-17\" class=\"cs-h3\">Paradigm trade-offs and selection criteria</h3>\n<p>Assembling that multi-operator stack to supply what a batch scheduler provides natively highlights why selecting a control plane requires matching its allocation and recovery contract to the workload mix. Rigid training groups need reliable atomic placement and checkpoint-aware interruption; serving replicas need readiness checks and continuous recovery. Existing operational expertise and the cost of running a second control plane also shape the choice. A fleet dedicated to long, homogeneous training runs that use bare-metal collectives, operated by a team fluent in batch scheduling, gains most from Slurm's authoritative allocation and mature fair-share. A fleet that mixes training with always-on serving, and already runs cloud-native deployment and observability tooling, gains more from Kubernetes with a gang-admission layer added for its rigid jobs. The Slurm vs. Kubernetes trade-off organizes around the dimensions most relevant to ML workloads (@tbl-fleet-orchestration-paradigm-comparison).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Dimension</strong></th><th><strong>Slurm</strong></th><th><strong>Kubernetes</strong></th></tr></thead><tbody>\n<tr><td><strong>Scheduling model</strong></td><td>Imperative: user specifies exact resources and scheduler allocates them</td><td>Declarative: user specifies desired state, system reconciles continuously</td></tr>\n<tr><td><strong>Failure handling</strong></td><td>Configuration-dependent requeue and checkpoint workflows</td><td>Self-healing through control loops</td></tr>\n<tr><td><strong>Gang/atomic multi-node start</strong></td><td>Atomic job allocation plus backfill; Slurm \"gang scheduling\" specifically refers to time-slicing/preemption</td><td>Production clusters commonly use PodGroup-based support such as Volcano, Coscheduling, Kueue, or upstream alpha gang scheduling</td></tr>\n<tr><td><strong>Fair-share</strong></td><td>Mature multi-factor priority with configurable decay</td><td>Kueue provides basic fair-share with ClusterQueue borrowing</td></tr>\n<tr><td><strong>Container overhead</strong></td><td>None from a container runtime when jobs run directly on nodes</td><td>Configuration-dependent networking overhead and container startup time</td></tr>\n<tr><td><strong>Service management</strong></td><td>No native support for long-running services</td><td>Native Deployment, rolling updates, health checks</td></tr>\n<tr><td><strong>Ecosystem</strong></td><td>MPI, OpenMP, scientific computing libraries</td><td>Cloud-native, microservices mesh, observability stack</td></tr>\n</tbody></table></div>\n<p>: <strong>Slurm vs. Kubernetes for ML Workloads</strong>: The two paradigms reflect different design philosophies optimized for different workload characteristics. Most production ML platforms use elements of both, with Slurm managing dedicated training clusters and Kubernetes managing inference serving and pipeline orchestration. {#tbl-fleet-orchestration-paradigm-comparison}</p>\n<p>The gang-scheduling row of the table compresses a naming collision that is easy to miss. This chapter uses gang scheduling for atomic allocation of a whole execution group, which is the requirement distributed training imposes. Slurm reserves the name for the older, Ousterhout-style meaning of the term, in which co-scheduled jobs share nodes by time-slicing in synchronized rounds. Slurm provides atomic multi-node allocation under its ordinary job model, so the requirement is met even though Slurm's \"gang scheduling\" option means something else.</p>\n<p>The choice of scheduling paradigm also reflects organizational trajectory. Teams starting with HPC-focused training infrastructure may begin with Slurm and add Kubernetes for serving. Teams starting from cloud-native application infrastructure may begin with Kubernetes and add HPC-oriented extensions (Volcano, Kueue) for training. Slurm has meanwhile added a REST interface and container support, so the two platforms now overlap in capability. Either path can reach a functional hybrid architecture, but the starting point determines which capabilities are strongest and which require the most investment to develop.</p>\n<h3 id=\"sec-18\" class=\"cs-h3\">Hybrid architectures in practice</h3>\n<p>In practice, those two convergence paths produce <strong>hybrid architectures</strong> that partition responsibilities between both systems according to workload semantics rather than organizational labels. Rigid, topology-sensitive jobs fit a batch scheduler's atomic allocation contract, while malleable services fit a reconciliation loop that adjusts replica count continuously. Some training jobs are elastic, and some serving replicas are rigid multi-accelerator gangs, so neither \"training\" nor \"serving\" selects a control plane by itself.</p>\n<p>The <strong>Kubernetes-over-Slurm</strong> pattern wraps the HPC scheduler within a cloud-native control plane. Kubernetes manages the lifecycle of training jobs through custom operators while delegating batch admission and placement to Slurm. The central engineering problem is ownership: exactly one control plane must authorize each placement, while the outer controller reconciles lifecycle state without issuing a conflicting allocation. The arrangement combines a declarative management surface with Slurm's batch and topology policies, but it also creates a cross-control-plane failure boundary that operators must fence explicitly.</p>\n<p>The <strong>Slurm-alongside-Kubernetes</strong> pattern takes a coarser-grained approach, maintaining separate clusters for training and serving that draw from a shared pool of physical nodes. A meta-scheduler or capacity broker acts as an arbitrator, dynamically reassigning nodes between the Slurm partition and the Kubernetes cluster based on demand signals. During intensive training campaigns, nodes are drained from Kubernetes and joined to Slurm; during product launches or traffic spikes, the flow reverses. The primary challenge is the mode-switching cost: draining a node, changing its ownership and configuration, and admitting it to the other control plane takes much longer than an ordinary placement decision. This latency limits sharing to planned capacity shifts rather than second-by-second inference bursts.</p>\n<p>A shared application runtime such as Ray runs both training and serving through two abstractions, tasks (stateless function calls executed on remote workers) and actors (long-lived processes that keep state between calls). Ray's placement groups, unlike the cloud network-locality abstraction of the same name, reserve bundles of logical resources for work that must run together, and serving replicas can also require multi-device groups. Inside a shared runtime the workloads keep their different state, latency, and recovery requirements, so the platform must still coordinate Ray's logical allocations with the underlying resource manager and validate the isolation and recovery behavior needed by each workload.</p>\n<p>Threading these patterns together, consider the lifecycle of our 175B parameter model. A hybrid platform can allocate the training gang through Slurm and later place serving replicas through Kubernetes. The orchestration boundary concerns resource ownership: the training job releases its allocation, and the serving control plane admits replicas against its own capacity and readiness requirements. Deciding whether the trained artifact is ready for production requires validation and release policy beyond the scheduler; @sec-ml-operations-scale-cicd-ml-scale-730a develops those validation checks and rollout policies.</p>\n<p>A hybrid platform is useful when its separate allocation contracts justify the additional ownership and recovery boundary. The cost to measure is the coordination between control planes, including node draining and reassignment, rather than a presumed performance advantage from either product name. Because Slurm and Kubernetes now overlap in capability, the paradigm choice is a workload-specific design decision, and teams must establish the allocation and recovery guarantees they need before layering physical placement constraints on top of them.</p>\n<p>Before the chapter turns to topology-aware placement, review the core trade-offs:</p>\n<ul class=\"cs-list\">\n<li>[ ] <strong>Gang scheduling</strong>: explain why a rigid synchronous execution group needs atomic allocation, and why the scheduler must still reserve capacity for a waiting gang that holds no GPUs itself.</li>\n<li>[ ] <strong>Slurm vs. Kubernetes</strong>: compare authoritative allocation with desired-state reconciliation, and explain why either design must prevent duplicate ownership during a network partition.</li>\n<li>[ ] <strong>Group admission</strong>: explain why a default scheduler that places pods one at a time can strand capacity for a 64-pod training job, and how a PodGroup's minimum membership prevents it.</li>\n<li>[ ] <strong>Resource units</strong>: explain how the resource unit a device plugin exposes changes what the scheduler can pack, and why a small model on an exclusively assigned GPU strands capacity.</li>\n<li>[ ] <strong>Backfill incentives</strong>: explain why backfill scheduling depends on accurate job runtime estimates and why users have game-theoretic incentives to provide inaccurate estimates.</li>\n</ul>\n<p>A control plane can now represent, admit, and reconcile an allocation, yet it still counts accelerators as if any group of the requested size were interchangeable. Two allocations of the same size can meet very different communication budgets depending on where the devices sit in the cluster fabric. The next layer of the scheduler must therefore weigh physical location alongside resource count.</p>\n<h2 id=\"sec-19\" class=\"cs-h2\">Topology-Aware Scheduling</h2>\n<p>A scattered allocation can place frequent collective traffic on shared cross-rack paths, exposing latency or bandwidth limits that a more compact allocation avoids. The penalty is set by how much of the job's traffic crosses those paths and how much capacity the fabric provisions there, not by the rack count itself. The earlier feasibility rules already required compatible topology; topology-aware scheduling makes that requirement explicit in the placement objective, accounting for communication paths as well as raw compute.</p>\n<h3 id=\"sec-20\" class=\"cs-h3\">The topology hierarchy</h3>\n<p>Splitting a tensor-parallel group across node boundaries moves its per-layer activation exchanges off intra-node NVLink onto the external network fabric, where an H100's per-direction NVLink rate is <code>[FleetTopologyInterconnect.xfer_slowdown_mult_str]</code> the rate of one NDR port (@sec-compute-bandwidth-hierarchy). Each level of a cluster's communication hierarchy comes from the hardware that builds it and sets a distinct bandwidth and latency budget. GPUs inside a node exchange data over NVLink, the tier fast enough for the per-layer exchanges of tensor parallelism. Nodes under one leaf switch communicate over an external fabric such as InfiniBand or RoCE. Racks joined through spine switches add switch hops whose delivered bandwidth depends on concurrent flows and oversubscription even in a fat-tree. Cross-rack communication also adds tail latency variability: while median latency may be only slightly higher, p99 latency can spike during congestion events, creating straggler effects in synchronous training where the slowest communicator determines the pace for all workers.</p>\n<p>↩ Bisection bandwidth and fat-tree network topologies are established in @sec-network-fabrics-fat-tree.</p>\n<p>A 64-GPU job within one rack can avoid cross-rack paths that a spread allocation must use. It outperforms the spread allocation only when those paths add exposed latency or bandwidth contention; a non-blocking, uncongested spine need not reduce sustained throughput. The performance difference stems directly from the hierarchical communication analysis in @sec-communication-collective-operations-collective-operations-hierarchical-allreduce-1338: a flat ring AllReduce runs at the speed of the slowest link in the ring, and cross-rack hops introduce both higher latency and increased contention risk. For synchronous training, every iteration waits for the slowest worker to complete its AllReduce, so even occasional cross-rack congestion inflates the Fleet Law's communication term $\\CommunicationTime(\\DeviceCount)$ (@eq-fleet-law) on every step it touches.</p>\n<p>The scheduler must therefore model the cluster as a hierarchical graph with discrete bandwidth boundaries (@fig-fleet-orchestration-topology-hierarchy). In the illustrated H100 fleet, per-direction bandwidth steps down from <code>[FleetTopologyInterconnect.nvlink_h100_perdir_gb_per_s_str]</code> across the NVSwitch inside a node to <code>[FleetTopologyInterconnect.ib_ndr_gb_per_s_str]</code> per port under a leaf switch, and to roughly <code>[FleetTopologyInterconnect.oversub_lo_num_str]</code>--<code>[FleetTopologyInterconnect.oversub_hi_gb_per_s_str]</code> per endpoint when balanced traffic saturates an oversubscribed spine. A node boundary can introduce a large bandwidth reduction, but a non-blocking rack or pod boundary need not reduce per-endpoint bandwidth. Oversubscription adds a separate constraint when traffic saturates shared uplinks. Topology-aware placement minimizes the communication cost of the job's actual traffic pattern rather than applying a fixed penalty to every boundary.</p>\n<p>For a 4-GPU collective group, the routing paths make that cost concrete (@fig-topology-placement-paths). In the illustrated contended fabric, scattering ranks across Rack A and Rack B forces a 3-hop leaf-spine-leaf path with about <code>[FleetTopologyInterconnect.oversub_lo_gb_per_s_str]</code> of effective bandwidth per endpoint, a share of contended uplinks rather than a physical link rate. Consolidating all four ranks (G0–G3) under Rack A's leaf switch avoids those shared uplinks and provides about <code>[FleetTopologyInterconnect.ib_ndr_gb_per_s_str]</code> per GPU under the example's load assumptions.</p>\n<h3 id=\"sec-21\" class=\"cs-h3\">Placement algorithms</h3>\n<p>The illustrated <code>[FleetTopologyInterconnect.rack_vs_spine_mult_str]</code> bandwidth difference between the 1-hop leaf path and the 3-hop spine route (@fig-topology-placement-paths) stretches the transfer component by the same factor when transfer time is bandwidth-dominated. Crossing a spine does not impose that ratio independently of load and topology. Whether communication exceeds computation also depends on the model and overlap schedule, and repeated exchanges can amplify the exposed cost. Topology-aware placement algorithms assign jobs to nodes that reduce this cost, turning resource packing into graph optimization over the physical topology. A simple <strong>locality cost</strong>, defined in @eq-fleet-orchestration-locality-score, penalizes allocations spanning multiple topology domains:</p>\n<p>$$ \\text{Cost}<em>{\\text{locality}} = \\sum</em>{i &lt; j} \\LocalityPenaltyFunction(\\GpuTopologicalDistance(\\AssignedJobGpu_i, \\AssignedJobGpu_j)) $$ {#eq-fleet-orchestration-locality-score}</p>\n<p>where $\\AssignedJobGpu_i$ and $\\AssignedJobGpu_j$ are GPUs assigned to the job, $\\GpuTopologicalDistance(\\AssignedJobGpu_i, \\AssignedJobGpu_j)$ is their topological distance (0 for same node, 1 for same rack, 2 for different racks), and $\\LocalityPenaltyFunction(\\cdot)$ is a weighting function that increases with distance. The scheduler minimizes this score when selecting an allocation from the set of feasible placements. An illustrative heuristic assigns locality penalties of $\\LocalityPenaltyFunction(0) = 0$ (same node, NVLink, no penalty), $\\LocalityPenaltyFunction(1) = 1$ (same rack, one switch hop), and $\\LocalityPenaltyFunction(2) = 10$ (different racks, multiple switch hops). These dimensionless weights are policy assumptions rather than measured latency or bandwidth ratios, so a deployment must calibrate them to its traffic and topology. An unweighted pairwise score still cannot distinguish heavily communicating rank pairs from pairs that rarely exchange data.</p>\n<p>More sophisticated algorithms distinguish the communication requirements of different parallelism strategies. Frequent tensor-parallel activation exchanges favor a high-bandwidth, low-latency domain that meets the measured communication budget; that domain need not coincide with one server. Pipeline parallelism exchanges activations across stage boundaries rather than between every layer, but its tolerance for link delay depends on microbatch size and the pipeline schedule. Data-parallel gradient synchronization can overlap computation, making wider placement feasible when the exposed communication remains within budget. These patterns guide placement without establishing a universal ranking for every model or fabric.</p>\n<p>@Algo-topology-aware-placement combines the all-or-nothing gang constraint of @sec-fleet-orchestration-gang-scheduling, the locality cost of @eq-fleet-orchestration-locality-score, and an illustrative parallelism-to-topology mapping. The algorithm constructs feasible rank mappings, scores each allocation, and chooses the lowest illustrative locality score, leaving the job queued when none fits. This surrogate does not guarantee minimum communication time or completion time. A fleet-scale implementation must restrict that search using heuristics rather than enumerate every allocation.</p>\n<pre class=\"cs-code\"><code>#| label: algo-topology-aware-placement\n#| pdf-line-number: true\n#| pdf-right-comment: false\n#| html-comment-delimiter: &quot;▷&quot;\n\\begin{algorithm}\n\\caption{Topology-aware placement}\n\\begin{algorithmic}\n\\Require job requesting $N$ accelerators with tensor-, pipeline-, and data-parallel groups; cluster topology with illustrative per-level locality weights $w(\\cdot)$\n\\Ensure an all-or-nothing feasible placement with the lowest illustrative locality score, or the job stays queued\n\\State enumerate candidate slots: sets of $N$ free accelerators that satisfy every resource dimension \\Comment{gang: all or nothing}\n\\State retain only slots that admit a rank mapping satisfying the job&#x27;s tensor-, pipeline-, and data-parallel communication constraints\n\\If{no feasible slot exists}\n    \\State leave the job queued without holding any accelerators \\Comment{prevents hold-and-wait deadlock}\n    \\State \\Return no placement\n\\EndIf\n\\For{each feasible slot}\n    \\State use a feasible rank mapping: tensor-parallel ranks within an NVLink domain, pipeline stages within a rack, data-parallel replicas across racks where permitted\n    \\State score the slot by $\\text{Cost}_{\\text{locality}} = \\sum_{i &lt; j} w(d(g_i, g_j))$\n\\EndFor\n\\State \\Return the feasible slot of least $\\text{Cost}_{\\text{locality}}$ \\Comment{minimum score among enumerated feasible placements; atomic allocation}\n\\end{algorithmic}\n\\end{algorithm}</code></pre>\n<p>Applied to a whole job, the same reasoning ranks placement strategies. The latencies in this comparison are illustrative, not derived. They are constructed to stay above the ring-AllReduce bandwidth bound for the payload, and they show the order in which placement removes delay rather than values a reader could recompute from topology names. For a 0.5 GB gradient synchronization on <code>[TopologyPlacement.n_gpus_str]</code> GPUs, random placement spans multiple racks and spine switches and takes an assumed <code>[TopologyPlacement.random_placement_latency_ms_str]</code>. Each successive strategy removes a source of delay that the previous one leaves. Confining the group to a single rack removes spine hops and reduces latency to <code>[TopologyPlacement.rack_aware_latency_ms_str]</code>. Rail-optimized alignment maps ranks so that every member of each collective group sits at the same local GPU index and therefore on the same network rail (developed in @sec-fleet-orchestration-rail-optimized). Traffic that previously hopped between rails through the spine now stays within one rail's switches, which cuts latency to <code>[TopologyPlacement.rail_optimized_latency_ms_str]</code>. Topology-optimal placement additionally avoids leaf ports that other jobs are using and reaches <code>[TopologyPlacement.optimal_latency_ms_str]</code>, a <code>[TopologyPlacement.speedup_mult_str]</code> reduction (@fig-topology-placement, where each bar also carries its algorithm throughput). This ratio compares whole collectives under four assumed placements, so it need not match the link-bandwidth ratio of the earlier two-rack paths.</p>\n<p>A <strong>hierarchical placement</strong> algorithm applies these constraints from the most restrictive communication domain outward, matching each 3D parallelism dimension to the interconnect tier its traffic can tolerate (@fig-fleet-orchestration-hierarchical-placement). In the illustrated fleet, it places each tensor-parallel group within an NVLink-connected node, where the per-layer activation exchanges run at <code>[FleetTopologyInterconnect.nvlink_h100_perdir_gb_per_s_str]</code>. It places consecutive pipeline stages under the same leaf switch, where stage boundaries cross at <code>[FleetTopologyInterconnect.ib_ndr_gb_per_s_str]</code>. It distributes data-parallel replicas across racks only when the once-per-step gradient synchronization fits the roughly <code>[FleetTopologyInterconnect.oversub_lo_num_str]</code>--<code>[FleetTopologyInterconnect.oversub_hi_gb_per_s_str]</code> per endpoint that an oversubscribed spine leaves. This alignment reduces costly boundary crossings, but placement alone cannot reserve the fabric's full bisection bandwidth against other jobs.</p>\n<p>Evaluating all possible placements for a 256-GPU job across a 10,000-GPU cluster is combinatorially intractable, so production schedulers rely on heuristic approaches. Common choices include greedy algorithms that build placements bottom-up (first fill NVLink domains, then fill racks, then spread across racks), tree-search algorithms with pruning that explore the most promising placements first, and scoring-based approaches that evaluate a sample of feasible placements and select the best. Long jobs can amortize a more expensive search, but frequent submissions, short jobs, and recovery bursts also consume scheduler capacity, making end-to-end completion time, including placement delay, the useful comparison rather than execution throughput alone. The same comparison governs how long a job should wait for a compact placement. Holding a job until enough GPUs free up under one leaf switch delays its start, and the wait pays off only if faster collectives recover more than that delay over the job's run.</p>\n<p><strong>Scenario</strong>: Consider a 256-GPU training job using 3D parallelism: 8-way tensor parallel, 4-way pipeline parallel, 8-way data parallel.</p>\n<p><strong>Good placement</strong> (topology-aware):</p>\n<ul class=\"cs-list\">\n<li>Tensor parallel groups: 32 groups of 8 GPUs, each confined to one 8-GPU node (NVLink: <code>[FleetTopologyInterconnect.nvlink_h100_perdir_gb_per_s_str]</code> per direction)</li>\n<li>Pipeline stages: 4 consecutive nodes within the same rack (1 switch hop, InfiniBand: <code>[FleetTopologyInterconnect.ib_ndr_gb_per_s_str]</code> per direction)</li>\n<li>Data parallel replicas: 8 racks (3 switch hops through leaf-spine-leaf paths)</li>\n</ul>\n<p><strong>Bad placement</strong> (topology-unaware):</p>\n<ul class=\"cs-list\">\n<li>Tensor parallel groups split across 2 nodes (InfiniBand instead of NVLink)</li>\n<li>Pipeline stages scattered across racks (3 switch hops instead of 1)</li>\n<li>Data parallel replicas randomly distributed</li>\n</ul>\n<p><strong>Math</strong>: The tensor parallel communication alone illustrates the impact. With NVLink delivering <code>[FleetTopologyInterconnect.nvlink_h100_perdir_gb_per_s_str]</code> per direction, a <code>[FleetTopologyInterconnect.activation_gb_str]</code> activation transfer takes approximately <code>[FleetTopologyInterconnect.nvlink_xfer_ms_str]</code>. Over InfiniBand at <code>[FleetTopologyInterconnect.ib_ndr_gb_per_s_str]</code>, the same transfer takes approximately <code>[FleetTopologyInterconnect.ib_xfer_ms_str]</code>, a <code>[FleetTopologyInterconnect.xfer_slowdown_mult_str]</code> slowdown.</p>\n<p><strong>Systems insight</strong>: This calculation prices only the tensor-parallel component of the bad placement. Splitting a tensor-parallel group across nodes makes each activation exchange <code>[FleetTopologyInterconnect.xfer_slowdown_mult_str]</code> slower, and the group performs such exchanges at every transformer layer of every step, so the penalty multiplies with model depth rather than appearing once. How much of it reaches step time depends on how much of the exchange was hidden behind computation, and it is why hierarchical placement gives tensor-parallel groups the fastest tier first. The scattered pipeline stages and data-parallel replicas add their own penalties on top, and the scheduler must profile the complete job before assigning a throughput benefit to the placement.</p>\n<h3 id=\"sec-22\" class=\"cs-h3\">Rail-optimized scheduling</h3>\n<p>Even when two nodes sit in the same pod, placing corresponding data-parallel shards on mismatched local GPU indices forces their gradient collective to cross between network rails through the spine instead of staying on a single rail switch. In rail-optimized topologies, corresponding GPU positions across nodes connect through parallel network \"rails\" that a suitable rank mapping can use concurrently. Balanced bandwidth depends on distributing traffic across those paths rather than concentrating it on a subset. Keeping a collective group on one rail avoids cross-rail transfers for that group, while the placement of other groups determines how much rail capacity it must share.</p>\n<p>↩ Rail-optimized fabric architectures and rail-to-rail traffic isolation are established in @sec-network-fabrics-rail-optimized.</p>\n<p>Rail-aware scheduling assigns corresponding model shards across data-parallel replicas to GPUs attached to the same rail. When intra-node parallelism partitions a model replica across the eight GPUs of a node, each data-parallel gradient collective reduces only one shard $\\LocalRankIndex$ across replicas rather than combining all eight GPUs on the node. In the eight-GPU-per-node example, local GPU index $\\LocalRankIndex$ connects to rail $\\LocalRankIndex$. Placing every replica's copy of shard $\\LocalRankIndex$ at that same local index on its selected node means the data-parallel replica rank varies across nodes rather than across local GPU indices, so the collective for shard $\\LocalRankIndex$ stays entirely within rail $\\LocalRankIndex$. This alignment removes cross-rail transfers for that group, though other groups or tenants can still contend for the same rail's links, and full dedicated bandwidth requires an explicit capacity and sharing contract.</p>\n<p>Rail alignment therefore acts at two levels, and they belong to different components. Within a node it is a rank-mapping decision. The launcher or framework must give every member of a data-parallel group the same local GPU index on its node, which is what removes the cross-rail hops in the placement comparison above. A mapping that puts shard $\\LocalRankIndex$ at index $\\LocalRankIndex$ on one node and at another index elsewhere sends that group's traffic between rails.</p>\n<p>Across nodes, rail alignment constrains the scheduler only when allocations are smaller than a node. When each replica's pipeline stage occupies a complete node and every node wires local GPU $\\LocalRankIndex$ to rail $\\LocalRankIndex$, any free node already offers every rail, so rail alignment does not narrow which racks the scheduler can choose. With partial-node allocations, a job can receive different local indices on different nodes, and the scheduler must then choose GPU positions as well as nodes so that each group's members share a rail. Those positions can conflict with the tensor-parallel budget and the paths between pipeline stages when only particular GPU positions remain free. The packing cost therefore follows the allocation granularity and the available topology rather than an inherent conflict among the three parallelism dimensions. Even a single-node allocation can have meaningful topology constraints when GPUs occupy different interconnect, PCIe, or non-uniform memory access (NUMA) domains, so packing efficiency should be optimized only among placements that satisfy the job's local and external communication contract.</p>\n<h3 id=\"sec-23\" class=\"cs-h3\">Topology discovery and dynamic adaptation</h3>\n<p>When a spine switch fails or an optical link degrades and begins retransmitting, a static configuration file such as Slurm's <code>topology.conf</code> or Kubernetes node labels still reports the rack as healthy and full-bandwidth. The scheduler then places communication-heavy gangs onto a crippled path. Runtime <strong>topology discovery</strong> supplements static maps with information exposed by the operating system and device libraries. NCCL uses system topology information, including the PCIe hierarchy and network devices exposed through paths such as <code>/sys/class/infiniband</code>, to identify communication paths and network interface card (NIC) proximity. The discovered graph describes reported connectivity; health checks and traffic measurements must establish whether those paths deliver the expected performance.</p>\n<p>Cluster topology is an operating state, not a fixed schematic. Hardware failures, maintenance windows, and thermal throttling change the paths and effective capacity available to the scheduler. A spine switch failure in a redundant Clos network can leave connectivity intact while removing capacity. The effect on our 175B parameter model's data-parallel AllReduce depends on rerouting, concurrent traffic, and how much bandwidth the job was using. If the failure increases exposed communication time, the scheduler must compare continuing at reduced throughput with the cost of moving to a healthier allocation. A degraded link can also pass binary up/down probes while cutting delivered bandwidth, so the scheduler needs performance evidence such as retransmission counts and collective bandwidth, the link-level telemetry of @sec-network-fabrics-link-telemetry, as well as reachability.</p>\n<p>A checkpoint-and-restart migration spends time saving state, releasing the old allocation, obtaining a new one, and restoring execution. Its value depends on measured transition cost and remaining work. If migration takes 10 minutes and removes a sustained 20 percent throughput loss, each later minute of training recovers a fifth of a minute of progress, so the move pays back in less than an hour of subsequent training. That comparison assumes a healthy destination is available and the gain persists. A practical policy also accounts for queue delay and requires evidence that placement causes the slowdown, such as rising collective time on the affected path, before it moves the job.</p>\n<p><strong>Context</strong>: OpenAI's account of scaling Kubernetes describes automated health checks that remove misbehaving nodes from the schedulable pool [@sigler2021openai_kubernetes].</p>\n<p><strong>Mechanism</strong>: Passive checks monitor reachability, disks, and GPU errors, but error codes do not expose every hardware or driver problem. Active GPU tests exercise the device before admitting ordinary workloads and periodically during its lifetime.</p>\n<p><strong>Fix</strong>: Nodes enter with a preflight taint, a node marking that repels ordinary pods, which blocks normal scheduling until the tests pass. Failed passive checks cordon a node, marking it unschedulable for new work; more serious failures can trigger eviction requests.</p>\n<p><strong>Systems lesson</strong>: Reachability alone is not a sufficient admission test. A scheduler needs health evidence that reflects the resources its jobs depend on, together with a policy for removing suspect nodes from placement.</p>\n<p>The general scheduling idea is quarantine: when runtime evidence says a node, rack, or link is degraded, the scheduler should stop placing sensitive work there even if the nominal resource count still looks available. Kubernetes implements this pattern through taints and tolerations, while Slurm clusters commonly use drain states, node features, or partition rules.</p>\n<p>↩ Slow components that pass liveness checks while setting the pace of every synchronous step, and how to tell them from fail-stop failures, are established in @sec-fault-tolerance-reliability-reliability-distinguishing-stragglers-failures-285d.</p>\n<p>Quarantining degraded nodes or links protects placement quality for new arrivals, but it also changes the healthy capacity pool while jobs are already running. Adapting to those capacity shifts alongside fluctuating queue demand requires relaxing the assumption that a job's resource allocation stays fixed for its entire lifetime.</p>\n<p>: <strong>Taints and tolerations</strong>: Node taints can block scheduling of pods without matching tolerations. A toleration permits consideration of a node but neither requires placement there nor reserves it exclusively for training. Dedicated GPU pools also need controlled toleration assignment and placement constraints; removing existing workloads requires an eviction or drain policy appropriate to the taint's effect.</p>\n<h2 id=\"sec-24\" class=\"cs-h2\">Elastic Scheduling</h2>\n<p>When cluster demand fluctuates, rigid allocation creates two categories of waste. During off-peak hours, a job running on 256 GPUs cannot absorb idle resources to speed up training. During peak demand, the same job cannot release excess resources to accommodate higher-priority work without being fully preempted. The scheduler's only options are \"let it keep all its resources\" or \"kill it entirely,\" with nothing in between.</p>\n<p>Elastic scheduling expands this binary choice. The recovery mechanics of elastic training show how a distributed job can adjust its worker count, adapt its batch policy, and reconstruct its communication group after a failure. From the scheduler's perspective, the same capability solves a resource-allocation problem under fluctuating demand. A training job might start with 128 GPUs, scale up to 256 when resources become available, and scale back to 192 when higher-priority work arrives, provided each allocation supports a viable worker group. Resizing may pause training and restart workers from saved state. Whether worker processes restart depends on the framework; TorchElastic restarts its worker group when membership changes. The scheduler therefore chooses among supported allocation sizes, each with a transition cost, rather than assuming uninterrupted progress at any resource level.</p>\n<p>↩ Batch-size and learning-rate adjustment and communication-group contraction during elastic recovery are established in @sec-fault-tolerance-reliability-reliability-elastic-training-mechanisms-49b1.</p>\n<h3 id=\"sec-25\" class=\"cs-h3\">The scheduler-framework contract</h3>\n<p>If a scheduler reclaims four nodes from a running job by abruptly killing their containers, or adds four idle nodes without triggering a new rendezvous, the surviving ranks treat the change as a fatal collective timeout rather than an elastic resize. Resizing a live job without crashing it requires an explicit contract between the scheduler and the training framework. For planned resizing, the scheduler and framework coordinate resource release through defined signals and an agreed adaptation window. Unexpected failures can bypass that window, so the framework must also recover from valid saved state. Its recovery path reconstructs communication groups and either preserves the global batch or applies a validated batch-size and learning-rate policy. The worker-membership lifecycle therefore behaves as a state machine centered on active training (@fig-fleet-orchestration-elastic-state-machine). Idle GPUs trigger scale-up, preemptions trigger scale-down, and host timeouts or ECC errors divert ranks to worker replacement; each path returns to active training once the communication group is rebuilt or a spare node joins.</p>\n<p>From the scheduler's perspective, this contract is defined by three governing parameters: the elastic range, the transition cost, and the scaling efficiency curve. The elastic range, $[\\ElasticMinimumWorkerCount, \\ElasticMaximumWorkerCount]$, specifies lower and upper worker bounds; the job's parallelism layout determines the valid allocation increments within them. The transition cost includes any checkpoint, restart, state redistribution, and rendezvous required by the runtime. Measuring the full interruption determines how frequently the scheduler can trigger reallocations before transition overhead wipes out any throughput advantage. Finally, the scaling efficiency curve quantifies throughput at each worker count relative to linear scaling. The marginal throughput of each added worker follows from that curve and indicates whether assigning idle GPUs to this job yields more aggregate progress than holding them for an assembling gang-scheduled workload. Together, these parameters provide the scheduler with the quantitative bounds needed to resize jobs dynamically without treating elasticity as free capacity.</p>\n<p>The scheduler must also account for the effect of worker count on global batch size ($\\GlobalBatchSize = \\PerWorkerBatchSize\\times \\DeviceCount$), where the per-worker batch counts examples contributing to one optimizer update, including gradient accumulation. Holding the global batch constant requires each remaining worker to process more examples after a shrink. Larger microbatches consume more memory; additional accumulation steps extend the update time. Preserving the batch removes one source of optimization change but does not guarantee identical convergence. Allowing the global batch to change instead requires validating the learning-rate policy and resulting model quality, so throughput alone cannot determine the best allocation.</p>\n<pre class=\"cs-code\"><code># Launch elastic training with min 32 to max 128 workers\ntorchrun \\\n  --nnodes=4:16 \\\n  --nproc_per_node=8 \\\n  --rdzv_backend=c10d \\\n  --rdzv_endpoint=head-node:29500 \\\n  --max_restarts=3 \\\n  train.py</code></pre>\n<p>TorchElastic sets the elastic range in its launch configuration as a minimum and maximum node count (@lst-fleet-orchestration-torchelastic). There, the <code>--nnodes=4:16</code> specification configures TorchElastic's rendezvous and worker-membership range as 4 to 16 nodes (32 to 128 workers with 8 processes per node). It does not acquire or resize cluster resources; a separate cluster scheduler or operator must place the nodes and start or stop elastic agents as capacity changes.</p>\n<p>Consider a congested cluster where a <code>[ElasticVsRigid.full_gpus_str]</code>-GPU data-parallel job, with no model-parallel constraint on its worker count, waits <code>[ElasticVsRigid.wait_h_str]</code> hours for a full gang allocation. This first comparison assumes throughput scales linearly with worker count, equivalent learning progress per processed example, and negligible resize overhead; the later scaling decision relaxes the throughput and transition assumptions.</p>\n<p><strong>Rigid scheduling</strong>: Wait <code>[ElasticVsRigid.wait_h_str]</code> hours, then train for <code>[ElasticVsRigid.full_run_h_str]</code> hours at full throughput. Total wall-clock: <code>[ElasticVsRigid.rigid_total_h_str]</code> hours.</p>\n<p><strong>Elastic scheduling</strong> (min <code>[ElasticVsRigid.min_gpus_str]</code>, max <code>[ElasticVsRigid.full_gpus_str]</code>):</p>\n<ul class=\"cs-list\">\n<li>Start immediately with <code>[ElasticVsRigid.min_gpus_str]</code> GPUs (throughput = <code>[ElasticVsRigid.frac_min_pct_str]</code> of full)</li>\n<li>At hour <code>[ElasticVsRigid.step_up_h_str]</code>, when <code>[ElasticVsRigid.mid_gpus_str]</code> GPUs free, scale to <code>[ElasticVsRigid.mid_gpus_str]</code> (throughput = <code>[ElasticVsRigid.frac_mid_pct_str]</code>)</li>\n<li>At hour <code>[ElasticVsRigid.wait_h_str]</code>, when the full gang frees and the rigid job would also start, scale to <code>[ElasticVsRigid.full_gpus_str]</code> (throughput = 100 percent)</li>\n</ul>\n<p>Work completed during the <code>[ElasticVsRigid.wait_h_str]</code>-hour queue wait, in hours of full-scale training:</p>\n<ul class=\"cs-list\">\n<li>Hours 0 to <code>[ElasticVsRigid.step_up_h_str]</code>: <code>[ElasticVsRigid.frac_min_pct_str]</code> throughput $\\times$ <code>[ElasticVsRigid.step_up_h_str]</code> hours = <code>[ElasticVsRigid.work_phase1_str]</code></li>\n<li>Hours <code>[ElasticVsRigid.step_up_h_str]</code> to <code>[ElasticVsRigid.wait_h_str]</code>: <code>[ElasticVsRigid.frac_mid_pct_str]</code> throughput $\\times$ <code>[ElasticVsRigid.phase2_h_str]</code> hours = <code>[ElasticVsRigid.work_phase2_str]</code></li>\n<li>Total: <code>[ElasticVsRigid.work_during_wait_str]</code> hours of equivalent full-scale work</li>\n</ul>\n<p>The elastic job completes in approximately <code>[ElasticVsRigid.elastic_total_h_str]</code> hours (<code>[ElasticVsRigid.wait_h_str]</code> hours of partial-scale training plus <code>[ElasticVsRigid.remaining_h_str]</code> hours at full scale), saving <code>[ElasticVsRigid.saving_h_str]</code> hours compared to rigid scheduling. This improvement of about <code>[ElasticVsRigid.saving_pct_str]</code> comes entirely from using resources productively during what would otherwise be idle queue time.</p>\n<p>Even within a declared node range such as 4 to 16 nodes, the scheduler cannot treat every worker count as a valid elastic configuration. Model parallelism constrains the allocation increment when the resize policy keeps tensor and pipeline layouts fixed and adds or removes whole data-parallel replicas. For a 175B-parameter job that relies on <code>[ElasticNodeRange.tp_degree_str]</code>-way tensor parallelism within each node and <code>[ElasticScalingCurve.pp_str]</code> pipeline stages across nodes, this policy operates at the granularity of a whole model replica of <code>[ElasticScalingCurve.replica_str]</code>. The pipeline depth of <code>[ElasticScalingCurve.pp_str]</code> is the smallest power of two at which each GPU's share of the mixed-precision Adaptive Moment Estimation (Adam) training state fits in its HBM when that state is not sharded across replicas. The layout of @sec-distributed-training-systems instead uses a shallower pipeline and shards optimizer state across the data-parallel group with ZeRO (@sec-distributed-training-systems-systems-memoryefficient-data-parallelism-zero-fsdp-0e69). This job gives up that sharded layout on purpose. Keeping each replica's state self-contained costs memory, but it lets the scheduler add or remove a replica without redistributing every other replica's optimizer shards. The 175B examples in @sec-fleet-orchestration-elastic-policies assume these self-contained replicas. The job can scale between <code>[ElasticNodeRange.max_nodes_str]</code> nodes (<code>[ElasticNodeRange.max_gpus_str]</code> GPUs) and <code>[ElasticNodeRange.min_nodes_str]</code> nodes (<code>[ElasticNodeRange.min_gpus_str]</code> GPUs) one replica at a time, changing the data-parallel degree. Removing a single GPU from a tensor-parallel group would instead require a new sharding layout and redistribution of training state. Changing the pipeline degree would also require repartitioning stages and rebuilding the pipeline schedule. A runtime that supports these transitions can expose them to the scheduler, but their feasibility and measured costs belong in the resize contract rather than following automatically from data-parallel elasticity.</p>\n<p>The transition cost also constrains the scheduler's resize frequency. Each scaling event can interrupt useful work while the framework reconstructs its communication group and restores or redistributes state. The duration must be measured for the chosen runtime and checkpoint path. The scheduler must amortize this cost over the subsequent run duration, so small resize increments are only worthwhile if the job will run at the new scale for significantly longer than the transition window, a test that @sec-fleet-orchestration-elastic-policies applies to resize policies.</p>\n<h3 id=\"sec-26\" class=\"cs-h3\">Scheduler integration</h3>\n<p>Without scheduler integration, a job that declares an elastic range $[\\ElasticMinimumWorkerCount, \\ElasticMaximumWorkerCount]$ in its launch script still waits in the queue for its full node count and still gets killed outright when a higher-priority job arrives. Integrating the $[\\ElasticMinimumWorkerCount, \\ElasticMaximumWorkerCount]$ bounds into the scheduler lets it start a job early at the minimum, expand the job into newly idle capacity, or shrink it to release borrowed capacity without terminating the logical job. Which action wins depends on the job's scaling curve and transition cost, and the policies below compare the choices by the work completed over the same time window.</p>\n<p>Each action must respect the framework contract. The most consequential of the three is <strong>graceful preemption</strong>: when higher-priority work arrives, the scheduler first shrinks an elastic job toward $\\ElasticMinimumWorkerCount$, reclaiming whole replicas at the next resize boundary, and resorts to checkpoint-and-preempt only when the final viable group itself must yield. Quota borrowing across teams, developed in @sec-fleet-orchestration-multi-tenancy, depends on this primitive whenever an owner reclaims capacity it lent. Scaling curves and transition costs determine whether the extra progress repays the disruption. Because batch changes can affect convergence, the test of a resize is time to target model quality, not throughput. Throughput counts examples per second, but a changed global batch can change how many examples the run needs to reach its target quality, so an expansion helps only when the faster rate outweighs any added examples.</p>\n<h3 id=\"sec-27\" class=\"cs-h3\">Elastic scaling policies</h3>\n<p>Adding resources to a running job does not always accelerate time-to-convergence. Communication and synchronization overhead limit throughput gains, requiring the scheduler to enforce elastic scaling policies based on empirical efficiency curves rather than resource availability alone. With fixed global work per step, a job's scaling efficiency $\\ScalingEfficiency(\\ScalingCurveWorkerCount)$ at $\\ScalingCurveWorkerCount$ workers (definition \\ref{dfn-distributed-training-scaling-efficiency}) typically passes through three regimes. In the near-linear regime, per-worker computation dwarfs every fixed per-step cost. In the sublinear regime, pipeline fill and drain and the unhidden part of gradient synchronization become a visible share of each step. In the saturation regime, those fixed costs rival the shrinking computation itself. Assigning available GPUs to a saturated job can yield less useful progress than serving queued work. The lower allocation bound answers a different question. Below its <strong>minimum viable scale</strong>, a job may lack the memory or complete parallel groups needed to execute at all. A policy can impose a higher minimum to meet a deadline, even when a smaller allocation remains computationally efficient.</p>\n<p>The 175B reference job shows these regimes with the chapter's own numbers. Modeled at a fixed global batch with the step-time decomposition of the Fleet Law (@eq-fleet-law), its scaling efficiency falls from <code>[ElasticScalingCurve.eff_min_str]</code> at <code>[ElasticNodeRange.min_gpus_str]</code> GPUs to <code>[ElasticScalingCurve.eff_max_str]</code> at <code>[ElasticNodeRange.max_gpus_str]</code> GPUs and <code>[ElasticScalingCurve.eff_top_str]</code> at <code>[ElasticScalingCurve.top_gpus_str]</code> (@fig-fleet-orchestration-scaling-efficiency-curve, panel a). Efficiency falls, yet quadrupling from <code>[ElasticNodeRange.max_gpus_str]</code> to <code>[ElasticScalingCurve.top_gpus_str]</code> still raises throughput <code>[ElasticScalingCurve.thr_gain_mult_str]</code>, so a lower efficiency is a declining marginal return rather than a slowdown. Panel (b) locates the loss. Tensor-parallel communication shrinks along with each worker's computation, so its share of the step never rises above <code>[ElasticScalingCurve.tp_share_str]</code>. The decline comes instead from pipeline fill and drain and unhidden gradient synchronization, which take roughly fixed time per step while each worker's share of the batch shrinks. The pipeline bubble grows fastest of the three, for a reason the bubble fraction $(\\PipelineParallelDegree-1)/(\\MicrobatchCount+\\PipelineParallelDegree-1)$ of @sec-distributed-training-systems-systems-pipeline-parallelism-8748 makes explicit. With the global batch fixed, each added replica takes a share of the sequences, so the microbatch count $\\MicrobatchCount$ per replica falls while the stage count stays at <code>[ElasticScalingCurve.pp_str]</code>, and the idle fraction rises.</p>\n<p>The shaded window from <code>[ElasticNodeRange.min_gpus_str]</code> to <code>[ElasticNodeRange.max_gpus_str]</code> GPUs is therefore a policy choice, not an interval derived from these efficiencies alone. A minimum allocation could follow from a completion deadline or the job's declared resource contract. It does not follow from insufficient per-worker computation at smaller scale, since with fixed global work fewer workers generally perform more work each. The upper limit likewise requires comparing additional useful progress with resize cost and the value of serving queued jobs. A real scheduler must obtain those inputs from profiling and the workload's quality target.</p>\n<p>This logic extends to the temporal dimension, where the scheduler must weigh the immediate progress of a smaller allocation against waiting for a larger one. If a 512-GPU job can start immediately with 128 GPUs or wait for the full request, the better choice depends on the integration of throughput over time. The resize overhead (the cost of stopping, checkpointing, and restarting when the runtime requires them) must be amortized over the subsequent run duration. A policy of \"opportunistic scaling\" that resizes a job every time a single node becomes free can lose its throughput advantage to repeated interruptions, completing less useful work than a stable allocation.</p>\n<p>The comparison of elastic and rigid scheduling above assumed linear scaling and free resizing; this decision drops both assumptions. Consider a training job with a target batch size that requires <code>[ElasticScaling.es_peak_gpus_str]</code> GPUs for the highest throughput among the configurations considered. Three scheduling strategies are evaluated over a window of <code>[ElasticScaling.es_window_h_str]</code>.</p>\n<p><strong>Given</strong>: Throughput at <code>[ElasticScaling.es_gpus_128_str]</code> is <code>[ElasticScaling.es_tp_128_str]</code> epoch/hour (baseline). Throughput at <code>[ElasticScaling.es_gpus_256_str]</code> is <code>[ElasticScaling.es_tp_256_str]</code> epochs/hour (<code>[ElasticScaling.es_eff_256_pct_str]</code> scaling efficiency relative to that baseline). Throughput at <code>[ElasticScaling.es_s2_gpus_str]</code> is <code>[ElasticScaling.es_tp_512_str]</code> epochs/hour (<code>[ElasticScaling.es_eff_512_pct_str]</code> scaling efficiency). Re-scaling cost is <code>[ElasticScaling.es_rescale_min_str]</code> (<code>[ElasticScaling.es_rescale_hours_str]</code>) to checkpoint, re-shard, and restart.</p>\n<p><strong>Strategy 1 (immediate start, no scaling)</strong>: The job starts immediately with <code>[ElasticScaling.es_s1_gpus_str]</code> and runs for the full <code>[ElasticScaling.es_window_h_str]</code>. Total work: <code>[ElasticScaling.es_s1_math]</code> epochs.</p>\n<p><strong>Strategy 2 (wait for the full allocation)</strong>: The job waits in the queue for <code>[ElasticScaling.es_wait_h_str]</code> until <code>[ElasticScaling.es_s2_gpus_str]</code> become available, then runs for <code>[ElasticScaling.es_s2_run_h_str]</code>. Total work: <code>[ElasticScaling.es_s2_math]</code> epochs.</p>\n<p><strong>Strategy 3 (elastic step-up)</strong>: The job starts immediately with <code>[ElasticScaling.es_gpus_128_str]</code>. After <code>[ElasticScaling.es_wait_h_str]</code>, the capacity that lets Strategy 2 start frees up, but the elastic policy caps growth at <code>[ElasticScaling.es_gpus_256_str]</code> so that the remaining GPUs stay available to queued jobs. The job pauses, scales up, and resumes. Phase 1: <code>[ElasticScaling.es_s3p1_math]</code> epochs. Phase 2: <code>[ElasticScaling.es_s3p2_math]</code> epochs. Total work: <code>[ElasticScaling.es_s3p1_str]</code> + <code>[ElasticScaling.es_s3p2_str]</code> = <code>[ElasticScaling.es_s3_str]</code> epochs.</p>\n<p>The elastic strategy completes nearly <code>[ElasticScaling.es_vs_imm_factor_mult_str]</code> the epoch-equivalent work of the immediate small-scale run, but still trails the full allocation by about <code>[ElasticScaling.es_trails_wait_pct_str]</code>. That comparison counts this job's epochs, not the GPU-hours spent on them. Strategy 2 holds twice as many GPUs as Strategy 3 for most of the window and runs them at <code>[ElasticScaling.es_eff_512_pct_str]</code> scaling efficiency against Strategy 3's <code>[ElasticScaling.es_eff_256_pct_str]</code>. The elastic job therefore does more work per GPU-hour, and the GPUs it leaves free serve queued jobs. Which strategy wins therefore depends on whether the fleet values this job's completion time or the total work completed across all jobs. That gap shrinks when queue waits grow or peak capacity stays scarce. Re-scaling overhead is only <code>[ElasticScaling.es_rescale_min_str]</code>, so the step-up strategy keeps its lead over the immediate small-scale run unless slow checkpoint transfer or compilation stretches that overhead beyond about <code>[ElasticScaling.es_rescale_break_even_h_str]</code>.</p>\n<p>Placement and elasticity determine which allocations are feasible and how much useful progress they produce across competing jobs. Fleet economics adds the price of those choices. Every placement, preemption, and reservation consumes capacity that could serve another workload, so the scheduler must compare both useful progress and opportunity cost.</p>\n<h2 id=\"sec-28\" class=\"cs-h2\">Cost Optimization</h2>\n<p>An idle accelerator in an enterprise fleet incurs operational costs every hour whether computing or blocked in a queue, turning placement and preemption decisions into direct financial trade-offs. The orchestrator translates this utilization-to-dollars relationship from @sec-fleet-orchestration-introduction into an online scheduling signal, balancing resource prices, reservation commitments, interruption risk, checkpoint cost, and job deadlines to decide whether to admit, delay, preempt, or resize work. Capital planning, portfolio return, cost attribution, and lifecycle total cost of ownership are larger, slower decisions developed in @sec-ops-scale-fleet-economics; the scheduler consumes their outcomes as prices and constraints.</p>\n<p>At a fixed utilization, idle capacity grows linearly with fleet size, so the dollar cost of a scheduling inefficiency grows with every procurement (@fig-cost-idle-gpus). At <code>[IdleCostAnchors.n_gpus_str]</code> GPUs operating at <code>[IdleCostAnchors.util_low_str]</code> utilization, annual waste reaches <code>[IdleCostAnchors.waste_low_str]</code> under the chapter's <code>[IdleCostAnchors.gpu_hour_str]</code>/GPU-hour accounting scenario. Published measurements show that such underutilization occurs in production. Microsoft's Philly cluster study [@jeon2019analysis] measured mean GPU utilization of approximately <code>[IdleCostAnchors.philly_util_str]</code>. The 30 to 70 percent shaded band in the figure is an illustrative operating range for the cost model, not a universal empirical claim about all production clusters. Moving from <code>[IdleCostAnchors.util_low_str]</code> to <code>[IdleCostAnchors.util_mid_str]</code> utilization, the improvement priced in the chapter opening, recovers over <code>[IdleCostAnchors.recovered_str]</code> annually in equivalent capacity value. That recovered value represents the same <code>[ClusterEconomicsContext.productive_gpu_gain_str]</code> GPU-equivalents the opening counted as the recoverable <code>[ClusterEconomicsContext.idle_pct_str]</code> idle share, and it becomes cash savings only when it avoids billed usage or a planned purchase.</p>\n<p>Recovering that idle capacity requires pricing each scheduling lever against the disruption it causes. Because reclaiming GPUs from running jobs is the most direct way to admit higher-value work, the cost of a single preemption and the cascades it can trigger come first. Discounted spot capacity then lowers the hourly price of restart-tolerant training, diversification and checkpoint policies keep correlated reclamations from erasing that discount, and capacity-reservation tiers combine with workload cost policies to route jobs across reserved, on-demand, and interruptible pools.</p>\n<h3 id=\"sec-29\" class=\"cs-h3\">Preemption cost and cascades</h3>\n<p>When a high-priority job enters a saturated cluster, the scheduler must decide which running workloads to terminate to free up resources. This decision is rarely isolated. In tightly packed clusters, evicting a medium-priority job to accommodate a high-priority request often triggers a <strong>preemption cascade</strong>, where the evicted job immediately attempts to reschedule itself by displacing lower-priority workloads. The disruption multiplies with each level. If the urgent job displaces $\\PreemptionFanoutCount$ medium-priority jobs and each of those, on rescheduling, displaces $\\PreemptionFanoutCount$ lower-priority jobs, one admission interrupts $\\PreemptionFanoutCount+ \\PreemptionFanoutCount^2$ jobs after two levels. Every one of them pays the preemption overhead quantified next and adds a checkpoint reload to the storage system at the same moment. Two dampening controls cap that growth. A rule that evicted jobs requeue without preempting anyone themselves stops the chain at the first level, so one admission costs at most $\\PreemptionFanoutCount$ interruptions. A <strong>preemption budget</strong> limits how often any single job, or what fraction of capacity, may be displaced in a time window, which protects the jobs at the bottom of the priority order that every chain would otherwise reach.</p>\n<p>Sizing that preemption budget requires pricing an engineering cost that extends beyond scheduling latency. The <strong>preemption overhead</strong> depends on the exit path. A successful graceful checkpoint adds the time to save and restart while preserving completed progress; a forced stop can instead discard work since the last durable checkpoint. Consider such a victim, a forced interruption of the <code>[PreemptionTax.gpus_str]</code>-GPU fine-tuning run for our 175B parameter model. The scenario assumes lost work equivalent to <code>[PreemptionTax.lost_min_str]</code> of execution. The restart then repeats the cold-restart steps of the recovery budget in @sec-fault-tolerance-reliability-reliability-recovery-procedures-002d, without its detection step because the scheduler itself stopped the job. These steps take <code>[PreemptionTax.restart_min_str]</code> to relaunch, <code>[PreemptionTax.reload_s_str]</code> to reload the <code>[PreemptionTax.ckpt_tb_str]</code> checkpoint with its optimizer state, and <code>[PreemptionTax.warmup_min_str]</code> of warmup as data pipelines refill and just-in-time (JIT) compilation and runtime initialization complete. The calculation prices replay and restart across the same allocation; it does not also charge for a successful final save.</p>\n<p>Reconstructing the distributed data pipeline also belongs in the preemption contract. The checkpoint must preserve the sampling and loader state needed to resume the intended data order, alongside model and optimizer state. If the restart path omits that state, it can repeat or skip samples and lose exact replay of the training trajectory. A different shuffle order does not by itself prove statistical corruption, but the recovery policy must specify which changes are acceptable. The scheduler should therefore measure restoration and pipeline warmup as part of recovery cost, rather than assume that reloading model weights alone makes the job productive.</p>\n<p>The resulting <code>[PreemptionTax.recovery_duration_min_attr_str]</code> overhead combines discarded execution, its larger part, with relaunch, reload, and warmup time; it is not a measurement of continuous kernel activity after eviction. Spread over the run, it belongs to the Fleet Law's coordination term $\\SynchronizationTime(\\DeviceCount)$ (@eq-fleet-law), which counts scheduling decisions and failure recovery alongside barrier waits, so frequent preemption lengthens the average step exactly as frequent failure does. At <code>[PreemptionTax.gpu_hour_rate_str]</code>, the scenario values each event at <code>[PreemptionTax.cost_per_event_str]</code> in allocation time. A low-priority run sits at the bottom of every cascade, so without a budget it can be struck many times a day. At the scenario's <code>[PreemptionTax.preemptions_per_day_str]</code> forced preemptions per day, it loses <code>[PreemptionTax.wasted_duration_per_day_h_str]</code> of equivalent allocation time, or <code>[PreemptionTax.wasted_gpu_hours_per_day_str]</code> for this <code>[PreemptionTax.gpus_str]</code>-GPU run. A per-job budget bounds that loss directly. When a budget is exhausted, the scheduler must consider waiting, another placement, or a defined emergency exception. The trade-off is reduced recovery churn against delayed admission, measured under the workload's deadlines.</p>\n<h3 id=\"sec-30\" class=\"cs-h3\">Spot instances and preemptible VMs</h3>\n<p>Where internal priority preemption reclaims capacity for a higher-priority tenant within the same fleet, cloud fleets face an external preemption trade-off between price and reclamation risk. Renting on-demand cloud GPUs for a multi-week training run protects the job from provider reclamation, but pays full price even when spare GPUs sit idle in the provider's data center. Renting interruptible capacity cuts the hourly rate by <code>[FleetSpotPricing.discount_lo_num_str]</code> to <code>[FleetSpotPricing.discount_hi_pct_str]</code>, but lets the provider reclaim those GPUs on best-effort notice. Cloud providers sell this spare capacity through spot instances (AWS) or <strong>preemptible VMs</strong> (GCP), where actual discounts depend on the resource and market. The reference interruption windows range from up to <code>[FleetSpotPricing.gcp_notice_str]</code> for GCP preemptible shutdown to <code>[FleetSpotPricing.aws_notice_str]</code> for AWS stop or termination notices, with best-effort delivery rather than a guaranteed recovery interval. At the scenario rates of <code>[FleetSpotPricing.spot_price_str]</code> instead of <code>[FleetSpotPricing.on_demand_price_str]</code>, the worked comparison that follows shows how savings can exceed half the on-demand cost after accounting for its assumed interruption overhead.</p>\n<p>: <strong>Spot instances</strong>: The scenario's <code>[FleetSpotPricing.discount_lo_num_str]</code> to <code>[FleetSpotPricing.discount_hi_pct_str]</code> discount purchases reclaimable capacity, not a guaranteed interval for saving state. AWS's best-effort stop or termination notice targets <code>[FleetSpotPricing.aws_notice_str]</code>, while GCP preemptible shutdown allows up to <code>[FleetSpotPricing.gcp_notice_str]</code>; AWS hibernation begins immediately. If a job's measured checkpoint time exceeds the reference <code>[FleetSpotPricing.gcp_notice_attr_str]</code> window, a notice-triggered save cannot be its only recovery path.</p>\n<p>The viability of spot instances for ML training depends on two factors that determine whether the discount translates into actual savings. The first is the cost of each interruption (checkpoint overhead plus restart time plus lost work since the last checkpoint). The second is the frequency of interruption (which varies by instance type, region, time of day, and overall cloud demand). @Eq-fleet-orchestration-spot-cost gives the <strong>effective cost</strong> of spot training:</p>\n<p>$$ \\EffectiveSpotTrainingCost= \\SpotHourlyPrice\\times \\frac{\\BilledAllocationTime}{\\RetainedProductiveTime} $$ {#eq-fleet-orchestration-spot-cost}</p>\n<p>where $\\BilledAllocationTime$ is billed allocation time, including checkpointing, recovery, and work later discarded after an interruption, and $\\RetainedProductiveTime$ is the equivalent training time represented by retained progress. The ratio assumes a fixed allocation size and price, with unchanged useful throughput while training; variable allocations require summing the cost of each allocation interval. Waiting for replacement capacity extends completion time but contributes to billed time only while resources remain allocated. When checkpointing and interruption losses consume a small fraction of billed time, effective cost stays near the spot price. Frequent interruptions, expensive recovery, or substantial replay can instead erase the discount.</p>\n<p>Spot savings and fault tolerance infrastructure are coupled. Fault tolerance mechanisms (frequent asynchronous checkpointing, fast checkpoint loading, elastic recovery) make spot capacity usable by lowering the cost of each interruption. Elastic training can resume a logical job with fewer workers after reclamation, provided the remaining allocation is viable, although the framework may still restart worker processes and restore checkpointed state, so elasticity reduces recovery cost rather than eliminating it. The same infrastructure therefore earns a double return. It protects against hardware losses, and it enables the deliberate use of interruptible capacity. Both benefits require measurement. The scheduler combines observed interruption rates, recovery costs, and retained training progress with resource prices to estimate whether spot savings repay the additional recovery infrastructure. The same evidence supports valuing protection against hardware failures; neither benefit follows from the discount or checkpoint mechanism alone.</p>\n<h3 id=\"sec-31\" class=\"cs-h3\">Spot instance strategies for ML training</h3>\n<p>Spot capacity pays off only when an interruption rarely removes the whole job at once, so schedulers that use it diversify where capacity comes from instead of simply retrying on failure. Availability zone diversification reduces the probability of simultaneous fleet-wide reclamation. Cloud providers typically manage spot pools independently per availability zone (AZ). If a training job requires <code>[ClusterEconomicsContext.gang_job_gpus_str]</code> GPUs, allocating them as a single block in one zone exposes the job to a complete stop if that specific zone's spot pool is reclaimed. Diversifying independent jobs or restart destinations across zones reduces exposure to one exhausted pool. Splitting a single synchronous gang across zones also changes its communication paths, so the scheduler must include cross-zone bandwidth, latency, and transfer costs before accepting that placement. The scheduler still must model correlation carefully: independent per-instance interruptions make large simultaneous losses unlikely, but pool-level or AZ-level reclamations can remove hundreds of GPUs at once and must be treated as elastic-shrink or failover events rather than ordinary isolated failures.</p>\n<p>Instance type diversification expands the set of capacity pools a job can use, though availability across those pools can remain correlated. A job that requests only one instance type cannot use spare capacity in another pool. Accepting alternatives therefore requires a compatibility list that includes memory capacity, runtime support, communication paths, and measured throughput. An instance with more memory can still be an unsuitable substitute if its runtime support, communication paths, or throughput differ. The scheduler compares each feasible alternative's price and recovery cost per unit of retained progress; mixing devices within a synchronous gang also requires accounting for unequal worker speeds.</p>\n<p>Spot capacity signals can guide placement but do not necessarily predict interruption frequency. For example, the AWS Spot Placement Score estimates the current likelihood that a capacity request will succeed in a region or availability zone; it explicitly does not predict interruption risk. A scheduler can use this signal to choose where to request capacity, but estimating interruptions per day requires separate historical measurements for the instance type and region. If the resulting workload-specific recovery model shows that interruption overhead erases the discount, the scheduler should migrate the job to on-demand capacity or a different region.</p>\n<p>Checkpoint frequency optimization for spot instances extends the reliability logic. The Young-Daly formula developed in @sec-fault-tolerance-young-daly models losses from unpredicted interruptions, whether caused by hardware failure or reclamation without a usable warning. Provider notices offer an additional opportunity to save state, using the reference windows of <code>[FleetSpotPricing.aws_notice_str]</code> on AWS and up to <code>[FleetSpotPricing.gcp_notice_str]</code> on GCP preemptible VMs. A <strong>two-tier checkpointing</strong> approach combines periodic checkpoints, with an interval chosen for the workload's interruption model, and a best-effort checkpoint triggered by a notice. The notice-triggered checkpoint reduces lost work only if it becomes durable before reclamation; otherwise, the job restores its last durable state, whether produced by a periodic, asynchronous, or incremental checkpoint, and replays subsequent work. That contingency planning matters more when spot interruptions are correlated across a pool rather than isolated to single machines.</p>\n<p><strong>Context</strong>: Spot capacity is cheap because it is reclaimable. That risk is not independent across instances: cloud regions, instance types, product launches, and deadline cycles can create correlated demand.</p>\n<p><strong>Failure mode</strong>: A fleet that concentrates all interruptible training in one region and one instance type can lose a large fraction of workers at once, even if each individual worker appears restartable.</p>\n<p><strong>Consequence</strong>: Checkpointing handles isolated interruptions; it does not solve fleet-wide preemption when every retry targets the same exhausted pool.</p>\n<p><strong>Systems insight</strong>: A robust scheduler diversifies compatible restart destinations, monitors interruption risk, and plans an on-demand fallback when spot capacity cannot meet the job's deadline or cost target. That fallback still depends on available capacity and the time needed to restore state.</p>\n<h3 id=\"sec-32\" class=\"cs-h3\">Capacity reservation strategies</h3>\n<p>Committing to long-term reserved capacity for 100 percent of peak demand leaves expensive GPUs idle whenever traffic dips, while relying solely on spot or on-demand pools risks capacity shortages during product launches and sudden reclamations during deadline crunches. To avoid paying for idle reservations or starving urgent workloads, organizations that rely on cloud infrastructure (or that price on-premises capacity in economic terms) combine three tiers of compute capacity. Each tier trades cost and commitment against availability and interruption risk (@tbl-cloud-capacity-reservation-tiers).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Capacity tier</strong></th><th><strong>Cost and commitment</strong></th><th><strong>Availability and interruption risk</strong></th><th><strong>Best-fit workloads</strong></th></tr></thead><tbody>\n<tr><td><strong>Reserved capacity</strong></td><td>Capacity reservation; price discounts require a separate purchasing contract.</td><td>Capacity assurance within the reservation terms; startup still takes time.</td><td>Predictable continuous workloads: 24/7 inference, scheduled training, CI and regression testing, jobs under service-level agreements (SLAs).</td></tr>\n<tr><td><strong>On-demand capacity</strong></td><td>Full price with no long-term commitment.</td><td>Admission depends on available capacity; provisioning and startup add delay.</td><td>Urgent retraining, interactive debugging, and short-lived jobs that do not justify spot management.</td></tr>\n<tr><td><strong>Spot capacity</strong></td><td>Discounted interruptible capacity.</td><td>Availability varies with cloud demand, and workers can be reclaimed.</td><td>Restart-tolerant jobs: hyperparameter sweeps, ablations, checkpointed pretraining, and exploratory research.</td></tr>\n</tbody></table></div>\n<p>: <strong>Cloud Capacity Reservation Tiers</strong>: Capacity tiers trade cost and commitment against availability guarantees and interruption risk, giving the scheduler a price ladder for routing workloads by urgency and restart tolerance. {#tbl-cloud-capacity-reservation-tiers tbl-colwidths=\"[18,25,27,30]\"}</p>\n<p>The constructed portfolio in @fig-fleet-orchestration-capacity-reservation divides capacity into a reserved tier covering the steady 60 percent baseline, an on-demand band between 60 and 80 percent, and an interruptible spot tier serving peaks up to 92 percent. An organization with 60 percent steady-state utilization and 40 percent burst demand might reserve capacity for 60 percent of peak need, use on-demand for bursts whose deadlines tolerate admission and startup delay, and use spot for restart-tolerant work. These shares illustrate a policy rather than establish an optimal portfolio. The scheduler must match each workload's deadline and recovery contract to the capacity tier. Reserved capacity can support the steady serving load or a training job's base allocation, while spot can support elastic replicas or independent experiments that tolerate reclamation. A peak in urgent demand cannot automatically be assigned to spot merely because it lies above the reserved band.</p>\n<p>Consider training a <code>[SpotTrainingEconomics.model_params_b_str]</code> parameter model, a smaller workload than the chapter's 175B reference, on <code>[SpotTrainingEconomics.spot_gpus_str]</code> for <code>[SpotTrainingEconomics.spot_run_days_str]</code>. The scenario fixes the event budget at <code>[SpotTrainingEconomics.restart_interruptions_str]</code> over the run and treats each as graceful, so no progress is replayed.</p>\n<p><strong>On-Demand</strong>: <code>[SpotTrainingEconomics.spot_gpus_str]</code> $\\times$ <code>[SpotTrainingEconomics.spot_run_hours_str]</code> $\\times$ <code>[SpotTrainingEconomics.on_demand_rate_str]</code> = <code>[SpotTrainingEconomics.on_demand_cost_str]</code></p>\n<p><strong>Spot</strong> (<code>[SpotTrainingEconomics.spot_discount_pct_str]</code> discount, <code>[SpotTrainingEconomics.checkpoint_overhead_pct_str]</code> checkpoint overhead, <code>[SpotTrainingEconomics.interruptions_per_day_str]</code> per day of useful training with <code>[SpotTrainingEconomics.restart_min_str]</code> restart):</p>\n<ul class=\"cs-list\">\n<li>Base cost: <code>[SpotTrainingEconomics.spot_gpus_str]</code> $\\times$ <code>[SpotTrainingEconomics.spot_run_hours_str]</code> $\\times$ <code>[SpotTrainingEconomics.spot_rate_str]</code> = <code>[SpotTrainingEconomics.spot_base_cost_str]</code></li>\n<li>Checkpoint overhead: <code>[SpotTrainingEconomics.checkpoint_overhead_pct_math]</code> $\\times$ <code>[SpotTrainingEconomics.spot_run_hours_str]</code> = <code>[SpotTrainingEconomics.checkpoint_extra_hours_str]</code></li>\n<li>Restart overhead: <code>[SpotTrainingEconomics.restart_interruptions_str]</code> $\\times$ <code>[SpotTrainingEconomics.restart_hours_each_str]</code> = <code>[SpotTrainingEconomics.restart_total_hours_str]</code></li>\n<li>Total time: <code>[SpotTrainingEconomics.spot_run_hours_str]</code> + <code>[SpotTrainingEconomics.checkpoint_extra_hours_str]</code> + <code>[SpotTrainingEconomics.restart_total_hours_str]</code> = <code>[SpotTrainingEconomics.spot_total_hours_str]</code></li>\n<li>Total cost: <code>[SpotTrainingEconomics.spot_gpus_str]</code> $\\times$ <code>[SpotTrainingEconomics.spot_total_hours_str]</code> $\\times$ <code>[SpotTrainingEconomics.spot_rate_str]</code> = <code>[SpotTrainingEconomics.spot_total_cost_str]</code></li>\n</ul>\n<p><strong>Savings</strong>: <code>[SpotTrainingEconomics.savings_str]</code> (<code>[SpotTrainingEconomics.savings_pct_str]</code>), at the cost of approximately <code>[SpotTrainingEconomics.longer_pct_str]</code> longer wall-clock time.</p>\n<p>These savings assume fault tolerance infrastructure is already in place. Without checkpointing, a single interruption forces restart from scratch, potentially wasting days of compute and negating all savings.</p>\n<h3 id=\"sec-33\" class=\"cs-h3\">Cost-aware scheduling policies</h3>\n<p>Once a fleet spans reserved, on-demand, and spot tiers, a newly submitted job can often launch immediately on reserved A100 GPUs or wait two hours for spot H100 instances that, under illustrative assumptions, deliver twice the throughput at half the execution cost. Deciding whether those savings repay the two-hour delay and interruption risk turns the purchasing tiers into an online scheduling decision. Alongside completion time, utilization, and fairness, a cost-aware orchestrator evaluates three recurring trade-offs: waiting versus running immediately, preempting lower-priority work on reserved capacity (such as a hyperparameter sweep) versus routing a high-priority training run to more expensive on-demand instances, and replacing reclaimed spot instances with on-demand nodes versus shrinking elastically. Each choice requires the costs of waiting, recovery, and displaced work as well as the price of the new allocation.</p>\n<p>These decisions require the scheduler to model both the time-value of computation (the organizational cost of a 2-hour delay in researcher productivity, product launch schedules, or competitive position) and the financial cost of different resource allocations. Delaying a production model retrain by 2 hours might violate a service level agreement (SLA), while the same delay to an exploratory experiment can postpone a research decision or block dependent work. A workload class's delay tolerance is therefore a policy input grounded in its dependencies and deadlines, not an assumption that exploratory work has no time cost.</p>\n<p>Production systems can define <strong>cost policies</strong> per workload class that encode these trade-offs as configuration rather than requiring per-decision human judgment. One policy places steady inference demand on reserved capacity and maintains ready replicas to meet its latency target; the reservation alone does not guarantee application availability or latency. Large training runs can combine a reserved minimum viable allocation with interruptible elastic expansion, requesting on-demand replacements when a deadline justifies the cost and capacity is available. Exploratory workloads with flexible deadlines can use spot capacity while accepting interruptions and variable completion times. These assignments express the organization's priorities rather than a universal mapping from workload type to purchasing tier.</p>\n<p>The scheduler does not implement the organization's financial accounting system. It consumes the resulting price and policy signals: the marginal price of each capacity tier, the reservation a project may claim, the interruption risk it may accept, and the deadline it must meet. That accounting system reports or bills each team for its usage (showback or chargeback) and attributes shared costs; the scheduler uses its outputs only to rank feasible scheduling actions. Lifecycle total cost of ownership (TCO) reaches the scheduler the same way, as per-resource opportunity costs and constraints that record whether capacity is owned, reserved, on demand, or interruptible, rather than as a scheduling mechanism.</p>\n<p>↪ Tag-based cost attribution, shared-cost allocation, and chargeback are developed in @sec-ml-operations-scale-cost-visibility-attribution-3f3a.</p>\n<p>↪ The lifecycle TCO framework, which combines training, inference, data, and iteration costs, is developed in @sec-ml-operations-scale-ml-systems-tco-framework-b980.</p>\n<p>Before moving to ML-specific schedulers, review how the cost-optimization mechanisms interact:</p>\n<ul class=\"cs-list\">\n<li>[ ] <strong>Spot break-even</strong>: identify the additional inputs needed to compute a break-even checkpoint interval for the <code>[SpotTrainingEconomics.spot_gpus_num_str]</code>-GPU, <code>[SpotTrainingEconomics.spot_run_days_attr_str]</code> training job of the spot comparison above (<code>[SpotTrainingEconomics.spot_discount_pct_str]</code> spot discount, <code>[SpotTrainingEconomics.interruptions_per_day_str]</code> per day, <code>[SpotTrainingEconomics.restart_min_attr_str]</code> restart overhead), including checkpoint duration, the interruption-rate clock, and lost-progress assumptions.</li>\n<li>[ ] <strong>Double return</strong>: explain why fault tolerance infrastructure has a \"double return\" for reliability and cost savings, and identify the minimum fault tolerance investment needed to make spot instances viable.</li>\n<li>[ ] <strong>Reservation sizing</strong>: starting from the constructed portfolio that reserves 60 percent of peak, identify the demand history, reservation terms, unit prices, and unused-capacity costs needed to decide whether raising the reserved share to 70 percent reduces total spending.</li>\n</ul>\n<p>Spot pricing and reservation strategy reduce the cost of capacity, but they do not determine which competing job should receive it. Runtime uncertainty, unequal completion delays, and the cost of interrupting an iteration remain even when prices are known. Resolving them requires signals from the workload itself. A scheduler that tracks learning progress can optimize time-to-accuracy, the wall-clock time until a run reaches a target validation metric, rather than execution speed alone.</p>\n<h2 id=\"sec-34\" class=\"cs-h2\">Custom ML Schedulers</h2>\n<p>A short experiment waiting behind a long training run can suffer even when every running job has an efficient placement. Improving that outcome requires a policy for deciding which job receives the next available resources. Custom ML schedulers use different signals to make that decision: consumed service can prioritize jobs without runtime estimates, iteration boundaries can make preemption cheaper, normalized finish time can expose unfair delay, and measured goodput can guide joint resource and batch-size changes. Only the last of these requires a model of learning progress; the others improve completion time, utilization, or fairness without predicting convergence.</p>\n<h3 id=\"sec-35\" class=\"cs-h3\">Duration-agnostic scheduling (Tiresias)</h3>\n<p>When a researcher submits an exploratory training run without knowing whether it will fail in ten minutes or run for a week, scheduling policies that depend on upfront duration estimates (@sec-fleet-orchestration-gang-scheduling) either mispack the queue or penalize inaccurate guesses. <strong>Tiresias</strong> [@gu2019tiresias] eliminates the requirement for duration estimates entirely. It uses a two-dimensional attained service scheduler that makes priority decisions based on what a job has already consumed, not what it claims it will consume. Jobs accumulate \"service\" based on GPU-time consumed, with priority decreasing as service increases. The two dimensions are time (how long the job has been running) and resources (how many GPUs the job uses), capturing both elapsed duration and resource intensity.</p>\n<p>: <strong>Attained service scheduling</strong>: A discipline that uses consumed service to set priority when remaining work is unknown. Unlike shortest remaining processing time (SRPT), it cannot distinguish a newly arrived long job from a short one before either receives service. Its benefit depends on the workload distribution; protection against starvation remains necessary when new jobs repeatedly displace older ones.</p>\n<p>A discretized version groups jobs into service bins (illustratively, less than 1 GPU-hour, 1 to 10 GPU-hours, 10 to 100 GPU-hours, greater than 100 GPU-hours), giving lower-service bins higher priority. When job durations are heavy-tailed, a job that has consumed little service is likely to be short, so favoring low-service jobs approximates shortest-remaining-processing-time ordering without any runtime estimate. New jobs can receive service before long-running jobs, but their eventual duration remains unknown, and a high-priority gang still needs a feasible allocation. Tiresias also promotes jobs that have waited too long, trading some average-completion-time benefit for protection against starvation. The priority rule therefore replaces runtime prediction with an observable signal and an explicit waiting-time policy; it does not guarantee that every short job starts promptly.</p>\n<p>The Tiresias evaluation reports lower average job completion time (JCT) on its testbed and trace-driven workloads [@gu2019tiresias]. The result depends on job arrivals, sizes, and the comparison policy. Prioritizing low-service jobs can delay long-running jobs, so average completion time must be evaluated alongside starvation prevention and the delay experienced by each job class.</p>\n<h3 id=\"sec-36\" class=\"cs-h3\">Iteration-aware scheduling (Gandiva)</h3>\n<p>Preempting a job in the middle of a training step either discards the partial step or requires saving gigabytes of temporary forward-pass activations alongside the model weights. <strong>Gandiva</strong> [@xiao2018gandiva] avoids that mid-step state transfer by exploiting repetitive training iterations to profile jobs and time-slice GPUs at iteration boundaries. To give a GPU to another job, Gandiva suspends the running job at the end of a minibatch, copies its live GPU memory to host memory, and resumes another job on the device; switching back reverses the copy. Several jobs can therefore take turns on one GPU, and the same suspend-and-resume path lets Gandiva migrate a job to better-placed devices or pack compatible jobs onto one GPU when their combined memory fits. The boundary is the cheap place to switch because temporary activations have been released, so far less state must move than in the middle of a step. Weights, optimizer state, and runtime allocations remain, so each switch still costs a transfer proportional to that persistent state, and a job whose persistent state nearly fills the device cannot share it. The scheduler must measure memory demand, interference, and transition cost before admitting additional jobs.</p>\n<p>Gandiva also implements <strong>grow-shrink elasticity</strong>, applying the allocation mechanism of @sec-fleet-orchestration-elastic-training to jobs that explicitly permit resizing. It expands eligible jobs into idle capacity and shrinks them when demand returns, using profiles to estimate which jobs benefit. The published implementation limits growth to one server and waits through an idle period before expanding. Its contribution is the connection between measured job behavior and resource control, rather than a claim that arbitrary training jobs can resize cheaply.</p>\n<h3 id=\"sec-37\" class=\"cs-h3\">Finish-time fairness (Themis)</h3>\n<p>Equal GPU-time shares can produce unequal completion delays when workloads respond differently to placement. <strong>Themis</strong> [@mahajan2020themis] measures fairness in normalized finish time. Each application, which can contain related training jobs, compares its completion time in the shared cluster with its completion time on an isolated $1/\\ContendingApplicationCount$ share of the cluster, where $\\ContendingApplicationCount$ is the number of applications contending for it. The ratio has the same form as the slowdown $\\JobSlowdown_j$ defined with the scheduling objectives, except in its denominator. Themis divides by the completion time on a fair share of the cluster rather than by the isolated runtime on the job's own allocation, so a ratio of one means the application finished no later than its fair share would have allowed.</p>\n<p>Themis targets the worst finish-time fairness ratio across applications. Its auction rounds offer available resources to the applications farthest from fair completion, while allowing placement efficiency to influence which specific GPUs each one receives within a round. With two applications whose current estimates are 1.2 and 2.0, the second is projected to finish twice as late as its fair share would allow, so it enters the round ahead of the first. The first application's ratio rises while it waits, and once it overtakes the second it moves to the front of later rounds. The signal is relative completion delay, not proximity to completion or GPU-hours already consumed.</p>\n<p>Within a round, contending applications bid on candidate GPU subsets by reporting the finish-time fairness ratio they would reach on each subset. Because a communication-heavy job finishes much faster on a compact subset than on a scattered one while a communication-light job sees little difference, these bids expose placement sensitivity rather than monetary willingness to pay. The arbiter can then assign compact subsets to the lagging applications whose finish-time ratios gain the most from locality. This auction trades short-term allocation efficiency against the long-term fairness objective, making the quality of completion-time and placement estimates part of the scheduler's operating assumptions.</p>\n<h3 id=\"sec-38\" class=\"cs-h3\">Adaptive resource allocation (Pollux)</h3>\n<p>Adding GPUs to a running job by increasing its global batch size raises throughput in examples per second. Past the critical batch size, however, each example contributes less optimization progress, so the extra GPUs can slow convergence rather than speed it up. <strong>Pollux</strong> [@qiao2021pollux] addresses this coupling by extending resource adaptation to training hyperparameters. Where Gandiva changes only device allocations, Pollux jointly considers allocation, batch size, and learning-rate scaling because a larger batch can use more devices efficiently while changing the amount of work needed to converge. The preferred configuration can therefore change with both cluster demand and the stage of training.</p>\n<p>Pollux uses statistical goodput to connect system throughput, measured in training examples per second, with statistical efficiency, which measures progress per example relative to a reference batch size. The word goodput already carries two other meanings. The run-level goodput of @sec-vol2-introduction-fleet-law discounts work lost to failures and restarts, and Google's ML productivity goodput multiplies program, runtime, and scheduling factors. Statistical goodput instead discounts each example by the optimization progress it contributes at the current batch size, and @sec-performance-engineering-goodput-family sets the three side by side. Statistical efficiency falls as the batch grows past the critical batch size of @sec-distributed-training-systems-systems-critical-batch-size-parallelism-hurt-4961, which is why more GPUs at a larger batch can raise throughput while lowering goodput. Pollux estimates how allocation and batch changes affect both quantities, then uses those estimates to guide resource sharing across jobs. Additional GPUs are valuable only when their throughput gain survives the corresponding change in statistical efficiency and the cost of changing the allocation.</p>\n<p>The Pollux evaluation reports average job completion times <code>[PolluxReportedJct.jct_lo_num_str]</code> to <code>[PolluxReportedJct.jct_hi_pct_str]</code> lower than the state-of-the-art deep learning schedulers it was compared against, which do not make the same combined adjustment of resources and batch size [@qiao2021pollux]. The number belongs to that testbed and trace. Its durable lesson is the coupling: an allocation can increase samples per second while reducing progress per sample. The scheduler must estimate both effects and validate completion time at the same target quality, rather than transferring a reported improvement to a different workload.</p>\n<h3 id=\"sec-39\" class=\"cs-h3\">Scheduler comparison framework</h3>\n<p>Each research scheduler pursues a different objective, and each objective requires its own observations and controls (@tbl-fleet-orchestration-scheduler-comparison). Consumed service can be obtained from resource accounting, while iteration timing and learning-progress estimates require closer runtime integration. The choice therefore turns on what the platform can observe and control, not on a ranking of scheduler sophistication.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Scheduler</strong></th><th><strong>Key insight</strong></th><th><strong>Scheduling signal</strong></th><th><strong>Optimization target</strong></th><th><strong>Integration requirement</strong></th></tr></thead><tbody>\n<tr><td><strong>Tiresias</strong></td><td>Attained service informs priority</td><td>GPU-hours consumed</td><td>Minimize average JCT</td><td>Resource accounting and queue reprioritization</td></tr>\n<tr><td><strong>Gandiva</strong></td><td>Iteration boundaries enable sharing</td><td>Iteration timing</td><td>Improve utilization</td><td>Runtime profiling and coordinated time slicing</td></tr>\n<tr><td><strong>Themis</strong></td><td>Completion delay defines fairness</td><td>Normalized finish time</td><td>Improve worst fairness</td><td>Finish-time estimates and allocation auctions</td></tr>\n<tr><td><strong>Pollux</strong></td><td>Batch size and allocation are coupled</td><td>Goodput</td><td>Maximize cluster goodput</td><td>Runtime resizing and batch-size adaptation</td></tr>\n</tbody></table></div>\n<p>: <strong>Custom ML Scheduler Comparison</strong>: A taxonomy of research schedulers based on the specific workload characteristic they exploit. Tiresias uses attained-service accounting, Gandiva profiles iterations, Themis estimates relative finish times and placement effects, and Pollux models goodput under allocation and batch-size changes. {#tbl-fleet-orchestration-scheduler-comparison}</p>\n<p>The common lesson is to match the policy signal to the scheduling objective. Attained service addresses runtime uncertainty and can work from accounting records. Iteration boundaries lower the cost of interrupting work but need reliable timing profiles. Normalized finish time measures unequal delay, and goodput couples resource allocation to learning progress, which requires the training loop to accept allocation and batch-size changes. Each added control creates a failure mode of its own: inaccurate profiles can increase interference, and an inaccurate learning-progress model can choose allocations that fail to improve convergence. A platform should therefore test the chosen policy against queue delay, starvation risk, and measured recovery cost before adopting it.</p>\n<h3 id=\"sec-40\" class=\"cs-h3\">From research to production</h3>\n<p>A production cluster containing V100s alongside A100s and H100s, with both InfiniBand and Ethernet paths, gives the same GPU count very different performance across placements, while live jobs crash, hang, or exceed declared memory needs. Because a research scheduler's evaluation establishes results on a specific testbed, workload trace, and set of runtime controls, a production fleet must test whether its own hardware and failure conditions preserve those gains. Deploying a policy therefore requires integrating its decisions with admission, failure recovery, and the existing orchestrator, then measuring its benefit under the fleet's actual workload.</p>\n<p>Consider applying adaptive allocation to our 175B-parameter model training run. The runtime must first expose viable resize configurations and their costs. A checkpoint-and-restart path can require persisting and restoring large optimizer state, while other state-transfer mechanisms impose different costs. Repeated resizing can consume the expected throughput gain before the job benefits from its new allocation. The policy should therefore compare predicted additional progress over the expected allocation duration with the measured transition cost, retaining a stable placement when resizing does not repay that cost. The decision follows the workload and cluster demand, not a universal training phase.</p>\n<p>The production decision is whether a specialized policy improves marginal allocation enough to justify its operational burden, judged by the measures this chapter has already built: queue delay and slowdown, useful GPU-hours, preemption overhead, and placement efficiency. Group admission settles whether a gang can start at all; the research schedulers answer the next question, which feasible group to admit, and each imposes different requirements on the runtime. Selecting a policy therefore means matching its objective and assumptions to the fleet rather than choosing a single scheduler as universally best.</p>\n<p>Consider the trade-offs between the four research schedulers:</p>\n<ul class=\"cs-list\">\n<li>[ ] <strong>Estimate-free scheduling</strong>: identify the information Tiresias sacrifices by eliminating runtime estimates, and describe when that sacrifice hurts scheduling quality.</li>\n<li>[ ] <strong>Time-slicing limits</strong>: identify workloads for which Gandiva's iteration-boundary time-slicing fails, and explain why.</li>\n<li>[ ] <strong>Job starvation</strong>: explain how waiting changes an application's finish-time fairness ratio in Themis, and why this differs from favoring jobs that are nearly complete.</li>\n<li>[ ] <strong>Goodput-model risk</strong>: describe the failure mode when Pollux's goodput model is wrong.</li>\n</ul>\n<p>The training policies just compared balance completion time, fairness, utilization, and learning progress. Serving adds a different deadline: capacity must be ready before an arriving request exhausts its latency budget. That requirement makes provisioning delay and burst headroom central to how the fleet allocates capacity to serving.</p>\n<h2 id=\"sec-41\" class=\"cs-h2\">Serving Capacity in the Shared Fleet</h2>\n<p>When an e-commerce platform launches a major sale, requests can arrive faster than its serving replicas can process them. A training job may tolerate waiting in the admission queue; a serving request misses its deadline while additional capacity is still starting. To the fleet orchestrator, serving is therefore a claim on accelerators that must be honored quickly and that competes with training gangs for the same devices.</p>\n<p>The orchestrator's unit is the serving replica, a ready execution group with a loaded model that may occupy one accelerator, a device partition, or a multi-accelerator gang. A 175B-parameter model may make an eight-GPU tensor-parallel group the schedulable replica. Archetype B (DLRM at Scale) imposes the same constraint through its embedding tables: a replica whose tables are sharded across several accelerators can serve only when every shard is placed. Each replica has a measured request-processing capacity at a specified workload mix and latency target, and that measured capacity is the quantity the orchestrator uses to size and place replicas. It decides how many such groups exist, where they reside, how they are protected from interference, and which lower-priority allocations yield when serving demand grows. Language models add a memory dimension to the claim. Each in-progress response retains per-token attention state, the key-value (KV) cache, whose footprint grows with context length and concurrency even though the weights stay fixed, so a replica can exhaust its memory before it exhausts its compute.</p>\n<p>How many replicas to run at each moment is a control problem with its own signals and delays. Accelerator utilization alone does not identify the capacity needed to meet a request-latency target, and loading large models can delay a new replica's readiness. The controller must combine demand signals with measured startup time and ready reserve capacity; @sec-inference-scale-autoscaling-capacity-control develops that control loop. For the orchestrator, the immediate consequence is that reclaiming a device from training does not instantly make it available for serving. Three fleet-level questions follow, namely how serving workloads share devices without unacceptable interference, when sharing pays for itself, and where the boundary between training and serving pools should sit.</p>\n<h3 id=\"sec-42\" class=\"cs-h3\">Resource isolation</h3>\n<p>When multiple inference workloads share physical hardware, noisy-neighbor contention arises whenever one workload's resource consumption degrades another's execution speed. On GPUs, shared execution units can limit concurrent kernels, while saturated HBM interfaces constrain memory-bound work. Contending working sets can evict lines from the shared L2 cache, and simultaneous host-to-device transfers can compete for PCIe bandwidth. Aggregate power and temperature limits can also reduce operating clocks. These mechanisms connect the placement decision to the request's critical path. A placement that fits every model in memory can still miss its service-level objective if sharing extends execution or queueing enough to exhaust the latency budget.</p>\n<p>: <strong>Noisy neighbor</strong>: In GPU clusters, interference arises when one job's bursty network traffic or memory bus utilization slows down a co-located job on the same node. In synchronous training, a delayed flow can extend collective completion when it lies on the communication critical path, propagating one tenant's interference across a worker group.</p>\n<p>Multi-Instance GPU (MIG) closes several of these channels in hardware by partitioning A100 (<code>[ClusterEconomicsMigRecap.a100_mem_gb_str]</code>) and H100 (<code>[ClusterEconomicsMigRecap.h100_mem_gb_str]</code>) GPUs into hardware-isolated instances. Unlike software-based GPU sharing, such as time-slicing that context-switches several processes over one whole device, MIG dedicates memory, cache, and compute resources to each instance, reducing interference through those partitioned resources. The A100 MIG profiles in @tbl-fleet-orchestration-mig-profiles show the scheduling consequence. A single physical A100 becomes several fixed-size resources that the device plugin of @sec-fleet-orchestration-kubernetes can expose as independently schedulable accelerators.</p>\n<p>: <strong>Multi-Instance GPU (MIG)</strong>: Introduced with the A100 (2020), MIG partitions a single GPU into up to 7 hardware-isolated instances with dedicated memory controllers, L2 cache slices, and compute units [@NVIDIA2020]. The isolation is enforced at the hardware level, not by time-slicing, reducing noisy-neighbor interference relative to software-only sharing. Changing the partition layout requires stopping affected GPU workloads; the scheduler must include that disruption when adapting profiles to a changing workload mix.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>MIG profile</strong></th><th><strong>GPU memory</strong></th><th><strong>SM count</strong></th><th><strong>Typical workload</strong></th></tr></thead><tbody>\n<tr><td><strong>1g.10gb</strong></td><td><code>[ClusterEconomicsMigRecap.mig_1g_mem_str]</code></td><td><code>[ClusterEconomicsMigRecap.mig_1g_sm_str]</code> SMs</td><td>Small inference</td></tr>\n<tr><td><strong>2g.20gb</strong></td><td><code>[ClusterEconomicsMigRecap.mig_2g_mem_str]</code></td><td><code>[ClusterEconomicsMigRecap.mig_2g_sm_str]</code> SMs</td><td>Medium inference</td></tr>\n<tr><td><strong>3g.40gb</strong></td><td><code>[ClusterEconomicsMigRecap.mig_3g_mem_str]</code></td><td><code>[ClusterEconomicsMigRecap.mig_3g_sm_str]</code> SMs</td><td>Large inference</td></tr>\n<tr><td><strong>7g.80gb</strong></td><td><code>[ClusterEconomicsMigRecap.mig_7g_mem_str]</code></td><td><code>[ClusterEconomicsMigRecap.mig_7g_sm_str]</code> SMs</td><td>Training</td></tr>\n</tbody></table></div>\n<p>: <strong>A100 MIG Profiles</strong>: Multi-Instance GPU configurations trade GPU memory and compute resources for increased sharing density. Each profile provides hardware-isolated resources, making MIG suitable for multi-tenant inference clusters where workloads from different teams or customers must not interfere. The streaming multiprocessor (SM) count determines compute throughput within each instance. {#tbl-fleet-orchestration-mig-profiles}</p>\n<p>MIG therefore sits at the strong resource-isolation end of this design space. The operational implication is that hardware partitioning reduces cross-workload interference but turns partition choice into a placement constraint. MIG is available on supported MIG-capable NVIDIA data-center GPUs, profiles may require draining affected workloads before reconfiguration, and fixed partition sizes may not match workload requirements. The memory-fit and sharing examples take each labeled device or profile capacity as a conservative admission budget of that many decimal gigabytes, so an instance admits a working set no larger than its label. A workload that needs <code>[MigPartitionFit.need_str]</code> of GPU memory leaves <code>[MigPartitionFit.waste_str]</code> of a <code>[MigPartitionFit.fit_str]</code> MIG instance budget unused or exceeds a <code>[MigPartitionFit.small_str]</code> instance budget.</p>\n<p>Software sharing offers different controls over execution, memory, and fault isolation; these do not form a single performance-versus-security scale. At the simplest level, <strong>CUDA time-slicing</strong> allows multiple processes to share a GPU by context-switching the compute resources. While flexible, it offers weak performance isolation because contexts compete for the entire device over time. NVIDIA's Multi-Process Service (MPS) allows kernels and memory copies from different processes to overlap, reducing context-switch overhead and improving utilization when one process cannot fill the device [@nvidiaCudaMps]. In the shared-resource MPS configuration considered here, Volta and newer clients have distinct GPU virtual address spaces but compete for execution and memory-system resources. Additional partitioning controls depend on the hardware, software version, and selected mode, and those configured limits, not address-space separation, determine how much performance and fault isolation MPS provides.</p>\n<p>GPU memory accounting must still prevent one model from consuming capacity reserved for another. A distinct virtual address space blocks direct addressing of another client's allocations, but it does not create a fixed memory-capacity partition. Without enforceable per-client limits, a memory leak or unexpectedly large batch can exhaust shared device memory and disrupt colocated workloads. MPS therefore fits mutually trusting workloads whose aggregate memory footprint and interference have been measured; MIG or full-device assignment fits stronger trust and predictability requirements. At the host level, CPU core pinning and NUMA-aware placement complement these device controls by keeping inference processes off contended cores and away from remote memory, which shortens tail latency whenever those host paths lie on the request's critical path.</p>\n<p>: <strong>CUDA MPS (Multi-Process Service)</strong>: The shared-resource mode used in this example does not reserve an independent hardware slice for each client, and a deployment must also account for the GPU fault domain its clients share [@nvidiaCudaMps].</p>\n<p>The GPU mechanisms form a spectrum from flexible software sharing (time-slicing and MPS) through hardware partitioning (MIG) to exclusive assignment, and each point gives up packing efficiency for isolation (@tbl-gpu-virtualization-isolation-spectrum). For serving, the choice turns on interference and memory accounting; when colocated workloads belong to different teams, it also becomes a trust-boundary decision, which @sec-fleet-orchestration-security-isolation takes up with the rest of multi-tenant security.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Option</strong></th><th><strong>Isolation strength</strong></th><th><strong>Efficiency and flexibility</strong></th><th><strong>Suitable workload or trust boundary</strong></th></tr></thead><tbody>\n<tr><td><strong>Time-slicing</strong></td><td>Separate contexts; shared performance and device fault domains.</td><td>Flexible; no spatial reservation.</td><td>Trusted, bursty jobs.</td></tr>\n<tr><td><strong>MPS</strong></td><td>Separate address spaces; shared performance and GPU fault domains.</td><td>Concurrent kernels; configurable limits.</td><td>Mutually trusting jobs with measured demand.</td></tr>\n<tr><td><strong>MIG</strong></td><td>Hardware-partitioned memory, cache, and compute.</td><td>Predictable; fixed profiles.</td><td>SLO-sensitive work; external tenants also need platform security controls.</td></tr>\n<tr><td><strong>Full device passthrough</strong></td><td>Exclusive access to the GPU.</td><td>Strongest device isolation; lowest packing efficiency.</td><td>Jobs that saturate the device or forbid sharing.</td></tr>\n</tbody></table></div>\n<p>: <strong>GPU Virtualization Isolation Spectrum</strong>: GPU sharing mechanisms trade device-resource isolation against packing efficiency. External tenant isolation additionally depends on the host, driver, identity, network, and storage security boundaries. {#tbl-gpu-virtualization-isolation-spectrum tbl-colwidths=\"[23,27,23,27]\"}</p>\n<h3 id=\"sec-43\" class=\"cs-h3\">GPU sharing economics</h3>\n<p>The decision to co-locate multiple models on a single GPU trades potential capacity savings against interference. Choosing <strong>exclusive access</strong> avoids competition from another device tenant but can leave capacity unused when one workload cannot fill the device. Production evidence suggests such stranded capacity is common. On NERSC's Perlmutter supercomputer, @li2023 found that <code>[IdleCostAnchors.perlmutter_jobs_str]</code> of jobs used less than <code>[IdleCostAnchors.perlmutter_mem_str]</code> of their allocated GPU memory. Moving to <strong>aggressive sharing</strong> (via MPS or time-slicing) can admit more work, provided contention does not erase the gain or violate latency objectives. Exclusive device assignment still depends on the surrounding host, driver, identity, network, and storage controls for tenant security. The scheduler must therefore evaluate memory fit and measured service capacity together.</p>\n<p>Using the same conservative admission budget, consider an A100 GPU with a <code>[GpuSharingDensity.a100_mem_gb_str]</code> memory budget serving a <code>[GpuSharingDensity.small_model_b_str]</code> parameter model. The model weights in FP16 consume approximately <code>[GpuSharingDensity.small_weights_gb_str]</code>. With the scenario's assumed KV cache and activation overhead, the total runtime footprint is roughly <code>[GpuSharingDensity.small_footprint_gb_str]</code>. Exclusive access leaves <code>[GpuSharingDensity.excl_dark_gb_str]</code> (<code>[GpuSharingDensity.excl_dark_pct_str]</code>) of the memory budget unused at this load. That budget is reclaimable only to the extent that it exceeds required runtime and burst headroom. A MIG partition (for example, a <code>3g.40gb</code> profile) leaves roughly <code>[GpuSharingDensity.mig_dark_pct_str]</code> of the assigned partition budget unused; the remaining device capacity is subject to valid partition combinations. Packing two such models onto the same <code>[GpuSharingDensity.a100_mem_gb_str]</code> device through MPS consumes <code>[GpuSharingDensity.shared_mem_gb_str]</code>, leaving <code>[GpuSharingDensity.shared_dark_pct_str]</code> of the device memory budget unused under the same footprint assumption. Reducing the device count also requires enough compute and bandwidth headroom to preserve throughput and latency under concurrent demand; fitting the models in memory is only the first admission condition.</p>\n<p>This density introduces interference. When two workloads share execution and memory resources through MPS, their demands can overlap on SMs and memory bandwidth. A compute-bound model paired with a memory-bound model is a candidate for complementary placement because, in isolation, each saturates a different resource, but the bottleneck labels describe isolated behavior, not a guarantee of compatibility. Both workloads still use multiple resources, and concurrent demand can change the limiting resource. The scheduler must measure the pair's throughput and tail latency across its expected load range before treating memory density as usable capacity.</p>\n<p>For a heterogeneous fleet, this logic dictates a bifurcated strategy. Our 175B parameter model requires about <code>[GpuSharingDensity.large_weights_gb_str]</code> for FP16 weights alone; with the <code>[GpuSharingDensity.a100_mem_gb_str]</code> per-device admission budget that means at least <code>[GpuSharingDensity.min_gpus_large_str]</code> GPUs before KV cache, activation buffers, runtime workspace, and tensor-parallel granularity are included. In practice, an 8-GPU tensor-parallel replica is the cleaner scheduling unit and is a candidate for exclusive access. Conversely, the dozens of 1B to 7B parameter support models, such as toxicity classifiers, query embedding encoders, and auxiliary generation models, are candidates for sharing. Packing these smaller models onto shared utility nodes frees the high-performance nodes for foundation-model replicas.</p>\n<p>Consider a fleet serving <code>[GpuSharingRoi.gs_n_small_str]</code> distinct <code>[GpuSharingRoi.gs_small_model_b_str]</code> models (<code>[GpuSharingRoi.gs_small_footprint_gb_str]</code> footprint each) and <code>[GpuSharingRoi.gs_n_large_str]</code> distinct <code>[GpuSharingRoi.gs_large_model_b_str]</code> models (<code>[GpuSharingRoi.gs_large_footprint_gb_str]</code> footprint each). Assume load testing has established that each proposed co-resident pair meets its throughput and tail-latency objectives with the required headroom and isolation. The memory-utilization percentages use the same conservative admission budgets. The example computes the resulting capacity reduction under the load-testing assumption; memory fit alone would not establish it.</p>\n<p><strong>Strategy A (exclusive access, one model per GPU)</strong>: The <code>[GpuSharingRoi.gs_small_model_b_str]</code> models require <code>[GpuSharingRoi.gs_n_small_str]</code> A100 GPUs (<code>[GpuSharingRoi.gs_a100_mem_gb_str]</code> each), achieving only <code>[GpuSharingRoi.gs_excl_util_str]</code> memory utilization (<code>[GpuSharingRoi.gs_n_small_str]</code> $\\times$ <code>[GpuSharingRoi.gs_small_footprint_gb_str]</code> used out of <code>[GpuSharingRoi.gs_excl_total_mem_gb_str]</code> total). The <code>[GpuSharingRoi.gs_large_model_b_str]</code> models require <code>[GpuSharingRoi.gs_excl_large_str]</code> (<code>[GpuSharingRoi.gs_n_large_str]</code> models $\\times$ <code>[GpuSharingRoi.gs_gpus_per_large_str]</code> each for tensor parallelism). Total fleet: <code>[GpuSharingRoi.gs_excl_total_str]</code>.</p>\n<p><strong>Strategy B (MPS for small models, exclusive for large)</strong>: Pack <code>[GpuSharingRoi.gs_models_per_gpu_str]</code> models per A100 for the <code>[GpuSharingRoi.gs_small_model_b_str]</code> models (<code>[GpuSharingRoi.gs_models_per_gpu_str]</code> $\\times$ <code>[GpuSharingRoi.gs_small_footprint_gb_str]</code> = <code>[GpuSharingRoi.gs_shared_mem_gb_str]</code>, well within <code>[GpuSharingRoi.gs_a100_mem_gb_str]</code>), requiring only <code>[GpuSharingRoi.gs_shared_gpus_str]</code> at <code>[GpuSharingRoi.gs_shared_util_str]</code> memory utilization. The <code>[GpuSharingRoi.gs_large_model_b_str]</code> models remain unchanged at <code>[GpuSharingRoi.gs_excl_large_str]</code>. Total fleet: <code>[GpuSharingRoi.gs_shared_total_str]</code>.</p>\n<p>Under the load-testing assumption, sharing reduces the required fleet size by <code>[GpuSharingRoi.gs_saved_pct_str]</code> (<code>[GpuSharingRoi.gs_saved_gpus_str]</code> fewer GPUs). At <code>[GpuSharingRoi.gs_gpu_hour_rate_str]</code>, the released capacity is worth approximately <code>[GpuSharingRoi.gs_annual_usd_str]</code> annually at the scenario rate. It becomes a cash saving when the organization releases billed resources or avoids purchasing that capacity.</p>\n<h3 id=\"sec-44\" class=\"cs-h3\">The training-serving resource boundary</h3>\n<p>Separate training and serving pools simplify capacity ownership but can leave useful work queued beside idle devices. Consider a serving pool reserved for peak traffic while a training pool remains backlogged. This <strong>static partitioning</strong> protects serving capacity from training demand, but unused serving resources cannot help the training queue. <strong>Dynamic sharing</strong> allows that borrowing only when the orchestrator can return ready serving capacity before it is needed. The mode-switching cost determines how much capacity can safely move between the pools.</p>\n<p>Repurposing a GPU from training to serving can require saving training state, releasing the old allocation, launching the inference runtime, loading weights, and warming the replica. The orchestrator must measure the complete path to readiness, including any overlap between these operations. If that path takes minutes, reclaiming training capacity cannot cover a burst that exhausts the serving reserve in seconds. Forecasts can schedule transfers ahead of predictable demand, while already-ready headroom covers shorter bursts; the required reserve depends on forecast error and measured reclaim time.</p>\n<p>Consider a daily traffic pattern with low demand at 3 AM, growth at 8 AM, a peak at 2 PM, and a decline at 10 PM. A forecast with a 30-minute lead allows the orchestrator to begin reclaiming training allocations at 7:30 AM, provided measured replica startup fits within that lead time. As traffic falls, it drains surplus replicas before returning their devices to training. Pricing that policy against a static split needs three quantities: what serving reserves, what it uses on average, and how much of the difference training can absorb without eroding the surge buffer. The accompanying diurnal-shift calculation assumes its surge buffer suffices; a production policy must size the buffer against its own burst distribution and forecast errors.</p>\n<p>Consider a fleet of <code>[DiurnalGpuShift.ds_fleet_gpus_str]</code> managed under two regimes:</p>\n<p><strong>Scenario A (static partitioning)</strong>: The serving pool reserves <code>[DiurnalGpuShift.ds_serving_peak_str]</code>. That reservation is the forecast peak of <code>[DiurnalGpuShift.ds_peak_demand_str]</code> plus a <code>[DiurnalGpuShift.ds_safety_buffer_str]</code>-GPU surge buffer that absorbs forecast error and bursts shorter than a replica's startup time. Average usage is only <code>[DiurnalGpuShift.ds_serving_avg_str]</code> (<code>[DiurnalGpuShift.ds_serving_peak_util_str]</code> utilization). The training pool takes the rest of the fleet after the serving reservation and <code>[DiurnalGpuShift.ds_unallocated_str]</code> held back as maintenance headroom, which leaves <code>[DiurnalGpuShift.ds_training_fixed_str]</code>, and its backlog keeps them at <code>[DiurnalGpuShift.ds_training_full_util_str]</code> utilization. Result: <code>[DiurnalGpuShift.ds_serving_avg_str]</code> + <code>[DiurnalGpuShift.ds_training_fixed_str]</code> = <code>[DiurnalGpuShift.ds_static_active_str]</code> active GPUs. Fleet utilization: <code>[DiurnalGpuShift.ds_static_util_str]</code>. The maintenance headroom stays unallocated in both scenarios.</p>\n<p><strong>Scenario B (dynamic sharing)</strong>: Serving holds forecast demand (average <code>[DiurnalGpuShift.ds_serving_avg_str]</code>) plus the same <code>[DiurnalGpuShift.ds_safety_buffer_str]</code>-GPU surge buffer. Training reclaims the rest of the serving reservation, which is the unused <code>[DiurnalGpuShift.ds_serving_reclaimable_str]</code> on average minus the buffer and averages <code>[DiurnalGpuShift.ds_reclaimed_str]</code> over the course of the day (the medium-blue band in @fig-fleet-orchestration-training-serving-diurnal). Because each role switch costs minutes, the orchestrator moves this capacity on the forecast rather than chasing individual traffic spikes. Result: serving (<code>[DiurnalGpuShift.ds_serving_avg_str]</code>) + training (<code>[DiurnalGpuShift.ds_training_fixed_str]</code> + <code>[DiurnalGpuShift.ds_reclaimed_str]</code>) = <code>[DiurnalGpuShift.ds_dynamic_active_str]</code> active GPUs (the second training term is reclaimed serving capacity). Fleet utilization: <code>[DiurnalGpuShift.ds_dynamic_util_str]</code>.</p>\n<p>Dynamic sharing recovers <code>[DiurnalGpuShift.ds_reclaimed_str]</code> of effective capacity. At <code>[DiurnalGpuShift.ds_gpu_hour_rate_str]</code>, this recovered capacity creates approximately <code>[DiurnalGpuShift.ds_annual_usd_str]</code> per year in value without purchasing a single additional accelerator.</p>\n<p>Moving capacity between pools on that diurnal schedule requires both a measured interference budget and an enforceable right to reclaim capacity. Isolation mechanisms address the first requirement; they do not decide which team owns a device or when a borrower must release it. That second requirement is an allocation contract across teams, and it applies to every pool the orchestrator manages, serving and training alike.</p>\n<h2 id=\"sec-45\" class=\"cs-h2\">Multi-Tenancy and Quotas</h2>\n<p>When the computer vision team hoards 500 GPUs for a week while the natural language processing team sits blocked trying to push a critical bug fix to production, shared clusters devolve into a tragedy of the commons. Teams with the most aggressive job submission rates, the largest jobs, or the most persistent resubmission scripts consume disproportionate resources, while teams with more modest or intermittent needs find the cluster perpetually occupied. The result is organizational friction and underinvestment in slower-moving but potentially higher-value projects whose teams cannot compete for capacity on submission volume alone. A static serving reservation faces the same pressure from the other direction, since a training team that sees idle serving devices will want them.</p>\n<p>Multi-tenancy and quotas turn organizational priorities into rules for resource allocation, borrowing, and reclamation that the scheduler can enforce. A quota defines an entitlement or a limit. Whether that entitlement becomes prompt, productive access depends on borrowing that lends idle guarantees to other teams and on reclamation that returns them within a bounded time, both developed below. Accounting that separates the capacity a team holds from the capacity it uses well belongs with utilization debugging in @sec-fleet-orchestration-resource-accounting.</p>\n<h3 id=\"sec-46\" class=\"cs-h3\">Hierarchical fair-share</h3>\n<p>Assigning fixed GPU quotas at the namespace or project level (for example, 500 GPUs to Team A, 300 to Team B, and 200 to Team C) gives each team a clear entitlement, but leads to systematic underutilization whenever workloads fluctuate. If Team A's 500-GPU allocation sits 50 percent idle during a quiet period while Team B's queue overflows with urgent work, rigid quotas leave 250 GPUs wasted that Team B is forbidden to use. Allocating smaller static quotas to each team creates the opposite failure: teams are blocked from running legitimate work during peak periods even when the cluster has spare capacity overall.</p>\n<p>Hierarchical quotas, which Slurm expresses through its account hierarchy and fair-share accounting (@eq-fleet-orchestration-fair-share) and Kueue through ClusterQueues grouped into borrowing cohorts, separate a team's guaranteed share from its maximum permitted allocation. In @eq-fleet-orchestration-quota, $\\TeamQuotaCap$ denotes a team's maximum burst cap rather than its guarantee, $\\DepartmentQuotaLimit$ is the department's total capacity limit, and $\\SiblingTeamAllocation$ is each sibling team's current active allocation. Assuming those allocations remain within the department limit, the smaller of the team's burst cap and the department's currently unallocated capacity sets the team's admission ceiling before any reclamation:</p>\n<p>$$ \\EffectiveAdmissionCeiling= \\min\\left(\\TeamQuotaCap,\\ \\DepartmentQuotaLimit- \\sum_{\\text{other teams}} \\SiblingTeamAllocation\\right) $$ {#eq-fleet-orchestration-quota}</p>\n<p>The second term inside the minimum is what lends idle guarantees across sibling teams. If Team A uses only <code>[QuotaLending.used_pct_str]</code> of its <code>[QuotaLending.guarantee_str]</code>-GPU guarantee, its active allocation $\\SiblingTeamAllocation$ drops below its guarantee and leaves the remaining <code>[QuotaLending.lendable_str]</code> GPUs in $\\DepartmentQuotaLimit - \\sum_{\\text{other teams}} \\SiblingTeamAllocation$ for sibling teams to claim, up to each borrower's own cap $\\TeamQuotaCap$. This ceiling bounds what a team may hold at admission, and it encodes neither fair-share weights nor guarantees. When several teams contend for that spare capacity at once, the scheduler still applies its fairness policy, the dominant-resource calculation of @sec-fleet-orchestration-drf-worked-allocation, to the feasible gangs that fit under each ceiling.</p>\n<h3 id=\"sec-47\" class=\"cs-h3\">Burst capacity and quota borrowing</h3>\n<p>Lending turns unused guarantees into burst capacity. Suppose a small team holds a guarantee of 64 GPUs but needs 256 for a weekend-long training run while a sibling team's guaranteed share sits idle. The small team may borrow idle whole devices up to its maximum quota. Those devices remain part of physical cluster capacity rather than becoming virtual capacity, and they carry lower preemption priority than owned resources. When the sibling team submits work that needs its guarantee, the scheduler reclaims the borrowed devices by preempting or shrinking the borrower's opportunistic jobs.</p>\n<p>Borrowing resolves that static-quota dilemma only when the lent capacity remains reclaimable within the platform's response-time objective, safety headroom, and current physical capacity. A team entitled to 500 GPUs can reclaim borrowed devices according to that contract, but the scheduler must not promise an immediate 500-GPU allocation when failures, nonpreemptible reservations, or recovery headroom reduce reclaimable capacity.</p>\n<p>Burst capacity therefore raises the maximum a team may hold, while its guarantee stays fixed. The 64-GPU team from the weekend-run example may hold up to 256 GPUs, but the platform promises only its 64-GPU guarantee concurrently with every other team's. The sum of guarantees that the platform promises to honor concurrently must fit reclaimable physical capacity after nonpreemptible reservations and safety headroom. Teams may advertise higher maximums or fair-share weights, the target shares that set priority in @eq-fleet-orchestration-fair-share, because borrowed jobs yield when guaranteed demand returns, but those values are not guarantees.</p>\n<p>Reclamation couples quota policy to the checkpoint infrastructure. The admission controller separates guaranteed jobs from opportunistic jobs. Guaranteed jobs run on the team's owned quota and face preemption only from higher-priority work. Opportunistic jobs run on borrowed capacity, yield first, and must checkpoint often enough that reclamation wastes little work, since every forced reclaim pays the preemption overhead of @sec-fleet-orchestration-preemption-cascades. Elastic jobs soften reclamation further through the graceful preemption of @sec-fleet-orchestration-elastic-scheduler-integration, shrinking one replica at a time toward their minimum viable allocation rather than terminating.</p>\n<p>One policy for quota borrowing uses four tiers. Production serving (Priority 0) holds capacity protected from routine preemption. Production training (Priority 1) yields only under a defined serving-failover policy. Interactive and debug sessions (Priority 2) receive short execution limits to preserve iteration speed without indefinite resource occupation. Batch and research tasks (Priority 3) use surplus capacity and yield under their reclamation contract. These numbers label this example's tiers; they are not Kubernetes priority values, where larger integers indicate higher priority. The hierarchy establishes precedence, but deadline protection still requires feasible capacity and bounded reclamation time, while lower-priority work needs an explicit starvation policy.</p>\n<p>As the over-subscription discussion in @sec-fleet-orchestration-bin-packing showed, a partly idle device is still a whole allocated device, so the safe burst limit follows from reclaimability rather than average SM utilization. Fractional sharing is a separate mechanism that requires an explicit MIG, MPS, or time-slicing contract. The scheduler must measure how quickly borrowed jobs can checkpoint, shrink, or terminate, and it must reserve the I/O and network bandwidth required for that transition. Only then can it bound the amount of opportunistic capacity that is safe to lend while still honoring the guarantee's response-time objective. Until reclamation completes, a borrowed job that still runs beside the owner's returning work is a noisy neighbor on the shared network and storage paths (@sec-fleet-orchestration-resource-isolation). Isolation and the reclaim deadline must together bound how much the borrower can slow the owner.</p>\n<h3 id=\"sec-48\" class=\"cs-h3\">Security and namespace isolation</h3>\n<p>Teams that share a fleet must also be kept from observing or altering one another's model weights, training data, and inference traffic. A namespace provides only an administrative boundary that host, device, network, and storage controls must enforce. Network policy must cover the collective paths an admitted gang actually uses, and host networking moves the enforcement point off the pod network, so each path needs its own verification.</p>\n<p>↩ Fabric-level isolation, through virtual lanes and traffic classes that keep one job's bursts from stretching another job's collectives, is established in @sec-network-fabrics-qos.</p>\n<p>Across teams, the isolation spectrum of @tbl-gpu-virtualization-isolation-spectrum becomes a trust-boundary choice, because colocated workloads now belong to owners with different exposure to one another. Side-channel attacks on shared GPUs are a documented vulnerability; by monitoring contention on shared caches or memory controllers, a malicious tenant can infer the architecture or even data properties of a co-resident model. In sensitive environments, MIG or dedicated devices can strengthen device-resource isolation, but neither creates a complete external-tenant security boundary by itself. A multi-tenant platform combines device partitioning with VM or container isolation, configuration of the input-output memory management unit (IOMMU) that limits which host memory a device can reach, driver and runtime hardening, authentication and authorization, and network and storage controls. Single-organization workloads with a narrower trust boundary can use MPS or time-slicing when weaker fault and performance isolation is acceptable.</p>\n<p>↪ The attack surface of shared accelerators, and which sharing mechanisms leave co-resident tenants observable to one another, is developed in @sec-security-privacy-shared-accelerators.</p>\n<h3 id=\"sec-49\" class=\"cs-h3\">Quota governance and organizational dynamics</h3>\n<p>Even when a scheduler enforces quotas accurately, a guarantee set six months ago can leave 60 percent of a team's reserved GPUs underused after its flagship model ships while another team's urgent launch queue backs up. While the scheduler manages immediate resource assignments, <strong>quota governance</strong> revises the entitlements and limits those assignments must honor. Periodic <strong>quota review cycles</strong> compare observed use, forecast demand, and the cost of meeting each team's capacity promise. A team using only 40 percent of a 128-GPU guarantee does not necessarily block other teams if unused devices can be borrowed. The governance question is whether the guarantee remains justified and whether its reclamation contract lets the fleet use spare capacity productively between demand peaks.</p>\n<p>The central tension in quota management is the <strong>hoarding problem</strong>, in which teams retain idle reservations to avoid queuing again when work becomes ready. A workflow that pauses policy training while awaiting human annotations or a training run delayed by unfinished tokenization can leave its reserved accelerators unused, reflecting dependencies in particular workflows rather than an unavoidable idle phase of all training. Utilization-based reclamation can release idle physical allocations to borrowers, provided the platform preserves any promised return time; revising the team's longer-term guarantee instead requires comparing expected demand with observed use. Clear return contracts reduce the incentive to hold idle devices without making low activity alone grounds for breaking a capacity promise.</p>\n<p>Quota accounting should remain close to the scheduling decision. Every admitted job needs an owner, project, workload class, and preemption contract so the scheduler can apply quota and recovery policy consistently, and Kubernetes labels and Slurm accounts carry this scheduling identity. GPU-hours charged against a reservation, borrowed share, or preemption class then make the opportunity cost of hoarding visible and let the control plane reclaim idle guarantees.</p>\n<p><strong>Scenario</strong>: A research team reserves a static block of <code>[QuotaHoardingCost.hoarding_gpus_str]</code> GPUs for an upcoming model refresh.</p>\n<p><strong>Diagnosis</strong>: Upstream data delays postpone training, but the team retains the reservation to ensure future availability. The GPUs sit idle for <code>[QuotaHoardingCost.hoarding_weeks_str]</code>, leaving <code>[QuotaHoardingCost.hoarding_cost_str]</code> of capacity value unused while other teams' queues back up.</p>\n<p><strong>Systems lesson</strong>: An idle reservation should trigger a review of lending eligibility and future demand. The orchestrator can admit opportunistic borrowers under a bounded reclamation contract without changing the owner's guarantee. Reducing that guarantee is a separate governance decision; lending owned capacity does not turn it into cloud spot capacity.</p>\n<p>A \"use it or lose it\" reclamation policy addresses the most visible symptom of quota hoarding. Lending idle capacity to another team, however, requires the system to distinguish borrowed capacity that is preemptible on short notice from guaranteed reservations protected by SLOs. Defining borrowing, preemption, and guaranteed tiers as first-class policy primitives is the core multi-tenancy design decision.</p>\n<p>Consider a 2,000-GPU cluster shared between a research team (60 percent allocation) and a production team (40 percent allocation):</p>\n<ul class=\"cs-list\">\n<li>[ ] <strong>Idle reclamation</strong>: decide whether the production team can borrow the research team's allocation while half of it sits idle, and describe the preemption behavior when the research team submits a large job.</li>\n<li>[ ] <strong>Priority classes</strong>: configure priority classes for a production inference workload that needs 100 GPUs with guaranteed latency SLOs and a research training job that can tolerate preemption.</li>\n<li>[ ] <strong>Sharing contract</strong>: explain why 65 percent average SM utilization does not justify whole-device overcommitment, then identify which measured resource and isolation constraints would make statistical multiplexing safe.</li>\n</ul>\n<p>Together, isolation boundaries, lending rules, and periodic quota reviews align organizational entitlements with physical capacity. Even a well-governed quota hierarchy, however, can leave a fleet reporting low aggregate utilization beside a backlogged queue whenever top-level metrics hide which constraint is actually blocking pending work.</p>\n<h2 id=\"sec-50\" class=\"cs-h2\">Debugging Cluster Utilization</h2>\n<p>A cluster dashboard shows average GPU utilization stuck at 60 percent, yet developers complain about three-day queue times for small debugging jobs. Hundreds of GPUs sit idle, but no jobs are starting. Explaining the gap requires tracing the interactions among hardware topology, scheduler policies, and user behavior.</p>\n<p>Part of the paradox is the queueing arithmetic of notebook \\ref{nbk-fleet-orchestration-queuing-theory-gpu-clusters}. The $\\ServingUtilization/(1-\\ServingUtilization)$ factor grows without bound as offered load approaches service capacity, so mean wait rises gently through moderate load and then steeply above 80 percent for small, mixed, and large workloads alike (@fig-utilization-paradox, plotted on a logarithmic scale). The three curves differ only in mean job duration, as their labels show, and all use the notebook's exponential reference case ($\\ServiceTimeVariationCoefficient= 1$), so they are the gentlest version of the effect. A mixed ML queue with the notebook's representative $\\ServiceTimeVariationCoefficient= 3$ multiplies every curve by the larger variability factor, shifting each one upward without changing where it bends. The curves also describe offered service load rather than allocated or kernel-active GPU percentages, and their 75 percent headroom marker is an illustrative choice rather than a universal cluster threshold. Queueing explains why a busy fleet waits. A fleet whose queue is full while devices sit idle is waiting for a different reason, and finding it requires looking past the dashboard.</p>\n<h3 id=\"sec-51\" class=\"cs-h3\">Allocated, active, and productive utilization</h3>\n<p>The 64 GPUs that sat idle for a weekend because a researcher forgot to cancel a reservation represent invisible waste in a multi-tenant cloud fleet. In a dedicated cluster, such waste is at least visible to the team that owns the hardware. In a shared environment, the cost is hidden and compounds across thousands of jobs. Effective governance requires moving beyond a single utilization number to a tiered accounting model that distinguishes between what was allocated, what was used, and what was useful.</p>\n<p>Three tiers of measurement expose this gap between allocated hardware and actual progress. Allocated capacity counts resources held by complete allocations, so devices assigned to a gang that still waits for its remaining members do not count. A partial gang can run no step, so those held devices are a scheduling loss below the allocated tier rather than allocated capacity. Active utilization measures hardware activity under a stated counter definition, which can include communication kernels or work later replayed. Productive utilization requires a workload-level measure of retained training progress or serving work that meets its objective, normalized to the job's own fault-free step rate. For example, a team allocated <code>[UtilizationTiersExample.allocated_str]</code> might average <code>[UtilizationTiersExample.active_str]</code> active-device equivalents (<code>[UtilizationTiersExample.active_pct_str]</code> activity) while delivering <code>[UtilizationTiersExample.productive_str]</code> device-equivalents of useful work at its fault-free rate (<code>[UtilizationTiersExample.productive_pct_str]</code> of its allocation). These are time-averaged equivalents, not necessarily distinct sets of active and productive devices. The gap motivates profiling; it does not identify its cause or imply that necessary communication and recovery can all be eliminated. The allocated and productive tiers also serve as the boundaries of two goodput factors that @sec-performance-engineering-goodput-boundaries measures. Scheduling goodput is the share of offered capacity held by complete allocations, and runtime goodput is the share of allocated time that becomes retained progress.</p>\n<p>This data feeds the utilization dashboard, the cluster operator's primary instrument for fleet health. This view must synthesize per-team utilization against quotas, queue depth by priority class, and the <strong>fragmentation index</strong>, a measure of free GPUs that cannot be allocated due to topology constraints. It must also track preemption rates, spot interruptions, checkpoint traffic, and the recovery overhead they induce. These measurements let the scheduler distinguish idle capacity it can reclaim from allocated capacity whose apparent idleness reflects communication, I/O, or a rigid gang dependency.</p>\n<p>Automated anomaly detection turns these metrics into investigation triggers. A sudden spike in a team's consumption to 3$\\times$ its historical norm might reflect a runaway submission script or an intentional experiment. A growing queue can indicate insufficient capacity, but it can also reflect quota limits, fragmented placements, or a stalled dependency. A sudden power drop can accompany a shared storage stall, though job completions and changes in workload mix can produce a similar signal. Operators must correlate these alerts with admission decisions and job progress before changing capacity or policy.</p>\n<p>Each tier narrows the investigation. Low allocated utilization calls for checking demand, quotas, device health, and placement feasibility. Low active utilization on allocated devices calls for tracing input supply, communication waits, and runtime execution. Low productive utilization despite busy kernels calls for comparing retained progress with replay, synchronization, and other overhead. The metric selects the next evidence to collect; it does not by itself select the remedy.</p>\n<h3 id=\"sec-52\" class=\"cs-h3\">Policy-infrastructure mismatch</h3>\n<p>When a cluster adds a new generation of high-memory GPUs alongside older pools, job templates written for the newest hardware can leave the older pools sitting idle while dozens of jobs queue behind the newest partition. Diagnosing this <strong>policy-infrastructure mismatch</strong> requires comparing scheduler state with physical capability and inspecting job requests against each hardware pool. A full queue and idle accelerators can coexist when the scheduler is honoring constraints that the top-level dashboard has aggregated away. The cluster at the center of example \\ref{exmp-fleet-orchestration-debugging-low-gpu-utilization} runs the heterogeneous hardware in @tbl-fleet-orchestration-debug-inventory, accumulated across three procurement cycles.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>GPU type</strong></th><th><strong>Count</strong></th><th><strong>Memory</strong></th><th><strong>Interconnect</strong></th><th><strong>Nodes</strong></th></tr></thead><tbody>\n<tr><td><strong>A100-80 GB</strong></td><td><code>[DebugValueCalc.a100_80_count_str]</code></td><td><code>[DebugValueCalc.a100_80_memory_str]</code> HBM2e</td><td>NVLink (<code>[DebugValueCalc.nvlink_a100_gb_per_s_str]</code>)</td><td><code>[DebugValueCalc.a100_80_nodes_str]</code> $\\times$ <code>[DebugValueCalc.a100_gpus_per_node_str]</code></td></tr>\n<tr><td><strong>A100-40 GB</strong></td><td><code>[DebugValueCalc.a100_40_count_str]</code></td><td><code>[DebugValueCalc.a100_40_memory_str]</code> HBM2e</td><td>NVLink (<code>[DebugValueCalc.nvlink_a100_gb_per_s_str]</code>)</td><td><code>[DebugValueCalc.a100_40_nodes_str]</code> $\\times$ <code>[DebugValueCalc.a100_gpus_per_node_str]</code></td></tr>\n<tr><td><strong>V100-32 GB</strong></td><td><code>[DebugValueCalc.v100_count_str]</code></td><td><code>[DebugValueCalc.v100_memory_str]</code> HBM2</td><td>PCIe Gen3 (<code>[DebugValueCalc.pcie_v100_gb_per_s_str]</code>)</td><td><code>[DebugValueCalc.v100_nodes_str]</code> $\\times$ <code>[DebugValueCalc.v100_gpus_per_node_str]</code></td></tr>\n</tbody></table></div>\n<p>: <strong>Cluster Hardware Inventory</strong>: Three procurement generations create distinct resource pools with different capabilities. In this inventory, A100 nodes have NVLink and the V100 pool uses PCIe. That difference changes tensor-parallel communication cost; it does not make tensor parallelism impossible on V100 devices. {#tbl-fleet-orchestration-debug-inventory}</p>\n<p><strong>Scenario</strong>: A <code>[DebugValueCalc.debug_cluster_comma_str]</code>-GPU cluster reports <code>[DebugValueCalc.debug_util_before_pct_str]</code> average utilization despite over <code>[DebugValueCalc.pending_jobs_str]</code> pending jobs in queue.</p>\n<p><strong>Diagnosis</strong>: Over-specification (users copying A100-80 GB templates for <code>[DebugValueCalc.large_job_peak_memory_str]</code> memory jobs), pool fragmentation, and legacy V100 avoidance leave A100-40 GB and V100 nodes idle while large jobs wait for A100-80 GB allocations. The scheduler correctly enforced policies written for a homogeneous fleet that no longer matched the heterogeneous infrastructure.</p>\n<p><strong>Systems lesson</strong>: Surface-level diagnosis often mistakes policy-infrastructure mismatches for scheduling algorithm bugs. Updating scheduler policies to support automatic capability matching, dynamic memory profiling, and backfilling raises cluster utilization to <code>[DebugValueCalc.debug_util_after_pct_prose_str]</code>, recovering <code>[DebugValueCalc.debug_annual_usd_str]</code> in annual compute capacity. @Tbl-fleet-orchestration-debug-results breaks that gain out pool by pool, using the allocated and active tiers of @sec-fleet-orchestration-resource-accounting.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Pool</strong></th><th><strong>Before</strong></th><th><strong>After</strong></th><th><strong>Change</strong></th></tr></thead><tbody>\n<tr><td><strong>A100-80 GB</strong></td><td><code>[DebugValueCalc.a100_80_alloc_before_str]</code> allocated, <code>[DebugValueCalc.a100_80_eff_before_str]</code> active</td><td><code>[DebugValueCalc.a100_80_alloc_after_str]</code> allocated, <code>[DebugValueCalc.a100_80_eff_after_str]</code> active</td><td>+<code>[DebugValueCalc.a100_80_eff_change_pp_str]</code></td></tr>\n<tr><td><strong>A100-40 GB</strong></td><td><code>[DebugValueCalc.a100_40_alloc_before_str]</code> allocated</td><td><code>[DebugValueCalc.a100_40_alloc_after_str]</code> allocated</td><td>+<code>[DebugValueCalc.a100_40_alloc_change_pp_str]</code></td></tr>\n<tr><td><strong>V100</strong></td><td><code>[DebugValueCalc.v100_alloc_before_str]</code> allocated</td><td><code>[DebugValueCalc.v100_alloc_after_str]</code> allocated</td><td>+<code>[DebugValueCalc.v100_alloc_change_pp_str]</code></td></tr>\n<tr><td><strong>Cluster-wide</strong></td><td><strong><code>[DebugValueCalc.debug_util_before_pct_tbl_str]</code></strong></td><td><strong><code>[DebugValueCalc.debug_util_after_pct_str]</code></strong></td><td><strong>+<code>[DebugValueCalc.cluster_change_pp_str]</code></strong></td></tr>\n</tbody></table></div>\n<p>: <strong>Utilization Recovery Results</strong>: Before the fix, A100-80 GB GPUs were almost fully allocated but less than fully active, while strict job templates stranded the other pools. Pool rows report allocated utilization, and for the A100-80 GB pool also the active share of its allocated GPUs; the A100-80 GB change is in that active share, the others in allocation. The cluster-wide row is the fleet's separately observed average utilization, so the pool rows are diagnostic signals that locate the loss rather than terms that add up to the total. {#tbl-fleet-orchestration-debug-results}</p>\n<p>For this capacity valuation, assume that each active GPU-hour delivers the same retained useful work before and after the policy change, including across hardware pools. Under that simplifying assumption, the observed utilization gain is equivalent to approximately <code>[DebugValueCalc.debug_productive_gain_str]</code> fully active GPUs of productive work (@tbl-fleet-orchestration-debug-results). A heterogeneous production fleet must validate that conversion against workload progress and measured throughput in each pool. As at the start of the chapter, procurement planning compares the gain with the hardware it replaces, here <code>[DebugValueCalc.debug_recovered_str]</code> additional raw GPUs, because new devices under the old policies would also run at only <code>[DebugValueCalc.debug_util_before_pct_str]</code> utilization. At <code>[DebugValueCalc.debug_gpu_hour_rate_str]</code>, that avoided purchase represents approximately <code>[DebugValueCalc.debug_annual_usd_str]</code> in annual recovered value, achieved through policy changes requiring zero additional hardware investment.</p>\n<h3 id=\"sec-53\" class=\"cs-h3\">Common utilization anti-patterns</h3>\n<p>Fixing policy-infrastructure mismatches gets queued jobs onto GPUs, but a dashboard reporting 85 percent allocation still says only how much capacity is assigned, not whether those allocations deliver productive work. Inside allocated capacity, four runtime patterns commonly widen the gap between the allocated, active, and productive tiers, and separating them requires correlating device telemetry with execution timelines.</p>\n<p>A zombie job retains an allocation after its useful execution has stopped, so its devices stay in the allocated tier while contributing nothing to the productive one, and they may or may not register as active. In a distributed run training a 175B parameter model, a rank failure can leave a 128-GPU group idle if worker cleanup or failure propagation does not complete. The surviving ranks may block inside a collective that will never finish, or a process left behind by a driver-level fault may resist reaping by the container runtime, so the devices stay allocated until a timeout or node-level remediation clears them. Persistent memory allocation combined with low SM activity is an investigation signal, not proof of a driver fault; valid input or communication waits can look similar. The operator must compare runtime health, step progress, and the workload's timeout contract, then verify that old workers have stopped before releasing or reassigning their devices.</p>\n<p>The data starvation pattern lowers the active tier. It manifests as a high-frequency sawtooth wave in GPU utilization, where the device oscillates between 100 percent load (forward/backward pass) and 0 percent load (waiting for the next batch). While the average utilization might appear acceptable at 60 to 70 percent, the GPU is effectively idling for a third of its life. This idling occurs when the CPU-bound data pipeline cannot sustain the throughput required by the GPU, a common scenario in computer vision where JPEG decoding and augmentation saturate host CPUs. The data stall ratio of @eq-data-stall quantifies the loss as the fraction of each step spent waiting for input. A timeline that aligns the idle intervals with input waits supports the diagnosis; utilization variance alone does not identify the cause. The remedy depends on whether decoding, storage, or transfer limits the input path.</p>\n<p>A communication bottleneck can leave ranks waiting for collectives, which lowers the active tier, though communication kernels can also keep SM activity high and mask the wait in that tier. Per-rank gradient traffic depends on gradient precision, sharding, and the parallelism layout, so the ratio of step time to compute-only time (forward plus backward passes in isolation) is a quicker first bound on exposed overhead. If total iteration time exceeds 1.5$\\times$ compute-only time, non-compute overhead exceeds 0.5$\\times$ compute time, which is material but not dominant. Setting $\\SynchronizationTime(\\DeviceCount)$ and $\\OverlappedTime$ to zero in the Fleet Law (@eq-fleet-law) leaves $\\DistributedStepTime(\\DeviceCount) = \\IronLawComputeTime/\\DeviceCount+ \\CommunicationTime(\\DeviceCount)$, under which communication exceeds per-device computation only when the ratio is greater than 2$\\times$. Real steps also contain synchronization waits and input stalls, so profiling must separate communication from those before the ratio is read as a communication diagnosis. Placement can reduce exposed communication when it improves the relevant paths. Gradient accumulation can reduce synchronization frequency only when the runtime defers gradient exchange across accumulation steps.</p>\n<p>On the serving side, memory fragmentation can prevent a replica from admitting new requests even when its HBM occupancy suggests free capacity, which lowers the productive tier without necessarily showing in the active one. Its signal is a replica that holds fewer concurrent requests than its occupancy predicts. The KV-cache allocator, rather than the aggregate occupancy percentage, decides whether a new sequence fits in contiguous or paged memory blocks. For the fleet scheduler, the allocator matters through its result, the number of concurrent requests a replica can hold, because that measured capacity sets how many replicas the serving envelope needs.</p>\n<p>↪ Paged KV-cache allocation and its effect on replica concurrency are developed in @sec-inference-scale-pagedattention-3c94.</p>\n<p>The debugging example connects scheduling mechanics to fleet governance. Technical policies (GPU type matching, gang scheduling timeouts, preemption grace periods) interact with organizational policies (team quotas, priority hierarchies, cost allocation) and human behavior (job template reuse, resource request habits, queue submission patterns). Effective fleet orchestration requires attending to all three layers simultaneously, because the most expensive scheduling bug is often not a software defect but a policy that was correct for the old infrastructure and was never updated for the new one.</p>\n<h2 id=\"sec-54\" class=\"cs-h2\">Fallacies and Pitfalls</h2>\n<p>Those policy-infrastructure mismatches recur as a small set of misconceptions that can make an apparently healthy scheduler waste expensive fleet capacity. A cluster running at 98 percent utilization can look healthy while researchers have stopped submitting jobs because wait times have stretched into weeks. Each misconception below follows the same pattern, in which optimizing one visible metric degrades the outcome the fleet exists to deliver.</p>\n<p><strong>Fallacy</strong>: <em>More sophisticated scheduling algorithms always improve utilization.</em></p>\n<p>Engineers facing low utilization often reach for more advanced schedulers, assuming the algorithm is the bottleneck. As the debugging example in @sec-fleet-orchestration-debugging demonstrates, the root cause is frequently policy misconfiguration, not algorithmic limitation. A simple FIFO scheduler with correct policies (capability-based matching, backfill with timeouts, appropriate gang scheduling constraints) often outperforms a sophisticated scheduler with incorrect policies. Before upgrading the scheduler, audit the policies: confirm that users are not requesting resources they do not need, that heterogeneous resources are properly exposed, and that gang-scheduling timeouts are configured. The audit recurs as workloads evolve, because a preemption grace period that suffices for one model can be too short for another to save state, and placement weights suited to an earlier topology can strand capacity after an expansion.</p>\n<p><strong>Pitfall</strong>: <em>Treating all GPU-hours as equal when measuring utilization.</em></p>\n<p>An unlabeled \"GPU utilization\" percentage can conflate allocation with activity or useful work. For example, <code>[UtilizationSnapshotPitfall.assigned_pct_str]</code> of fleet capacity might be assigned to jobs while <code>[UtilizationSnapshotPitfall.incomplete_pct_str]</code> of the fleet sits in groups still waiting for their remaining members and another <code>[UtilizationSnapshotPitfall.input_wait_pct_str]</code> waits for input. Only <code>[UtilizationSnapshotPitfall.complete_pct_str]</code> is then allocated to complete groups, and at most <code>[UtilizationSnapshotPitfall.executing_pct_str]</code> executes useful training in that snapshot. Such a breakdown comes from scheduler and runtime evidence, which an activity counter cannot supply. The allocated, active, and productive tiers of @sec-fleet-orchestration-resource-accounting keep these measurements distinct, with productive capacity tied to a stated workload objective and the job's fault-free rate.</p>\n<p><strong>Fallacy</strong>: <em>Gang scheduling is always necessary for distributed training.</em></p>\n<p>Gang scheduling prevents partial-allocation deadlock for a rigid synchronous group, but the required group need not equal the job's maximum requested size. Asynchronous workers may progress independently, while elastic training can begin with its minimum viable gang and resize at supported boundaries. Independent hyperparameter trials can also run separately. The scheduler gains flexibility by admitting the actual unit of progress, while preserving atomic allocation wherever synchronous dependencies require it. Changes to worker count or synchronization policy still require convergence validation.</p>\n<p><strong>Pitfall</strong>: <em>Setting static quotas based on peak demand.</em></p>\n<p>Organizations commonly set team quotas to handle worst-case demand, reasoning that teams need guaranteed access during crunch periods. If Team A's peak demand is 500 GPUs and Team B's is 300 GPUs, the cluster needs 800 GPUs with static quotas. In practice, peaks rarely coincide. A 600-GPU cluster can accommodate either peak when the other team's simultaneous demand leaves enough capacity, but it cannot guarantee both peaks concurrently. Hierarchical fair-share with borrowing uses that statistical opportunity only when the declared guarantees fit physical capacity and borrowed work can yield within the reclamation contract. In this example, sizing static quotas to the sum of the peaks provisions 800 GPUs where a 600-GPU shared cluster with borrowing covers either peak. The extra 200, a quarter of the larger cluster, are guarantees that sit unused whenever the peaks do not coincide.</p>\n<p><strong>Fallacy</strong>: <em>Spot instances are always cheaper for training.</em></p>\n<p>Actual savings depend on the billed overhead each interruption adds, not on the scenario's <code>[FleetSpotPricing.discount_lo_num_str]</code> to <code>[FleetSpotPricing.discount_hi_pct_str]</code> discount band. Consider <code>[SpotDiscountFallacy.ckpt_attr_str]</code> checkpoint overhead to slow storage and <code>[SpotDiscountFallacy.restart_attr_str]</code> restart overhead to reacquire capacity and reload, far longer than a restart on a cluster's own file system, totaling <code>[SpotDiscountFallacy.lost_str]</code> of billed nonproductive time per event. If each event follows <code>[SpotDiscountFallacy.interval_str]</code> of retained training progress, the nominal <code>[SpotDiscountFallacy.nominal_str]</code> discount becomes about <code>[SpotDiscountFallacy.effective_str]</code> savings under the fixed-allocation model. This illustration assumes a successful save and no replay; a real interruption budget must also include discarded progress when the save cannot finish. The scheduler must separately account for unbilled capacity waits when evaluating deadlines. Sufficient billed overhead can erase the discount, regardless of the advertised rate.</p>\n<p><strong>Pitfall</strong>: <em>Ignoring topology when scheduling distributed training.</em></p>\n<p>Schedulers that ignore connectivity can place communication-intensive groups across paths with less available bandwidth or more contention. On a fleet with NVLink confined to each node, spreading a tensor-parallel group across nodes moves its traffic onto the inter-node fabric; other hardware can expose larger NVLink domains. Crossing a spine switch does not itself prove congestion, so the placement decision must compare effective path capacity and competing traffic. A measured throughput penalty accumulates over a long run and may exceed the delay of waiting for a more suitable allocation. The scheduler must weigh that gain against queue delay and fragmentation.</p>\n<p><strong>Pitfall</strong>: <em>Using elastic training to avoid gang-scheduling decisions.</em></p>\n<p>Elastic training complements gang scheduling by moving between viable execution groups. With a fixed 8-way tensor-parallel layout, each group still requires eight workers; changing the number of data-parallel replicas does not relax that requirement. A runtime that changes the tensor or pipeline layout must also redistribute state and establish a new viable group. The scheduler must honor the supported resize granularity, atomic admission requirements, and placement budget for each configuration. Elasticity adds feasible choices; it does not make an incomplete group productive or an arbitrary placement efficient.</p>\n<p><strong>Pitfall</strong>: <em>Treating high utilization as proof of cluster health.</em></p>\n<p>A high allocated-GPU percentage does not establish that the cluster has enough headroom to admit new work promptly, because waiting time climbs steeply as offered load nears capacity (@fig-utilization-paradox). That queueing model does not turn a GPU-busy percentage into a prediction for a gang-scheduled fleet. Real headroom targets depend on arrival bursts, job sizes, placement constraints, and the queue-delay or serving-latency objective. Measuring those outcomes instead of applying a universal utilization threshold keeps platform teams from optimizations that improve a dashboard metric while delaying the work the fleet exists to complete.</p>\n<h2 id=\"sec-55\" class=\"cs-h2\">Summary</h2>\n<p>Fleet orchestration turns data center capacity into useful ML work by deciding which jobs hold which accelerators, where, and for how long. Orchestration spends Coordination, the third axis of C³, so that Compute and Communication capacity turn into useful progress. In Fleet Law terms (@eq-fleet-law), placement sets the communication term $\\CommunicationTime(\\DeviceCount)$ of every step, and preemption and recovery, amortized over the run, enter the coordination term $\\SynchronizationTime(\\DeviceCount)$. Queue wait and gang admission are coordination costs too, but they delay the first step rather than lengthening any step, so they appear in end-to-end completion time rather than in the per-step Fleet Law. Multi-tenancy and quota policy decide how much of that time allocated compute spends doing useful work. Hardware capability sets the feasible choices; the scheduler turns those choices into useful allocations by preserving ownership, coordinating recovery, and matching placement to workload demand.</p>\n<p>Feasibility is the first filter. Gang size, topology locality, multi-dimensional fit, and accelerator compatibility decide which allocations a job can actually run, and only then can a fairness policy choose among them (principle \\ref{pri-feasibility-before-fairness}). Quota borrowing extends the same reasoning across teams, since a guarantee is worth what the platform can reclaim within its response-time objective rather than the number printed on the quota.</p>\n<p>Placement changes the physical paths available to a workload. Aligning model parallelism with the network hierarchy reduces exposed communication when placement is the limiting constraint, but it cannot create fabric capacity that is not there. Elastic resizing and spot capacity widen the set of feasible choices by trading worker continuity for flexibility and price. ML-aware schedulers sharpen the choice among them with workload signals such as attained service, iteration boundaries, finish-time ratios, and goodput. Every one of these levers pays a transition or integration cost that must be measured against the progress it buys.</p>\n<p>At serving time, the fleet scheduler preserves a capacity envelope of indivisible replicas with SLO headroom and moves the training-serving boundary on forecast demand, holding ready headroom for what the forecast misses. Request-level routing and batching stay with the serving system. When that envelope, the quotas around it, or the placements inside it go wrong, the visible symptom is usually a full queue beside idle accelerators. In practice, the root cause is more often a policy written for an earlier fleet than a defect in the scheduling algorithm.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Takeaways</div>\n<ul class=\"cs-list\">\n<li><strong>Distributed scheduling is hard</strong>: Cluster scheduling must coordinate allocation ownership across machines despite partial failures, network partitions, and stale observations. Control planes balance prompt recovery against the risk of authorizing a replacement while an old worker still runs.</li>\n<li><strong>Gang scheduling prevents deadlock but reduces flexibility</strong>: Gang scheduling gives rigid execution groups atomic resource allocation to prevent hold-and-wait deadlocks, while backfilling and elastic resizing recover flexibility within the job's minimum viable gang and transition constraints.</li>\n<li><strong>Fairness is measured over feasible bundles</strong>: DRF equalizes each tenant's dominant normalized share across GPUs, CPU, memory, and network, but only among bundles that already pass gang, topology, and compatibility constraints (principle \\ref{pri-feasibility-before-fairness}). Slowdown and maximum feasible wait test whether the resulting policy avoids delay and starvation, and a quota guarantee holds only as far as lent capacity can be reclaimed in time.</li>\n<li><strong>Topology determines performance</strong>: Where GPUs are placed within the cluster hierarchy changes the communication paths available to a job. Locality can reduce exposed communication, but waiting for a compact placement also costs time; compare end-to-end completion rather than iteration throughput alone.</li>\n<li><strong>Elastic and interruptible capacity must repay its transitions</strong>: A forced preemption or spot interruption discards work since the last durable checkpoint and then pays reload and warmup, while a resize pauses the job. A resize pays only if the new scale persists long enough to amortize that pause, and spot capacity saves money only while the spot price, scaled by the ratio of billed to retained productive time, stays below the on-demand price.</li>\n<li><strong>Scheduling signals must match the objective</strong>: Workload characteristics support different improvements: attained service addresses runtime uncertainty, iteration boundaries reduce interruption cost, finish-time ratios expose unfair delay, and goodput guides adaptive allocation. Each policy requires validation against the fleet's workload mix and recovery costs.</li>\n<li><strong>Useful utilization creates economic capacity</strong>: Reducing avoidable idle time, often by updating policies written for an earlier fleet rather than by changing the scheduling algorithm, can deliver more useful work from an existing fleet. Distinguish allocated, active, and productive capacity before valuing an improvement, and preserve the headroom required for recovery and latency targets.</li>\n</ul>\n</div>\n<p>Placing a tensor-parallel gang makes the displacement of overhead (principle \\ref{pri-conservation-overhead}) concrete. Co-locating the gang keeps its collectives on NVLink and shrinks the exposed communication of every step, but the scheduler pays for that locality in coordination time while it waits for a feasible contiguous allocation. The bottleneck moves from collective bandwidth to queue delay or fragmentation rather than disappearing, so the right placement is the one that minimizes end-to-end completion time, not iteration time alone.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Chapter Connection</div>\n<p>An allocation shows that a job holds capacity, not that the capacity produces useful work. A training job can hold a complete allocation while it restarts, waits for input, or exposes communication in every step. A serving replica can hold a full node while its decode steps stream weights and leave most of its arithmetic idle. The productive tier says how much of an allocation became useful work but not which part of a job's life lost the rest. The owners of scheduling, recovery, and execution therefore each see their own loss, and none can see which is largest. Those separate losses become one product whose factors can be compared once every hour of capacity is followed from the moment the fleet offers it until it becomes useful work, with each loss charged to the boundary where it occurs.</p>\n</div>\n<p>↪ How much of an allocation becomes useful work, and whether scheduling, runtime, or the program loses the rest, is developed in @sec-performance-engineering.</p>\n<pre class=\"cs-code\"><code>\\part{key:vol2_deployment}</code></pre>", "quizzes": [{"section": "The Scheduling Problem", "type": "MCQ", "question": "In the Kalos language-model cluster trace, most jobs requested a single GPU yet consumed a tiny share of GPU time, while jobs of 256 or more GPUs were a few percent of submissions and consumed nearly all GPU time. What does this distribution imply for judging a scheduling policy?", "choices": ["Judge the policy by job count alone, because most users submit small jobs.", "Judge the policy by GPU-hours alone, because large jobs hold nearly all of the capacity.", "Judge the policy under both views, because small jobs set most users' waits while a few large gangs hold most of the capacity.", "Treat the distribution as an artifact of one cluster, because production fleets have uniform job sizes."], "answer": "The correct answer is C. Counted by jobs, the cluster is a stream of small experiments whose users feel queue delay; counted by GPU-hours, it is a few large gangs that decide packing, reservation, and preemption. A policy tuned to either view alone harms the other. Job count alone ignores where the capacity goes, GPU-hours alone ignores most users' experience, and the trace shows this mix is the normal production case rather than an artifact."}, {"section": "The Scheduling Problem", "type": "SHORT", "question": "A 10,000-GPU cluster raises utilization from 50 percent to 80 percent with no new hardware, holding useful work per active GPU-hour constant. Why does the gain count as 3,000 productive GPU-equivalents but replace 6,000 raw GPUs, and when does it become a cash saving?", "choices": [], "answer": "The productive gain is 10,000 times 0.30, or 3,000 fully utilized GPU-equivalents of useful work. Procurement asks how much hardware that gain replaces: new GPUs run under the old policy would also reach only 50 percent utilization, so delivering 3,000 productive equivalents would take 6,000 raw GPUs. The recovered capacity becomes cash only when it avoids a planned purchase or reduces billed resource time; otherwise it is more useful work from the same investment."}, {"section": "Distributed Scheduling Complexity", "type": "SHORT", "question": "A scheduler control plane separates admission control, placement, and reconciliation. State what each decides, and explain why keeping them separate helps an operator diagnose a job that has not started.", "choices": [], "answer": "Admission decides whether a job may enter the runnable set under quota, priority, gang, and safety constraints. Placement binds an admitted job to a feasible set of nodes given accelerator capability, topology, power, storage, and network capacity. Reconciliation compares desired allocations with observed node and job state and starts, retries, evicts, or fences work until they agree. Separating them distinguishes an admission denial (for example, quota) from a placement failure (no feasible nodes) and from a reconciliation problem (allocation granted but not realized on the nodes)."}, {"section": "Distributed Scheduling Complexity", "type": "MCQ", "question": "A network partition cuts the scheduler off from four nodes running a training job, and their heartbeats time out. What must hold before the scheduler reassigns those nodes' GPUs to another job?", "choices": ["Nothing beyond the timeout, because a missed heartbeat proves the old processes have stopped.", "The old allocation must be revoked with confirmed cleanup or fenced, for example by rejecting stale allocation generations, so the old work cannot keep using or writing through those GPUs.", "The partition must heal first, because no recovery may begin while nodes are unreachable.", "The new job must run at higher priority, because priority resolves conflicting ownership."], "answer": "The correct answer is B. A timeout can trigger recovery, but it does not prove the old execution has stopped; reassigning without revocation or fencing risks two owners of the same devices when the partition heals. Waiting for the partition to heal is one policy choice, not a requirement, and priority orders requests without preventing duplicate ownership."}, {"section": "Scheduling Objectives and Their Conflicts", "type": "FILL", "question": "A one-hour job waits nine hours in the queue and then runs for its isolated runtime of one hour. Its ____, the ratio of its queueing-plus-running time to its isolated runtime, is 10, even if its team eventually receives its nominal GPU share.", "choices": [], "answer": "slowdown. Slowdown divides the time from submission to completion by the isolated runtime, here (9 + 1) / 1 = 10. It measures the delay a job experiences, which resource-share parity cannot reveal."}, {"section": "Scheduling Objectives and Their Conflicts", "type": "SHORT", "question": "Two teams receive equal dominant shares of the fleet over a month, yet one team's jobs routinely wait days. Which measurements expose this unfairness, and why does share parity miss it?", "choices": [], "answer": "Share parity measures allocated resources, not the delay users experience before obtaining results. The scheduler should report the distribution of slowdown by user and job class and the age of the oldest pending feasible job: slowdown exposes unequal delay, and maximum feasible wait exposes starvation risk. A policy can be fair in GPU-hours while unfair in the time users wait."}, {"section": "Core Allocation Constraints", "type": "TF", "question": "True or False: Under Dominant Resource Fairness (DRF), if Team A's workload requires $4\\text{ GPUs}$ and $8\\text{ CPU cores}$ per worker while Team B's workload requires $1\\text{ GPU}$ and $64\\text{ CPU cores}$ per worker on a cluster with $100\\text{ GPUs}$ and $1000\\text{ CPU cores}$, DRF equalizes each team's share of their dominant resource (GPUs for Team A, CPUs for Team B).", "choices": [], "answer": "True. Dominant Resource Fairness (DRF) multi-resource allocation identifies each tenant's dominant resource (the resource type for which the tenant requests the largest fraction of total cluster capacity) and equalizes the dominant shares across all active tenants, ensuring multi-resource equity without allowing single-resource monopolies."}, {"section": "Core Allocation Constraints", "type": "FILL", "question": "When multi-GPU jobs leave unallocated accelerators spread across nodes that cannot be combined to satisfy pending multi-GPU requests due to intra-node interconnect requirements, the cluster suffers from ____.", "choices": [], "answer": "fragmentation (or resource fragmentation). In ML scheduling, fragmentation refers to stranded, non-contiguous capacity across nodes that individually satisfy no pending job, despite the aggregate free GPU count being theoretically sufficient."}, {"section": "Orchestration Paradigms", "type": "MCQ", "question": "What is the fundamental difference in control philosophy between Slurm and Kubernetes when managing distributed ML training workloads?", "choices": ["Slurm relies on continuous reconciliation loops against desired state stored in etcd, whereas Kubernetes executes imperative one-time allocation scripts via a centralized daemon.", "Slurm uses peer-to-peer gossip protocols to schedule tasks across nodes, whereas Kubernetes enforces hierarchical master-slave token ring passing.", "Slurm employs an imperative allocation model where users request explicit physical resources guaranteed at launch, whereas Kubernetes uses a declarative model where controllers continuously reconcile observed cluster state toward declared desired state.", "Slurm schedules containerized microservices with dynamic horizontal auto-scaling, whereas Kubernetes only supports uncontainerized bare-metal MPI processes."], "answer": "The correct answer is C. Slurm originates from HPC batch systems and uses an imperative model (sbatch requests explicit resources like `--gres=gpu:8 --nodes=4`), providing authoritative upfront allocation. Kubernetes uses a declarative model where controllers continuously observe actual state and execute reconciliation loops to converge toward desired state (e.g., Pods, Deployments). The option swapping Slurm and Kubernetes mechanisms reverses their core architectures. The gossip protocol alternative invents a non-existent scheduling model for Slurm. The containerization claim reverses the platforms' primary native workload types."}, {"section": "Orchestration Paradigms", "type": "MCQ", "question": "Kubernetes' default scheduler places a 64-pod training job one pod at a time, and the cluster has room for only 60 of the pods. How does a PodGroup with a minimum membership of 64 change the outcome?", "choices": ["The scheduler binds the first 60 pods immediately and starts training with a smaller communication group, adding the last 4 pods as capacity frees.", "The scheduler tentatively reserves placements but binds no pod until all 64 members are placed, releasing every reservation if the attempt fails or times out.", "The scheduler preempts every lower-priority pod in the cluster until 64 GPUs are free, regardless of priority-class settings.", "The PodGroup guarantees that all 64 containers start at the same instant, so the framework no longer needs to establish its communication group."], "answer": "The correct answer is B. A PodGroup turns admission into a group decision. The scheduler reserves placements as it finds them but binds none until the minimum membership is placed, and it releases the reservations on failure or timeout, so 60 pods never hold GPUs while waiting for 4 more. Binding 60 pods recreates the partial allocation that strands capacity, and preemption follows priority-class policy rather than group admission. Group admission also does not make launches simultaneous; the framework must still form its communication group."}, {"section": "Topology-Aware Scheduling", "type": "MCQ", "question": "When scheduling a 3D-parallel large language model across a multi-rack GPU cluster, how should Tensor Parallelism (TP), Pipeline Parallelism (PP), and Data Parallelism (DP) be mapped across the topology hierarchy to maximize throughput?", "choices": ["Map DP strictly within intra-node NVLink domains, TP across inter-rack spine switches, and PP across rail-aligned network switches.", "Map PP strictly within intra-node NVLink domains, DP across Top-of-Rack switches, and TP across multi-hop spine switches.", "Map TP to the highest-bandwidth domain, place PP stages along suitable low-contention paths, and align corresponding DP shards with network rails while checking available capacity.", "Map TP, PP, and DP uniformly at random across all available nodes to balance switch thermal loads across the datacenter fabric."], "answer": "The correct answer is C. Frequent tensor-parallel exchanges favor the highest-bandwidth domain, which is not universally limited to one node. Pipeline boundaries and data-parallel groups must then be mapped to the actual topology and traffic pattern. Same-rack placement and rail alignment can help, but neither guarantees uncongested bandwidth. Reversing bandwidth priorities or choosing random placement ignores the communication requirements."}, {"section": "Topology-Aware Scheduling", "type": "MCQ", "question": "A persistent degraded switch path lowers measured end-to-end training throughput by 30 percent. A checkpoint-and-migration pause would take 10 minutes, healthy replacement capacity is available, and days of training remain. What is the appropriate orchestration response?", "choices": ["Continue running the job indefinitely because a 10-minute checkpoint-and-reschedule migration would cost more compute than a 30% slowdown over a multi-week run.", "Rely on the GPU driver to disable NVLink and route all tensor-parallel traffic through host memory over PCIe.", "Trigger a performance-aware topology quarantine via taints or drain states, checkpoint the running job, and migrate it to healthy nodes where the break-even time is under an hour.", "Terminate the job and permanently de-allocate all 10,000 GPUs in the datacenter until all network transceivers are manually replaced."], "answer": "The correct answer is C. Quarantine the degraded path and migrate onto verified healthy capacity. At a measured 30-percent end-to-end throughput loss, recovering the work forgone during a 10-minute pause takes about 23 minutes of subsequent healthy execution relative to staying on the degraded placement, or about 33 minutes counting the pause. This payback uses job throughput, not merely a collective microbenchmark, and assumes the slowdown would persist."}]};
